-- ----------------------------
-- Table structure for ai_conversation_history
-- ----------------------------
DROP TABLE IF EXISTS `ai_conversation_history`;
CREATE TABLE `ai_conversation_history`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '会话ID',
  `bank_id` bigint NULL DEFAULT NULL COMMENT '关联的题库ID',
  `role` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '角色：user/assistant/system',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '对话内容',
  `message_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'chat' COMMENT '消息类型：chat/generate/analyze',
  `metadata` json NULL COMMENT '元数据（如关联的题目ID等）',
  `token_count` int NULL DEFAULT NULL COMMENT 'Token数量（估算）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_session`(`user_id` ASC, `session_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI对话历史持久化表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_conversation_history
-- ----------------------------

-- ----------------------------
-- Table structure for ai_generate_history
-- ----------------------------
DROP TABLE IF EXISTS `ai_generate_history`;
CREATE TABLE `ai_generate_history`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `bank_id` bigint NULL DEFAULT NULL COMMENT '关联的题库ID（可为空）',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会话ID，用于关联同一轮对话',
  `request_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '请求类型：question（普通题）/composite（组合题）',
  `question_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '题型：single/multiple/judge/fill/essay',
  `knowledge_point` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '知识点/出题要求',
  `request_count` int NULL DEFAULT 5 COMMENT '请求生成数量',
  `generated_count` int NULL DEFAULT 0 COMMENT '实际生成数量',
  `imported_count` int NULL DEFAULT 0 COMMENT '最终导入数量',
  `provider` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'zhipuai' COMMENT '使用的AI模型：zhipuai/deepseek',
  `request_params` json NULL COMMENT '完整请求参数（JSON格式）',
  `response_summary` json NULL COMMENT '响应摘要（题目ID列表、知识点等）',
  `duration_ms` int NULL DEFAULT NULL COMMENT '请求耗时（毫秒）',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态：1成功 0失败',
  `error_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_bank_id`(`bank_id` ASC) USING BTREE,
  INDEX `idx_session_id`(`session_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI出题历史记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_generate_history
-- ----------------------------

-- ----------------------------
-- Table structure for bank_context_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `bank_context_snapshot`;
CREATE TABLE `bank_context_snapshot`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `bank_id` bigint NOT NULL COMMENT '题库ID',
  `total_questions` int NULL DEFAULT 0 COMMENT '题目总数',
  `question_type_distribution` json NULL COMMENT '题型分布，如{\"single\":10,\"multiple\":5}',
  `knowledge_points` json NULL COMMENT '知识点列表（从题目中提取）',
  `difficulty_distribution` json NULL COMMENT '难度分布',
  `last_question_time` datetime NULL DEFAULT NULL COMMENT '最后添加题目的时间',
  `snapshot_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '快照哈希，用于判断是否需要更新',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bank_id`(`bank_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '题库上下文快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of bank_context_snapshot
