DROP TABLE IF EXISTS `leave_message`;
CREATE TABLE `leave_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '留言ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
