-- ----------------------------
-- Table structure for note
-- ----------------------------
DROP TABLE IF EXISTS `note`;
CREATE TABLE `note`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '笔记ID，主键',
  `user_id` bigint NOT NULL COMMENT '所属用户ID',
  `category_id` bigint NOT NULL COMMENT '所属分类ID，关联 note_category.id，表示该笔记属于哪个分类（如“个人笔记”）',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '笔记标题',
  `filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原始文件名，如“学习计划.md”',
  `markdown_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'Markdown 内容',
  `word_count` int NULL DEFAULT 0 COMMENT '字数统计',
  `tags` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签，逗号分隔，如：Java,学习',
  `is_public` tinyint(1) NULL DEFAULT 0 COMMENT '是否公开：0-私有，1-公开',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'draft' COMMENT '状态：draft-草稿，published-已发布，archived-已归档',
  `sort_order` int NULL DEFAULT 0 COMMENT '笔记在当前分类内的排序权重',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `public_section_id` bigint NULL DEFAULT NULL COMMENT '公开分区ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_category_title`(`user_id` ASC, `category_id` ASC, `title` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_category_id`(`category_id` ASC) USING BTREE,
  INDEX `idx_user_status`(`user_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户笔记主表，每篇笔记必须归属于一个用户自定义的分类' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of note
-- ----------------------------

-- ----------------------------
-- Table structure for note_category
-- ----------------------------
DROP TABLE IF EXISTS `note_category`;
CREATE TABLE `note_category`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID，主键',
  `user_id` bigint NOT NULL COMMENT '所属用户ID，关联 sys_user.id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称，如“个人笔记”、“工作文档”，由用户自定义',
  `order_num` int NULL DEFAULT 0 COMMENT '排序序号，用于前端拖拽调整分类顺序',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_name`(`user_id` ASC, `name` ASC) USING BTREE COMMENT '同一用户下分类名称不能重复',
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '笔记分类表，支持用户自定义单层分类，每个分类下可包含多篇笔记' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of note_category
-- ----------------------------

-- ----------------------------
-- Table structure for note_click_record
-- ----------------------------
DROP TABLE IF EXISTS `note_click_record`;
CREATE TABLE `note_click_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `note_id` bigint NOT NULL COMMENT '笔记ID',
  `user_id` bigint NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '点击时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_note_user_date`(`note_id` ASC,  ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1185 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '笔记点击记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of note_click_record
-- ----------------------------

-- ----------------------------
-- Table structure for note_comment
-- ----------------------------
DROP TABLE IF EXISTS `note_comment`;
CREATE TABLE `note_comment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `note_id` bigint NOT NULL COMMENT '所属笔记ID',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '父评论ID，NULL=一级评论',
  `reply_to_user_id` bigint NULL DEFAULT NULL COMMENT '回复的目标用户ID',
  `user_id` bigint NOT NULL COMMENT '评论用户ID',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评论内容',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态：1-正常 0-已删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_note_id`(`note_id` ASC) USING BTREE,
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_reply_to_user_id`(`reply_to_user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '笔记评论表' ROW_FORMAT = Dynamic;

