-- ----------------------------
-- Table structure for user_ai_preference
-- ----------------------------
DROP TABLE IF EXISTS `user_ai_preference`;
CREATE TABLE `user_ai_preference`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `prefer_subject` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '偏好的科目（如Java、Python）',
  `prefer_question_types` json NULL COMMENT '偏好的题型列表，JSON数组如[\"single\",\"multiple\"]',
  `prefer_difficulty` tinyint NULL DEFAULT 2 COMMENT '偏好难度：1简单 2中等 3困难 4极难',
  `prefer_options_count` tinyint NULL DEFAULT 4 COMMENT '选择题偏好选项数量',
  `prefer_with_analysis` tinyint NULL DEFAULT 1 COMMENT '是否需要解析：0否 1是',
  `common_knowledge_points` json NULL COMMENT '常考知识点，JSON数组',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户AI偏好设置表' ROW_FORMAT = Dynamic;

