-- Records of user_ai_preference
-- ----------------------------

-- ----------------------------
-- Table structure for user_bank_favorite
-- ----------------------------
DROP TABLE IF EXISTS `user_bank_favorite`;
CREATE TABLE `user_bank_favorite`  (
  `favorite_id` bigint NOT NULL AUTO_INCREMENT COMMENT '收藏ID',
  `user_id` bigint NOT NULL COMMENT '用户ID（关联sys_user.user_id）',
  `bank_id` bigint NOT NULL COMMENT '题库ID（关联question_bank.id）',
  `notes` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '收藏备注',
  `tags` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '标签（逗号分隔，如：高频,重点）',
  `sort_order` int NULL DEFAULT 0 COMMENT '排序（用户自定义）',
  `is_starred` tinyint NULL DEFAULT 0 COMMENT '是否标星：0否 1是',
  `last_study_time` datetime NULL DEFAULT NULL COMMENT '最后学习时间',
  `study_count` int NULL DEFAULT 0 COMMENT '学习次数',
  `favorite_status` tinyint NULL DEFAULT 1 COMMENT '状态：1正常收藏 0取消收藏',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`favorite_id`) USING BTREE,
  UNIQUE INDEX `uk_user_bank`(`user_id` ASC, `bank_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_bank_id`(`bank_id` ASC) USING BTREE,
  INDEX `idx_user_status`(`user_id` ASC, `favorite_status` ASC) USING BTREE,
  INDEX `idx_star_time`(`is_starred` ASC, `last_study_time` DESC) USING BTREE,
  CONSTRAINT `fk_user_bank_favorite_bank` FOREIGN KEY (`bank_id`) REFERENCES `question_bank` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_bank_favorite_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户题库收藏表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_bank_favorite
-- ----------------------------

-- ----------------------------
-- Table structure for user_note_favorite
-- ----------------------------
DROP TABLE IF EXISTS `user_note_favorite`;
CREATE TABLE `user_note_favorite`  (
  `favorite_id` bigint NOT NULL AUTO_INCREMENT COMMENT '收藏ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `note_id` bigint NOT NULL COMMENT '笔记ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  PRIMARY KEY (`favorite_id`) USING BTREE,
  UNIQUE INDEX `uk_user_note`(`user_id` ASC, `note_id` ASC) USING BTREE,
  INDEX `idx_note_id`(`note_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户笔记收藏表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_note_favorite
-- ----------------------------

-- ----------------------------
-- Table structure for user_question_error
-- ----------------------------
DROP TABLE IF EXISTS `user_question_error`;
CREATE TABLE `user_question_error`  (
  `error_id` bigint NOT NULL AUTO_INCREMENT COMMENT '错题记录ID',
  `user_id` bigint NOT NULL COMMENT '用户ID（关联sys_user.user_id）',
  `question_id` bigint NOT NULL COMMENT '题目ID（关联question_main.id）',
  `bank_id` bigint NOT NULL COMMENT '所属题库ID（冗余字段，提升查询性能）',
  `error_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次做错时间',
  `last_error_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最近一次做错时间',
  `error_count` int NULL DEFAULT 1 COMMENT '累计错误次数',
  `notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `tags` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '标签（逗号分隔，如：易错,公式记错,审题不清）',
  `difficulty_rating` tinyint NULL DEFAULT NULL COMMENT '用户自评难度：1-5星',
  `review_count` int NULL DEFAULT 0 COMMENT '已复习次数',
  `last_review_time` datetime NULL DEFAULT NULL COMMENT '最后复习时间',
  `next_review_time` datetime NULL DEFAULT NULL COMMENT '下次复习时间（基于记忆曲线）',
  `is_mastered` tinyint NULL DEFAULT 0 COMMENT '是否已掌握：0未掌握 1已掌握',
  `status` tinyint NULL DEFAULT 1 COMMENT '记录状态：1活跃（错题中） 2已掌握归档 0无效/删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`error_id`) USING BTREE,
  UNIQUE INDEX `uk_user_question`(`user_id` ASC, `question_id` ASC) USING BTREE COMMENT '每个用户对每道题只有一条错题记录',
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_question_id`(`question_id` ASC) USING BTREE,
  INDEX `idx_bank_id`(`bank_id` ASC) USING BTREE,
  INDEX `idx_user_status`(`user_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_next_review`(`user_id` ASC, `next_review_time` ASC) USING BTREE,
  INDEX `idx_error_count`(`user_id` ASC, `error_count` ASC) USING BTREE,
  INDEX `idx_review_schedule`(`user_id` ASC, `status` ASC, `next_review_time` ASC) USING BTREE,
  CONSTRAINT `fk_user_error_bank` FOREIGN KEY (`bank_id`) REFERENCES `question_bank` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_error_question` FOREIGN KEY (`question_id`) REFERENCES `question_main` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_error_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户错题记录表（支持复习与掌握跟踪）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_question_error
-- ----------------------------

-- ----------------------------
-- Table structure for user_question_favorite
-- ----------------------------
DROP TABLE IF EXISTS `user_question_favorite`;
CREATE TABLE `user_question_favorite`  (
  `favorite_id` bigint NOT NULL AUTO_INCREMENT COMMENT '收藏ID',
  `user_id` bigint NOT NULL COMMENT '用户ID（关联sys_user.user_id）',
  `question_id` bigint NOT NULL COMMENT '题目ID（关联question_main.id）',
  `bank_id` bigint NOT NULL COMMENT '所属题库ID（冗余字段，方便查询）',
  `notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `tags` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '标签（逗号分隔，如：易错,高频,难点）',
  `difficulty_rating` tinyint NULL DEFAULT NULL COMMENT '难度评级：1-5星',
  `error_times` int NULL DEFAULT 0 COMMENT '错误次数',
  `correct_times` int NULL DEFAULT 0 COMMENT '正确次数',
  `last_review_time` datetime NULL DEFAULT NULL COMMENT '最后复习时间',
  `next_review_time` datetime NULL DEFAULT NULL COMMENT '下次复习时间（记忆曲线）',
  `review_count` int NULL DEFAULT 0 COMMENT '复习次数',
  `is_starred` tinyint NULL DEFAULT 0 COMMENT '是否标星：0否 1是（重点题目）',
  `favorite_status` tinyint NULL DEFAULT 1 COMMENT '状态：1正常收藏 2已掌握 3待复习 0取消收藏',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`favorite_id`) USING BTREE,
  UNIQUE INDEX `uk_user_question`(`user_id` ASC, `question_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_question_id`(`question_id` ASC) USING BTREE,
  INDEX `idx_bank_id`(`bank_id` ASC) USING BTREE,
  INDEX `idx_user_status`(`user_id` ASC, `favorite_status` ASC) USING BTREE,
  INDEX `idx_next_review`(`user_id` ASC, `next_review_time` ASC) USING BTREE,
  INDEX `idx_star_status`(`is_starred` ASC, `favorite_status` ASC) USING BTREE,
  INDEX `idx_review_schedule`(`user_id` ASC, `favorite_status` ASC, `next_review_time` ASC) USING BTREE,
  CONSTRAINT `fk_user_question_favorite_bank` FOREIGN KEY (`bank_id`) REFERENCES `question_bank` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_question_favorite_question` FOREIGN KEY (`question_id`) REFERENCES `question_main` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_question_favorite_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户题目收藏表（支持复习功能）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_question_favorite
-- ----------------------------

-- ----------------------------
-- Table structure for user_question_marked
-- ----------------------------
DROP TABLE IF EXISTS `user_question_marked`;
CREATE TABLE `user_question_marked`  (
  `marked_id` bigint NOT NULL AUTO_INCREMENT COMMENT '斩题ID',
  `user_id` bigint NOT NULL COMMENT '用户ID（关联sys_user.user_id）',
  `question_id` bigint NOT NULL COMMENT '题目ID（关联question_main.id）',
  `bank_id` bigint NOT NULL COMMENT '所属题库ID（冗余字段，方便查询）',
  `notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `tags` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '标签（逗号分隔，如：难题,重点,易错,技巧）',
  `marked_type` tinyint NULL DEFAULT 1 COMMENT '斩题类型：1错题 2难题 3重点 4易错 5技巧',
  `difficulty_level` tinyint NULL DEFAULT NULL COMMENT '难度等级：1简单 2中等 3困难 4极难',
  `error_times_before_mark` int NULL DEFAULT 0 COMMENT '斩题前的错误次数',
  `correct_times_before_mark` int NULL DEFAULT 0 COMMENT '斩题前的正确次数',
  `review_count` int NULL DEFAULT 0 COMMENT '复习次数',
  `last_review_time` datetime NULL DEFAULT NULL COMMENT '最后复习时间',
  `next_review_time` datetime NULL DEFAULT NULL COMMENT '下次复习时间',
  `is_mastered` tinyint NULL DEFAULT 0 COMMENT '是否掌握：0未掌握 1已掌握',
  `mastery_date` datetime NULL DEFAULT NULL COMMENT '掌握日期',
  `marked_status` tinyint NULL DEFAULT 1 COMMENT '状态：1正常 0删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '斩题时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`marked_id`) USING BTREE,
  UNIQUE INDEX `uk_user_question`(`user_id` ASC, `question_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_question_id`(`question_id` ASC) USING BTREE,
  INDEX `idx_bank_id`(`bank_id` ASC) USING BTREE,
  INDEX `idx_user_status`(`user_id` ASC, `marked_status` ASC) USING BTREE,
  INDEX `idx_marked_type`(`user_id` ASC, `marked_type` ASC) USING BTREE,
  INDEX `idx_difficulty`(`user_id` ASC, `difficulty_level` ASC) USING BTREE,
  INDEX `idx_mastered`(`user_id` ASC, `is_mastered` ASC) USING BTREE,
  INDEX `idx_next_review`(`user_id` ASC, `next_review_time` ASC) USING BTREE,
  INDEX `idx_comprehensive`(`user_id` ASC, `marked_status` ASC, `is_mastered` ASC, `next_review_time` ASC) USING BTREE,
  CONSTRAINT `fk_user_question_marked_bank` FOREIGN KEY (`bank_id`) REFERENCES `question_bank` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_question_marked_question` FOREIGN KEY (`question_id`) REFERENCES `question_main` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_question_marked_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户斩题表（重点攻克题目）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_question_marked
-- ----------------------------

-- ----------------------------
-- Table structure for word_books
-- ----------------------------
DROP TABLE IF EXISTS `word_books`;
CREATE TABLE `word_books`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL DEFAULT 1 COMMENT '用户ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单词本名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '单词本描述',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_default` tinyint(1) NULL DEFAULT 0 COMMENT '是否为默认单词本',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除标识: 0-未删除, 1-已删除',
  `deleted_time` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `word_book_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `user_id`(`user_id` ASC) USING BTREE,
  CONSTRAINT `word_books_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单词本表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of word_books
-- ----------------------------

-- ----------------------------
-- Table structure for words
-- ----------------------------
DROP TABLE IF EXISTS `words`;
CREATE TABLE `words`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `english` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '英文单词',
  `word_type` tinyint NULL DEFAULT 1 COMMENT '类型: 1-单词, 2-词组, 3-句子',
  `chinese` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '中文意思',
  `phonetic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '音标',
  `is_mastered` tinyint NULL DEFAULT 0 COMMENT '是否掌握: 0-未掌握, 1-已掌握',
  `review_count` int NULL DEFAULT 0 COMMENT '复习次数',
  `last_review_time` timestamp NULL DEFAULT NULL COMMENT '最后复习时间',
  `word_book_id` bigint NULL DEFAULT NULL COMMENT '所属单词本ID',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除标识: 0-未删除, 1-已删除',
  `deleted_time` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `word_book_id`(`word_book_id` ASC) USING BTREE,
  CONSTRAINT `words_ibfk_1` FOREIGN KEY (`word_book_id`) REFERENCES `word_books` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 189 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单词表' ROW_FORMAT = DYNAMIC;

