INSERT INTO `note_comment` VALUES (1, 42, NULL, NULL, 1, '文章写得太好了！尤其是 Provide/Inject 那部分，之前一直没搞懂，看了这篇终于理解了！', 1, '2026-04-29 14:30:00');
INSERT INTO `note_comment` VALUES (2, 42, NULL, NULL, 2, 'Props 和 Emits 的表格对比很清晰，对于新手来说很容易理解。', 1, '2026-04-29 14:32:00');
INSERT INTO `note_comment` VALUES (3, 42, NULL, NULL, 103, 'Pinia 部分可以再补充一下 getters 的使用场景吗？', 1, '2026-04-29 14:35:00');
INSERT INTO `note_comment` VALUES (4, 42, NULL, NULL, 1, '自定义指令那部分写得不错，权限指令在后台管理系统中很常用。', 1, '2026-04-29 14:38:00');
INSERT INTO `note_comment` VALUES (5, 42, NULL, NULL, 2, 'Vuex vs Pinia 的对比很直观，终于知道为什么要迁移到 Pinia 了。', 1, '2026-04-29 14:40:00');
INSERT INTO `note_comment` VALUES (6, 42, NULL, NULL, 103, '能不能出一期 Vue 3.4 的新特性？比如 defineModel 的用法？', 1, '2026-04-29 14:42:00');
INSERT INTO `note_comment` VALUES (7, 42, NULL, NULL, 1, '这篇总结得很全面，收藏了！', 1, '2026-04-29 14:45:00');
INSERT INTO `note_comment` VALUES (8, 42, NULL, NULL, 2, '建议加上一个完整的实战例子，比如 Todo 应用演示三种通信方式。', 1, '2026-04-29 14:48:00');
INSERT INTO `note_comment` VALUES (9, 42, NULL, NULL, 103, '想问一下，Provide/Inject 在大型项目中会不会造成数据流混乱？', 1, '2026-04-29 14:50:00');
INSERT INTO `note_comment` VALUES (10, 42, NULL, NULL, 1, '组件的 v-model 部分讲得简洁明了，终于搞懂了双向绑定的本质。', 1, '2026-04-29 14:52:00');
INSERT INTO `note_comment` VALUES (11, 42, 2, 2, 1, '谢谢支持！后面会继续更新更多 Vue3 的实战内容。', 1, '2026-04-29 14:55:00');
INSERT INTO `note_comment` VALUES (12, 42, 2, 2, 103, '同感！Props 的类型推导在 TS 下特别好用。', 1, '2026-04-29 14:56:00');
INSERT INTO `note_comment` VALUES (13, 42, 11, 1, 2, '期待！希望可以多讲讲 composables 的实际应用。', 1, '2026-04-29 14:58:00');
INSERT INTO `note_comment` VALUES (14, 42, 3, 103, 1, '好建议！下次更新我会补充 Pinia getters 的实战例子。', 1, '2026-04-29 15:00:00');
INSERT INTO `note_comment` VALUES (15, 42, 3, 103, 2, '其实 Pinia 的 getters 和 Vuex 用法基本一致，只是语法更简洁。', 1, '2026-04-29 15:02:00');
INSERT INTO `note_comment` VALUES (16, 42, 14, 1, 103, '太好了，期待更新！特别是结合 TypeScript 的写法。', 1, '2026-04-29 15:05:00');
INSERT INTO `note_comment` VALUES (17, 42, 6, 103, 1, '已经在计划中了！Vue 3.4 的 defineModel 确实简化了很多写法。', 1, '2026-04-29 15:08:00');
INSERT INTO `note_comment` VALUES (18, 42, 17, 1, 103, '期待！什么时候能出？', 1, '2026-04-29 15:10:00');
INSERT INTO `note_comment` VALUES (19, 42, 18, 103, 1, '争取下周就出，敬请关注！', 1, '2026-04-29 15:12:00');
INSERT INTO `note_comment` VALUES (20, 42, 9, 103, 1, '一般建议用 Pinia 做全局状态，Provide/Inject 适合局部组件树。约定好 key 命名就行。', 1, '2026-04-29 15:15:00');
INSERT INTO `note_comment` VALUES (21, 42, 9, 103, 2, '可以用 Symbol 作为 key 来避免命名冲突，这是官方推荐的做法。', 1, '2026-04-29 15:18:00');
INSERT INTO `note_comment` VALUES (22, 42, 20, 1, 103, '学到了！Symbol 确实是个好方案。', 1, '2026-04-29 15:20:00');
INSERT INTO `note_comment` VALUES (23, 42, 4, 1, 2, '自定义指令确实实用，尤其是权限控制场景。', 1, '2026-04-29 15:22:00');
INSERT INTO `note_comment` VALUES (24, 42, 4, 1, 103, '能不能讲讲自定义指令和 composables 的区别？', 1, '2026-04-29 15:25:00');
INSERT INTO `note_comment` VALUES (25, 42, 24, 103, 1, '自定义指令主要用于 DOM 操作，composables 用于逻辑复用，场景不同。后面会出专题。', 1, '2026-04-29 15:28:00');
INSERT INTO `note_comment` VALUES (26, 42, 8, 2, 1, '好建议！后面会出一个完整的 Todo 实战，涵盖三种通信方式。', 1, '2026-04-29 15:30:00');
INSERT INTO `note_comment` VALUES (27, 42, 8, 2, 103, '+1！最好能包含 TypeScript 的写法。', 1, '2026-04-29 15:32:00');
INSERT INTO `note_comment` VALUES (28, 42, 1, 1, 2, '确实，Provide/Inject 配合 readonly 可以避免子组件意外修改数据。', 1, '2026-04-29 15:35:00');
INSERT INTO `note_comment` VALUES (29, 42, 28, 2, 103, '那如果传入的是 reactive 对象，子组件修改会影响父组件吗？', 1, '2026-04-29 15:38:00');
INSERT INTO `note_comment` VALUES (30, 42, 29, 103, 1, '会影响的。建议用 readonly() 包装，或者只传 ref 的 value。', 1, '2026-04-29 15:40:00');
INSERT INTO `note_comment` VALUES (31, 42, 7, 1, 2, '收藏 +1！这篇文章值得反复看。', 1, '2026-04-29 15:42:00');
INSERT INTO `note_comment` VALUES (32, 42, 10, 1, 103, 'v-model 部分确实讲得好，尤其是多个 v-model 绑定的用法。', 1, '2026-04-29 15:45:00');
INSERT INTO `note_comment` VALUES (33, 42, 32, 103, 1, '谢谢！defineModel 在 Vue 3.4 中更加简洁，后面会补充。', 1, '2026-04-29 15:48:00');
INSERT INTO `note_comment` VALUES (34, 42, 5, 2, 1, 'Pinia 相比 Vuex 确实简洁很多，TypeScript 支持也更好。', 1, '2026-04-29 15:50:00');
INSERT INTO `note_comment` VALUES (35, 42, 34, 1, 103, '想问下从 Vuex 迁移到 Pinia 麻烦吗？', 1, '2026-04-29 15:52:00');
INSERT INTO `note_comment` VALUES (36, 42, 35, 103, 1, '不麻烦，Pinia 的 API 和 Vuex 很相似，主要是去掉了 mutations。', 1, '2026-04-29 15:55:00');
INSERT INTO `note_comment` VALUES (37, 42, 36, 1, 2, '补充：Pinia 支持 Option Store 和 Setup Store 两种写法，迁移很灵活。', 1, '2026-04-29 15:58:00');
INSERT INTO `note_comment` VALUES (38, 42, NULL, NULL, 103, '文章中的代码示例很实用，可以直接复制使用！', 1, '2026-04-29 16:00:00');
INSERT INTO `note_comment` VALUES (39, 42, NULL, NULL, 2, '希望能补充一下 Suspense 和 Teleport 的介绍。', 1, '2026-04-29 16:02:00');
INSERT INTO `note_comment` VALUES (40, 42, NULL, NULL, 1, '感谢大家的支持！后续会持续更新 Vue3 进阶系列。', 1, '2026-04-29 16:05:00');
INSERT INTO `note_comment` VALUES (41, 42, 40, 1, 1, '支持大大', 1, '2026-04-29 14:28:28');
INSERT INTO `note_comment` VALUES (42, 42, 41, 1, 1, '感谢支持', 1, '2026-04-29 14:28:37');
