INSERT INTO `question_main` VALUES (135, 1, 1, 2, 'She ______ English for five years.', '', '[\"has studied1111\", \"studied\", \"studies\", \"had studied\"]', 'B', '正确答案：A。现在完成时表示从过去持续到现在的动作。', 0, 0, 2.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (136, 1, 1, 2, 'If I ______ you, I would take the job.', '', '[\"am\", \"is\", \"were\", \"was\"]', 'C', '正确答案：C。虚拟语气中，be 动词用 were。', 0, 1, 2.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (137, 1, 2, 2, 'Which of the following are modal verbs?', '', '[\"can\", \"do\", \"must\", \"be\", \"should\"]', 'A,C,E', '正确答案：A,C,E。情态动词包括 can, must, should 等。', 0, 2, 3.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (138, 1, 3, 2, '\"He don’t like apples.\" is grammatically correct.', '', NULL, 'false', '正确答案：B（错误）。\"He don’t like apples.\" 是错误句，正确应为 \"He doesn’t like apples.\"，故原句错误。', 0, 3, 1.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (139, 1, 4, 2, 'The book is on the ______. (提示：家具)', '', NULL, 'table', '标准答案：table。根据上下文和提示，应填 table。', 0, 4, 2.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (140, 1, 1, 2, 'By the time we arrived, the train ______.', '', '[\"left\", \"had left\", \"leaves\", \"has left\"]', 'B', '正确答案：B。过去完成时表示“过去的过去”。', 0, 5, 2.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (141, 1, 3, 2, 'The word \"information\" is countable.', '', NULL, 'false', '正确答案：B（错误）。\"Information\" 是不可数名词。', 0, 6, 1.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (142, 1, 4, 2, 'She is interested ______ learning French.', '', NULL, 'in', '标准答案：in。固定搭配：be interested in...', 0, 7, 2.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (143, 1, 1, 2, 'Not only ______ late, but also forgot the documents.', '', '[\"he was\", \"was he\", \"did he\", \"he did\"]', 'B', '正确答案：B。Not only 开头，主句倒装，且时态为一般过去时。', 0, 8, 3.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (144, 1, 5, 2, 'Explain the difference between \"affect\" and \"effect\".', '', NULL, 'Affect is usually a verb meaning to influence; effect is usually a noun meaning result.', '参考答案：Affect is usually a verb meaning to influence; effect is usually a noun meaning result.。注意词性和用法区别。', 0, 9, 5.00, '0', '2026-04-11 15:53:57');
INSERT INTO `question_main` VALUES (145, 1, 1, 2, '11', '', '[\"11\", \"11\", \"22\", \"33\"]', 'A', '11', 0, 10, 5.00, '0', '2026-04-11 17:06:29');
INSERT INTO `question_main` VALUES (146, 1, 1, 2, '你好啊', '', '[\"1\", \"2\"]', 'A', '11', 0, 11, 5.00, '0', '2026-04-11 17:11:46');
INSERT INTO `question_main` VALUES (147, 1, 2, 2, '22', '', '[\"11\", \"11\", \"22\"]', 'A,B', '111', 0, 12, 5.00, '0', '2026-04-11 17:13:06');
INSERT INTO `question_main` VALUES (148, 1, 5, 2, '11', '', NULL, '11', '11', 0, 13, 10.00, '0', '2026-04-11 17:14:08');
INSERT INTO `question_main` VALUES (149, 1, 6, 2, '111', '1111', NULL, '', '2222', 1, 14, 5.00, '0', '2026-04-12 20:19:32');
INSERT INTO `question_main` VALUES (150, 1, 6, 2, '阅读下面的短文，从每题所给的选项中选择最佳答案填空。', 'Many people enjoy drinking coffee ___1___ the morning. It helps them wake up and feel more ___2___. However, too much coffee can cause problems like anxiety or trouble sleeping. Experts recommend drinking no more than ___3___ cups per day.', NULL, '', '', 1, 15, 5.00, '0', '2026-04-12 20:22:35');
INSERT INTO `question_main` VALUES (151, 1, 1, 2, 'By the time we got to the cinema, the movie ________ for twenty minutes.', '', '[\"had been running\", \"has been running\", \"ran\", \"was running\"]', 'A', '本题考查过去完成进行时。\'by the time\'引导的时间状语从句表示在过去某一时间点之前已经完成的动作，主句用过去完成时。由于电影一直在放映，所以用过去完成进行时\'had been running\'表示在过去某一时间点之前一直在进行的动作。', 0, 16, 5.00, '0', '2026-04-14 09:12:50');
INSERT INTO `question_main` VALUES (152, 1, 1, 2, 'I ________ my keys. I can\'t find them anywhere.', '', '[\"lost\", \"have lost\", \"was losing\", \"had lost\"]', 'B', '本题考查现在完成时。句子表达的是过去发生的动作对现在造成的结果或影响（找不到钥匙），且强调动作已经完成，所以用现在完成时\'have lost\'。', 0, 17, 5.00, '0', '2026-04-14 09:12:50');
INSERT INTO `question_main` VALUES (153, 1, 1, 2, 'When I arrived at the party, everyone ________ already ________.', '', '[\"had, left\", \"was, leaving\", \"has, left\", \"would, leave\"]', 'B', '本题考查过去完成时。\'when I arrived\'表示过去的时间点，而\'already left\'表示在\'我到达\'之前已经发生的动作，所以需要用过去完成时\'had left\'来表示过去的过去。', 0, 18, 5.00, '0', '2026-04-14 09:12:50');
INSERT INTO `question_main` VALUES (154, 1, 1, 2, 'By the end of this year, we ________ this project for five years.', '', '[\"will be working\", \"will have been working\", \"have worked\", \"had worked\"]', 'B', '本题考查将来完成进行时。\'by the end of this year\'表示将来的时间点，而\'for five years\'表示持续的时间，所以用将来完成进行时\'will have been working\'表示到将来的某一时间点为止已经持续了一段时间的动作。', 0, 19, 5.00, '0', '2026-04-14 09:12:50');
INSERT INTO `question_main` VALUES (155, 1, 1, 2, 'If it ________ tomorrow, we would cancel the picnic.', '', '[\"rains\", \"rained\", \"will rain\", \"would rain222\"]', 'D', '本题考查虚拟语气中与现在事实相反的假设。在if条件状语从句中，表示与现在事实相反的假设时，用过去式（rained），而主句用\'would + 动词原形\'。', 0, 20, 5.00, '0', '2026-04-14 09:12:50');
INSERT INTO `question_main` VALUES (156, 1, 1, 2, '以下哪个是Java的基本数据类型？', '', '[\"String\", \"int\", \"ArrayList\", \"HashMap\"]', 'B', 'int是Java的基本数据类型，而String、ArrayList和HashMap都是引用类型。Java的基本数据类型包括byte、short、int、long、float、double、char和boolean。', 0, 21, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (157, 1, 1, 2, '在Java中，哪个关键字用于创建对象？', '', '[\"new\", \"create\", \"make\", \"construct\"]', 'A', '在Java中，使用new关键字来创建对象。例如：ClassName obj = new ClassName();。create、make和construct都不是Java的关键字。', 0, 22, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (158, 1, 1, 2, 'Java中的接口可以包含以下哪种成员？', '', '[\"实例变量\", \"构造方法\", \"抽象方法\", \"静态代码块\"]', 'C', 'Java接口只能包含抽象方法、常量、默认方法、静态方法和私有方法。接口不能包含实例变量、构造方法或静态代码块。从Java 8开始，接口可以有默认方法和静态方法，但必须有default或static关键字修饰。', 0, 23, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (159, 1, 1, 2, 'Which of the following is the correct past tense form of the verb \'go\'?', '', '[\"goed\", \"went\", \"gone\", \"going\"]', 'B', 'The correct past tense form of \'go\' is \'went\'. \'Goed\' is not a standard English word form. \'Gone\' is the past participle form, and \'going\' is the present participle or gerund form.', 0, 24, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (160, 1, 1, 2, 'What is the comparative form of the adjective \'big\'?', '', '[\"biggest\", \"bigger\", \"more big\", \"biger\"]', 'B', 'For most one-syllable adjectives, we add \'-er\' to form the comparative. So \'big\' becomes \'bigger\'. \'Biggest\' is the superlative form, \'more big\' is incorrect structure, and \'biger\' is misspelled (should be \'bigger\').', 0, 25, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (161, 1, 1, 2, 'Which sentence correctly uses the present perfect tense?', '', '[\"She goes to school yesterday.\", \"She has gone to school.\", \"She is going to school.\", \"She goes to school every day.\"]', 'B', 'The present perfect tense (has/have + past participle) is used for actions that started in the past and continue to the present or have present results. \'She has gone to school\' is correct. The other options are either simple past (\'went\'), present continuous (\'is going\'), or simple present (\'goes\').', 0, 26, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (162, 1, 1, 2, '下列词语中，没有错别字的一项是？', '', '[\"安详\", \"详和\", \"祥瑞\", \"吉祥\"]', 'A', '\'安详\'中的\'详\'是\'安静、平和\'的意思，没有错别字。\'祥和\'中的\'祥\'是\'吉祥\'的意思，不是\'详\'；\'祥瑞\'和\'吉祥\'中的\'祥\'都是\'吉祥\'的意思，但\'祥瑞\'中的\'祥\'没有错，而\'吉祥\'中的\'吉\'也没有错。因此，\'安详\'是没有错别字的选项。', 0, 27, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (163, 1, 1, 2, '下列成语中，没有错别字的一项是？', '', '[\"名列前矛\", \"名列前茅\", \"名列前矛\", \"名列前茅\"]', 'B', '\'名列前茅\'的正确写法是\'名列前茅\'，意思是名次排在前面。\'茅\'指茅草，古代用茅草做旗帜，比喻名次在前。\'矛\'是古代的一种兵器，与成语意思无关。因此，第二个\'名列前茅\'是正确的。', 0, 28, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (164, 1, 1, 2, '下列句子中，没有错别字的一项是？', '', '[\"他做事一丝不苟，从不马虎大意\", \"他做事一丝不苟，从不马虎大义\", \"他做事一丝不苟，从不马虎大意\", \"他做事一丝不苟，从不马虎大义\"]', 'C', '\'马虎大意\'中的\'意\'是\'意思、含义\'的意思，表示做事不细心、不认真。\'大义\'通常指\'大道理、正义\'的意思，与句子语境不符。因此，第三个句子中的\'马虎大意\'是正确的写法。', 0, 29, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (165, 1, 1, 2, '在中文语境中，\'你好\'最常用的含义是？', '', '[\"表示惊讶\", \"表示问候\", \"表示告别\", \"表示感谢\"]', 'B', '\'你好\'是中文中最常用的问候语，用于初次见面或日常打招呼，表示对对方的礼貌和尊重。', 0, 30, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (166, 1, 1, 2, '当你第一次见到某人时，最合适的开场白是？', '', '[\"再见\", \"你好\", \"谢谢\", \"对不起\"]', 'B', '初次见面时，\'你好\'是最恰当的开场白，表示友好和尊重，而其他选项分别表示告别、感谢和道歉，不适合初次见面的场景。', 0, 31, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (167, 1, 1, 2, '在电话通话开始时，通常说的第一句话是？', '', '[\"喂\", \"你好\", \"再见\", \"谢谢\"]', 'B', '在电话通话开始时，使用\'你好\'作为问候语是最礼貌和标准的方式，表示通话开始并准备交流。\'喂\'虽然也常用于电话，但不如\'你好\'正式和礼貌。', 0, 32, 5.00, '0', '2026-04-14 19:27:20');
INSERT INTO `question_main` VALUES (168, 1, 6, 2, '阅读理解', 'Artificial Intelligence in Daily Life\n\nArtificial Intelligence (AI) has become an integral part of our daily lives, often without us even realizing it. From the moment we wake up to when we go to bed, AI technology is working behind the scenes to make our lives easier and more efficient.\n\nIn the morning, many people rely on AI-powered virtual assistants like Siri or Alexa to check the weather, set reminders, or play music. These assistants use natural language processing to understand and respond to our commands. When we commute, navigation apps like Google Maps use AI to analyze traffic patterns and suggest the fastest routes. \n\nAt school, AI tools help students with personalized learning experiences, adapting to individual needs and learning styles. Even entertainment has been transformed by AI, with streaming services using algorithms to recommend movies and shows based on our viewing history.\n\nAs AI continues to evolve, it will likely become even more prevalent in our daily routines, offering new ways to improve our quality of life.', NULL, '', '', 1, 33, 10.00, '0', '2026-04-14 19:43:58');
INSERT INTO `question_main` VALUES (169, 1, 5, 2, '请以\"青春心向党，奋斗正当时\"为题，写一篇800字的议论文，论述当代青年如何将个人理想与国家发展相结合。', '', NULL, '参考答案：青春心向党，奋斗正当时\n\n青春，是人生中最美好的年华，也是国家发展最宝贵的资源。当代青年作为国家未来的建设者和接班人，肩负着实现中华民族伟大复兴的历史使命。将个人理想与国家发展相结合，是当代青年应有的责任与担当。\n\n首先，坚定理想信念，筑牢思想根基。当代青年要深入学习党的创新理论，树立正确的世界观、人生观、价值观，把个人理想融入国家和民族的事业中。只有坚定理想信念，才能在纷繁复杂的社会环境中保持清醒头脑，找准人生方向，为实现个人价值和国家发展贡献智慧和力量。\n\n其次，锤炼过硬本领，提升综合素质。青年时期是学习的黄金时期，当代青年要珍惜时光，刻苦学习，掌握科学文化知识和专业技能，不断提高自身综合素质。同时，要积极参与社会实践，在实践中增长才干，在奋斗中锤炼品格，为将来服务国家、服务社会打下坚实基础。\n\n再次，勇于创新创造，积极投身实践。创新是民族进步的灵魂，是国家兴旺发达的不竭动力。当代青年要勇于打破常规，敢于挑战权威，积极投身科技创新、文化创新、制度创新等各个领域，为国家发展注入新的活力。同时，要立足本职岗位，从点滴做起，在平凡的岗位上创造不平凡的业绩，用实际行动诠释奋斗的意义。\n\n最后，传承红色基因，弘扬时代精神。当代青年要学习革命先辈的崇高精神，传承红色基因，弘扬以爱国主义为核心的民族精神和以改革创新为核心的时代精神。要将个人理想与国家发展紧密结合起来，在实现中华民族伟大复兴的征程中贡献青春力量，书写无悔于青春、无愧于时代的华彩篇章。\n\n总之，青春心向党，奋斗正当时。当代青年要将个人理想与国家发展紧密结合，坚定理想信念，锤炼过硬本领，勇于创新创造，传承红色基因，在实现中华民族伟大复兴的中国梦中放飞青春梦想，书写人生华章。', '这是一道议论文写作题，要求学生以\"青春心向党，奋斗正当时\"为题，论述当代青年如何将个人理想与国家发展相结合。参考答案从坚定理想信念、锤炼过硬本领、勇于创新创造、传承红色基因四个方面展开论述，结构清晰，论点明确，论据充分。文章开头点明主题，中间分四个层次论述，结尾总结升华，符合议论文的基本要求。学生写作时应注意论点明确，论据充分，结构合理，语言流畅，同时结合自身实际和社会热点，使文章更具说服力和感染力。', 0, 34, 5.00, '0', '2026-04-14 19:58:35');
INSERT INTO `question_main` VALUES (170, 1, 5, 2, '请以\"青春心向党，奋斗正当时\"为题，写一篇800字的议论文，论述当代青年如何将个人理想与国家发展相结合。', '', NULL, '参考答案：青春心向党，奋斗正当时\n\n青春是人生中最美好的时光，也是国家发展最宝贵的资源。当代青年作为国家未来的建设者和接班人，肩负着实现中华民族伟大复兴的历史使命。如何将个人理想与国家发展相结合，是当代青年必须认真思考和践行的重要课题。\n\n首先，树立远大理想，明确人生方向。当代青年要树立正确的理想信念，把个人理想与国家前途、民族命运紧密联系起来。只有将个人理想融入国家和民族的事业中，才能在实现个人价值的同时，为国家发展贡献力量。青年时期是树立理想信念的关键时期，要深入学习党的创新理论，增强\"四个意识\"，坚定\"四个自信\"，做到\"两个维护\"，为人生奋斗奠定坚实的思想基础。\n\n其次，勇于担当作为，积极投身实践。当代青年要勇于担当时代责任，积极投身国家建设和社会发展。在学习上要刻苦钻研，掌握科学文化知识和专业技能；在工作上要爱岗敬业，精益求精；在社会实践中要勇于探索，敢于创新。只有通过实际行动，才能将个人理想转化为服务国家、服务社会的具体行动，实现个人价值与社会价值的统一。\n\n再次，锤炼品德修养，弘扬时代新风。当代青年要自觉践行社会主义核心价值观，锤炼高尚品格，弘扬时代新风。要明大德、守公德、严私德，培养爱国情怀、社会责任感、创新精神和实践能力。同时，要积极参与志愿服务，关心弱势群体，用实际行动传递正能量，展现当代青年的良好形象。\n\n最后，坚定文化自信，传承中华优秀文化。当代青年要坚定文化自信，传承和弘扬中华优秀传统文化，吸收借鉴人类文明优秀成果。要树立正确的历史观、民族观、国家观、文化观，增强做中国人的志气、骨气、底气，为实现中华民族伟大复兴提供强大的精神力量。\n\n总之，青春心向党，奋斗正当时。当代青年要将个人理想与国家发展紧密结合，树立远大理想，勇于担当作为，锤炼品德修养，坚定文化自信，在实现中华民族伟大复兴的征程中贡献青春力量，书写无愧于时代、无愧于人民的青春华章。', '这是一道议论文写作题，要求学生以\"青春心向党，奋斗正当时\"为题，论述当代青年如何将个人理想与国家发展相结合。参考答案从树立远大理想、勇于担当作为、锤炼品德修养、坚定文化自信四个方面展开论述，结构完整，论点明确，论据充分。文章开头点明主题，中间分四个层次论述，结尾总结升华，符合议论文的基本要求。学生写作时应注意论点明确，论据充分，结构合理，语言流畅，同时结合自身实际和社会热点，使文章更具说服力和感染力。', 0, 35, 5.00, '0', '2026-04-14 19:58:35');
INSERT INTO `question_main` VALUES (171, 1, 5, 2, '请以\"青春心向党，奋斗正当时\"为题，写一篇800字的议论文，论述当代青年如何将个人理想与国家发展相结合。', '', NULL, '参考答案：青春心向党，奋斗正当时\n\n青春是人生最美好的时光，也是国家发展最宝贵的资源。当代青年作为国家未来的建设者和接班人，肩负着实现中华民族伟大复兴的历史使命。如何将个人理想与国家发展相结合，是当代青年必须认真思考和践行的重要课题。\n\n首先，坚定理想信念，筑牢精神支柱。当代青年要深入学习党的创新理论，树立正确的世界观、人生观、价值观，坚定对马克思主义的信仰，对中国特色社会主义的信念，对中华民族伟大复兴中国梦的信心。只有坚定理想信念，才能在纷繁复杂的社会环境中保持清醒头脑，找准人生方向，为实现个人价值和国家发展贡献智慧和力量。\n\n其次，锤炼过硬本领，提升综合素质。青年时期是学习的黄金时期，当代青年要珍惜时光，刻苦学习，掌握科学文化知识和专业技能，不断提高自身综合素质。同时，要积极参与社会实践，在实践中增长才干，在奋斗中锤炼品格，为将来服务国家、服务社会打下坚实基础。只有具备过硬的本领，才能在实现个人理想的同时为国家发展贡献力量。\n\n再次，勇于创新创造，积极投身实践。创新是民族进步的灵魂，是国家兴旺发达的不竭动力。当代青年要勇于打破常规，敢于挑战权威，积极投身科技创新、文化创新、制度创新等各个领域，为国家发展注入新的活力。同时，要立足本职岗位，从点滴做起，在平凡的岗位上创造不平凡的业绩，用实际行动诠释奋斗的意义。\n\n最后，传承红色基因，弘扬时代精神。当代青年要学习革命先辈的崇高精神，传承红色基因，弘扬以爱国主义为核心的民族精神和以改革创新为核心的时代精神。要将个人理想与国家发展紧密结合起来，在实现中华民族伟大复兴的征程中贡献青春力量，书写无悔于青春、无愧于时代的华彩篇章。\n\n总之，青春心向党，奋斗正当时。当代青年要将个人理想与国家发展紧密结合，坚定理想信念，锤炼过硬本领，勇于创新创造，传承红色基因，在实现中华民族伟大复兴的中国梦中放飞青春梦想，书写人生华章。', '这是一道议论文写作题，要求学生以\"青春心向党，奋斗正当时\"为题，论述当代青年如何将个人理想与国家发展相结合。参考答案从坚定理想信念、锤炼过硬本领、勇于创新创造、传承红色基因四个方面展开论述，结构清晰，论点明确，论据充分。文章开头点明主题，中间分四个层次论述，结尾总结升华，符合议论文的基本要求。学生写作时应注意论点明确，论据充分，结构合理，语言流畅，同时结合自身实际和社会热点，使文章更具说服力和感染力。', 0, 36, 5.00, '0', '2026-04-14 19:58:35');
INSERT INTO `question_main` VALUES (172, 14, 1, 2, '以下哪个是Python中的关键字？', '', '[\"function\", \"def\", \"define\", \"func\"]', 'B', '在Python中，\'def\'是用于定义函数的关键字，而\'function\'、\'define\'和\'func\'都不是Python的关键字。', 0, 0, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (173, 14, 1, 2, 'Python中，以下哪个数据类型是不可变的？', '', '[\"list\", \"dictionary\", \"tuple\", \"set\"]', 'C', '在Python中，tuple（元组）是不可变数据类型，一旦创建就不能修改。而list（列表）、dictionary（字典）和set（集合）都是可变的。', 0, 1, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (174, 14, 1, 2, 'Python中，以下哪个运算符用于计算整除？', '', '[\"%\", \"//\", \"/\", \"**\"]', 'B', '在Python中，\'//\'运算符用于整除运算，返回商的整数部分；\'%\'是取模运算；\'/\'是普通除法；\'**\'是幂运算。', 0, 2, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (175, 14, 1, 2, 'Python中，以下哪个函数用于获取列表的长度？', '', '[\"size()\", \"length()\", \"len()\", \"count()\"]', 'C', '在Python中，\'len()\'函数用于获取列表（或其他序列）的长度。\'size()\'和\'length()\'不是Python内置函数，\'count()\'用于统计元素出现次数。', 0, 3, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (176, 14, 1, 2, 'Python中，以下哪个循环结构会执行至少一次循环体？', '', '[\"for循环\", \"while循环\", \"do-while循环\", \"for-else循环\"]', 'C', '在Python中，没有传统的do-while循环，但其他选项中，for循环和while循环都是先判断条件再执行循环体，可能一次都不执行。Python中没有for-else循环的概念。', 0, 4, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (177, 14, 1, 2, 'Python中，以下哪个方法用于向列表末尾添加元素？', '', '[\"append()\", \"add()\", \"insert()\", \"extend()\"]', 'A', '在Python中，\'append()\'方法用于向列表末尾添加单个元素；\'add()\'是集合的方法；\'insert()\'用于在指定位置插入元素；\'extend()\'用于将一个列表的所有元素添加到另一个列表中。', 0, 5, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (178, 14, 1, 2, 'Python中，以下哪个运算符用于比较两个对象是否引用同一个内存地址？', '', '[\"==\", \"!=\", \"is\", \"is not\"]', 'C', '在Python中，\'is\'运算符用于比较两个对象是否引用同一个内存地址；\'==\'和\'!=\'用于比较值是否相等；\'is not\'用于检查两个对象是否引用不同的内存地址。', 0, 6, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (179, 14, 1, 2, 'Python中，以下哪个函数用于将字符串转换为整数？', '', '[\"str_to_int()\", \"int()\", \"convert()\", \"parse()\"]', 'B', '在Python中，\'int()\'函数用于将字符串（或其他类型）转换为整数；\'str_to_int()\'、\'convert()\'和\'parse()\'都不是Python内置函数。', 0, 7, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (180, 14, 1, 2, 'Python中，以下哪个关键字用于定义类？', '', '[\"class\", \"def\", \"struct\", \"type\"]', 'A', '在Python中，\'class\'关键字用于定义类；\'def\'用于定义函数；\'struct\'不是Python关键字；\'type\'是一个内置函数，用于获取对象的类型。', 0, 8, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (181, 14, 1, 2, 'Python中，以下哪个模块提供了日期和时间处理功能？', '', '[\"date\", \"time\", \"datetime\", \"calendar\"]', 'C', '在Python中，\'datetime\'模块提供了日期和时间处理功能；\'date\'和\'time\'是datetime模块中的类；\'calendar\'模块提供了日历相关的功能。', 0, 9, 5.00, '0', '2026-04-16 09:28:30');
INSERT INTO `question_main` VALUES (182, 1, 6, 2, '阅读理解', 'Climate change is one of the most pressing challenges facing our planet today. Global temperatures have risen by approximately 1.1°C since the pre-industrial era, primarily due to human activities that increase greenhouse gases in the atmosphere. These activities include burning fossil fuels for energy, deforestation, and industrial processes. The consequences of climate change are far-reaching, affecting weather patterns, sea levels, biodiversity, and human health. Scientists warn that without immediate action, we could face more extreme weather events, rising sea levels threatening coastal cities, and significant disruptions to ecosystems worldwide. International agreements like the Paris aim to limit global warming to well below 2°C, but achieving these targets requires coordinated global efforts and significant changes in how we produce and consume energy.', NULL, '', '', 1, 37, 10.00, '0', '2026-04-17 13:56:37');
INSERT INTO `question_main` VALUES (183, 15, 1, 2, '在Python中，以下哪种方式可以实现封装？', '', '[\"使用private关键字\", \"使用下划线前缀\", \"使用public关键字\", \"使用final关键字\"]', 'B', '在Python中，封装主要通过命名约定来实现，使用单下划线前缀(_)表示受保护的成员，使用双下划线(__)表示私有的成员。Python没有像Java那样的private或public关键字。', 0, 0, 5.00, '0', '2026-04-19 18:09:07');
INSERT INTO `question_main` VALUES (184, 15, 1, 2, 'Python中，以下关于封装的说法正确的是？', '', '[\"Python强制实现封装\", \"Python通过访问控制修饰符实现封装\", \"Python主要通过命名约定和属性访问器实现封装\", \"Python不支持封装\"]', 'C', 'Python不像Java等语言那样有严格的访问控制修饰符，而是通过命名约定(如下划线前缀)和属性访问器(getter/setter)来实现封装。Python的封装更多是一种约定而非强制执行。', 0, 1, 5.00, '0', '2026-04-19 18:09:07');
INSERT INTO `question_main` VALUES (185, 1, 1, 2, '在Python中，以下哪个特性封装了对象的内部状态，防止外部直接访问？', '', '[\"继承\", \"多态\", \"封装\", \"抽象\"]', 'C', '封装是面向对象编程的三大特性之一，它将对象的属性和方法包装在一起，隐藏对象的内部状态，只通过公共接口与外部交互。在Python中，通常通过在属性名前添加双下划线(__)来实现封装，使属性变为私有属性。', 0, 38, 5.00, '0', '2026-04-26 00:58:08');
INSERT INTO `question_main` VALUES (186, 1, 1, 2, '在Python中，以下哪种方法可以实现对私有属性的访问控制？', '', '[\"直接访问属性名\", \"通过getter和setter方法\", \"通过@property装饰器\", \"以上都是\"]', 'D', '在Python中，有几种方法可以实现封装和访问控制：1) 直接访问属性名（不推荐，破坏了封装性）；2) 使用getter和setter方法来控制对属性的访问；3) 使用@property装饰器创建属性访问器，可以在访问属性时添加额外的逻辑。这三种方法都可以实现对私有属性的访问控制，但@property装饰器是Python中最优雅的方式。', 0, 39, 5.00, '0', '2026-04-26 00:58:08');
INSERT INTO `question_main` VALUES (187, 16, 1, 2, '在Vue3中，以下哪种方式是父子组件之间最常用的通信方式？', '', '[\"使用Vuex\", \"使用props和emit\", \"使用EventBus\", \"使用localStorage\"]', 'B', '在Vue3中，父子组件之间的通信主要通过props(父传子)和emit(子传父)来实现。这是Vue官方推荐的标准通信方式，简单直接且符合Vue的设计理念。Vuex更适合全局状态管理，EventBus在Vue3中已不推荐使用，而localStorage主要用于跨页面或组件的数据持久化。', 0, 0, 5.00, '0', '2026-04-28 15:04:40');
INSERT INTO `question_main` VALUES (188, 16, 1, 2, 'Vue3中，setup函数的作用是什么？', '', '[\"创建组件实例\", \"初始化组件的props\", \"组合式API的入口\", \"处理组件的生命周期\"]', 'C', 'setup函数是Vue3组合式API的入口点，它是在组件创建之前执行的函数，主要用于初始化组件的状态、方法和计算属性等。在setup中定义的变量和方法需要通过return暴露给模板使用。虽然setup也会在组件实例创建过程中被调用，但它的主要目的是提供组合式API的编程体验。', 0, 1, 5.00, '0', '2026-04-28 15:04:40');
INSERT INTO `question_main` VALUES (189, 16, 1, 2, '在Vue3中，以下哪个选项是响应式数据的正确定义方式？', '', '[\"let count = ref(0)\", \"let count = reactive(0)\", \"let count = 0\", \"let count = new Ref(0)\"]', 'A', '在Vue3中，ref和reactive都是创建响应式数据的方法。ref主要用于基本类型数据的响应式包装，使用方式为ref(0)；reactive主要用于对象或数组的响应式包装。选项B中reactive(0)是错误的用法，reactive应该接收对象或数组。选项C没有使用任何响应式API，选项D中的Ref不是Vue3中的有效API。', 0, 2, 5.00, '0', '2026-04-28 15:04:40');
INSERT INTO `question_main` VALUES (190, 16, 1, 2, 'Vue3中的Composition API相比Options API的主要优势是什么？', '', '[\"代码更简洁\", \"性能更好\", \"逻辑复用更方便\", \"以上都是\"]', 'D', 'Vue3的Composition API相比Options API有多个优势：1) 代码更简洁，相关逻辑可以组织在一起；2) 性能更好，减少了不必要的响应式追踪；3) 逻辑复用更方便，可以将可复用的逻辑抽取为组合函数(Composables)。这些优势使得Composition API在处理复杂组件时更具优势。', 0, 3, 5.00, '0', '2026-04-28 15:04:40');
INSERT INTO `question_main` VALUES (191, 16, 1, 2, '在Vue3中，以下哪个指令用于条件渲染？', '', '[\"v-show\", \"v-if\", \"v-for\", \"v-model\"]', 'B', '在Vue3中，v-if是条件渲染指令，根据表达式的值来决定是否渲染元素。v-show也是条件渲染，但它只是切换CSS的display属性，元素始终存在于DOM中。v-for用于列表渲染，v-model用于表单双向绑定。虽然v-show也能实现条件显示，但v-if是真正的条件渲染，当条件为false时，元素不会被渲染到DOM中。', 0, 4, 5.00, '0', '2026-04-28 15:04:40');
INSERT INTO `question_main` VALUES (192, 1, 1, 2, '在JVM中，以下哪个区域是线程私有的？', '', '[\"堆\", \"方法区\", \"程序计数器\", \"运行时常量池\"]', 'C', '程序计数器是每个线程独有的，用于记录当前线程执行的字节码行号；堆和方法区是所有线程共享的，运行时常量池属于方法区的一部分。', 0, 40, 5.00, '0', '2026-05-02 21:00:34');
INSERT INTO `question_main` VALUES (193, 1, 1, 2, '关于JVM垃圾回收，以下哪种算法主要用于老年代的回收？', '', '[\"标记-复制算法\", \"标记-清除算法\", \"标记-整理算法\", \"分代收集算法\"]', 'C', '老年代垃圾回收通常使用标记-整理算法，因为存活对象多，复制开销大；标记-复制算法主要用于新生代，标记-清除算法会产生内存碎片，而分代收集是策略而非具体算法。', 0, 41, 5.00, '0', '2026-05-02 21:00:34');
INSERT INTO `question_main` VALUES (194, 1, 1, 2, 'JVM类加载过程中，哪个步骤负责将字节流转化为方法区的运行时数据结构？', '', '[\"加载\", \"验证\", \"准备\", \"解析\"]', 'A', '加载阶段通过类全限定名获取二进制字节流，并将其转化为方法区的运行时数据结构，同时在堆中生成Class对象。验证、准备、解析属于连接阶段。', 0, 42, 5.00, '0', '2026-05-02 21:00:34');
INSERT INTO `question_main` VALUES (195, 1, 1, 2, '在Python中，以下哪种命名约定通常用于表示类的私有属性或方法？', '', '[\"以单个下划线开头（如 _name）\", \"以双下划线开头（如 __name）\", \"以双下划线开头和结尾（如 __name__）\", \"以大写字母开头（如 Name）\"]', 'B', '在Python中，以双下划线开头（如 __name）的属性或方法会被解释器进行名称修饰（name mangling），将其转换为 _ClassName__name，从而实现一种弱形式的私有化，防止子类意外覆盖。单个下划线通常仅作为约定表示内部使用，不强制限制访问。', 0, 43, 5.00, '0', '2026-05-03 14:42:15');
INSERT INTO `question_main` VALUES (196, 1, 1, 2, '关于Python中的封装，下列说法错误的是：', '', '[\"Python没有像Java或C++那样的严格访问控制关键字（如private、protected）\", \"可以通过@property装饰器来定义getter和setter方法，实现对属性的访问控制\", \"以双下划线开头的成员变量在类外部绝对无法访问\", \"封装的主要目的是隐藏实现细节，保护数据完整性\"]', 'C', '虽然Python通过名称修饰机制使得以双下划线开头的成员变量在类外部直接访问变得困难，但并非绝对无法访问。用户可以通过 _ClassName__attribute 的形式强行访问。因此，说\'绝对无法访问\'是错误的。Python的封装更多依赖于命名约定的文化而非强制性的语言机制。', 0, 44, 5.00, '0', '2026-05-03 14:42:15');
INSERT INTO `question_main` VALUES (197, 1, 1, 2, '在Python类中，使用@property装饰器修饰的方法主要作用是什么？', '', '[\"将实例方法转换为静态方法\", \"允许像访问属性一样调用方法，并可定义setter和deleter来控制访问\", \"定义类的构造函数\", \"实现类的继承关系\"]', 'B', '@property装饰器允许将方法调用语法转换为属性访问语法。它通常配合@method_name.setter和@method_name.deleter使用，从而实现对类属性的读取、写入和删除操作的封装和控制，提高了代码的可读性和安全性。', 0, 45, 5.00, '0', '2026-05-03 14:42:15');
INSERT INTO `question_main` VALUES (198, 17, 1, 2, 'Java语言的诞生产生于哪一年？', '', '[\"1991\", \"1995\", \"1998\", \"2000\"]', 'B', 'Java语言由Sun Microsystems公司于1995年正式发布，因此正确答案是1995年。', 0, 0, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (199, 17, 1, 2, '以下哪个是Java的面向对象特性？', '', '[\"继承\", \"封装\", \"多态\", \"所有以上\"]', 'D', 'Java具有三大面向对象特性：封装、继承和多态，因此所有选项都是Java的面向对象特性。', 0, 1, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (200, 17, 1, 2, '下面哪个关键字用于让类不能被继承？', '', '[\"static\", \"final\", \"abstract\", \"private\"]', 'B', 'final关键字用于修饰类、方法和变量，当用final修饰类时，表示该类不能被继承。', 0, 2, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (201, 17, 1, 2, 'Java支持多继承（类之间）。', '', '[\"选项A\", \"选项B\"]', 'A', 'Java不支持类之间的多继承，一个类只能直接继承一个父类，但可以通过实现多个接口来达到类似多继承的效果。', 0, 3, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (202, 17, 1, 2, 'JVM是跨平台的核心。', '', '[\"选项A\", \"选项B\"]', 'A', 'JVM(Java虚拟机)是Java跨平台的核心，Java代码被编译成字节码，可以在任何安装了JVM的平台上运行。', 0, 4, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (203, 17, 1, 2, 'public static void main(String[] args)是Java程序的入口方法。', '', '[\"选项A\", \"选项B\"]', 'A', 'Java程序的入口方法是main方法，其签名必须是public static void main(String[] args)，JVM通过这个方法启动应用程序。', 0, 5, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (204, 17, 1, 2, 'StringBuffer和StringBuilder都是线程安全的。', '', '[\"选项A\", \"选项B\"]', 'A', 'StringBuffer是线程安全的，而StringBuilder不是线程安全的。StringBuilder在性能上通常优于StringBuffer，但不保证线程安全。', 0, 6, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (205, 17, 1, 2, '在Java 8之后，接口中可以包含私有方法（private methods）。', '', '[\"选项A\", \"选项B\"]', 'A', '从Java 9开始，接口可以包含私有方法，这些方法只能在接口内部使用，提高了代码的组织性和复用性。', 0, 7, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (206, 17, 1, 2, 'final修饰的类不能被继承，但final修饰的方法可以被重写。', '', '[\"选项A\", \"选项B\"]', 'A', 'final修饰的类不能被继承，同时final修饰的方法也不能被重写，这是final关键字的基本特性。', 0, 8, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (207, 17, 1, 2, 'Optional类主要用于解决什么问题？', '', '[\"提高代码执行速度\", \"避免空指针异常(NullPointerException)\", \"替代所有的null检查\", \"优化内存分配\"]', 'B', 'Optional类是Java 8引入的容器类，主要用于避免空指针异常，提供了一种更优雅的方式来处理可能为null的值。', 0, 9, 5.00, '0', '2026-05-04 01:31:43');
INSERT INTO `question_main` VALUES (208, 1, 6, 2, '阅读理解', 'Artificial intelligence has become an integral part of modern life, transforming various aspects of our daily routines. From smart home devices that adjust temperature automatically to personalized learning platforms that adapt to individual student needs, AI technology continues to evolve and expand its influence. In high school settings, AI-powered educational tools help students identify their strengths and weaknesses, providing customized learning paths that enhance academic performance. For college students, AI applications assist in research, time management, and even career planning, making university life more efficient and productive. The integration of AI in family life has brought both convenience and challenges, as parents navigate between embracing technological advancements and ensuring healthy screen time for their children. As AI continues to advance, it\'s crucial for individuals to develop digital literacy skills and understand the ethical implications of these technologies.', NULL, '', '', 1, 46, 10.00, '0', '2026-05-11 18:57:52');
INSERT INTO `question_main` VALUES (209, 1, 6, 2, '阅读理解', 'The university orientation week is an exciting time for freshmen. One of the most anticipated activities is the military training, which helps students develop discipline and teamwork. The training usually starts early in the morning with basic exercises like marching and standing at attention. Many students find it challenging at first, but they gradually build up their physical strength and endurance. The military training also creates opportunities for new friendships to form as students work together to complete tasks. By the end of the week, most students feel a strong sense of accomplishment and pride in their university.', NULL, '', '', 1, 47, 10.00, '0', '2026-05-12 08:18:40');
INSERT INTO `question_main` VALUES (210, 1, 6, 2, '阅读理解', 'In today\'s fast-paced world, many people experience high levels of stress ___1___ their daily lives. There are several effective ways to manage stress and maintain mental well-being. First, regular exercise can help ___2___ tension and improve mood. Physical activities like walking, swimming, or yoga release endorphins, which are natural stress ___3___. Second, maintaining a balanced diet is crucial. Eating nutritious foods and avoiding excessive caffeine and sugar can ___4___ your body better cope with stress. Third, getting enough sleep is essential for stress management. Most adults need 7-9 hours of quality sleep each night to ___5___ properly. By incorporating these habits into your routine, you can significantly reduce stress levels and improve your overall quality of life.', NULL, '', '', 1, 48, 10.00, '0', '2026-05-12 08:40:08');
INSERT INTO `question_sub` VALUES (1775999703993, 149, '1', 1, '[\"选项A\", \"选项B\"]', 'A', '', 0, 2.00);
INSERT INTO `question_sub` VALUES (1776001233251, 150, '11', 1, '[\"选项A\", \"选项B\"]', 'A', '', 0, 2.00);
INSERT INTO `question_sub` VALUES (1776044795710, 149, '11111', 3, NULL, 'true', '', 1, 2.00);
INSERT INTO `question_sub` VALUES (1776044806875, 149, '1222', 4, NULL, '111', '', 2, 2.00);
INSERT INTO `question_sub` VALUES (1776044820766, 149, '2222', 5, NULL, '3333', '', 3, 2.00);
INSERT INTO `question_sub` VALUES (1776044820767, 168, 'What is the main idea of the passage?', 1, '[\"AI technology is replacing human workers in various industries\", \"AI has become an invisible but essential part of daily life\", \"Virtual assistants are the most common form of AI technology\", \"AI will eventually replace all traditional forms of entertainment\"]', 'B', 'The main idea of the passage is that AI has become an integral and often unnoticed part of our daily lives. The passage describes how AI is used in various aspects of daily routines, from morning routines to entertainment, without explicitly stating that it\'s replacing humans or that it\'s only in virtual assistants.', 0, 2.00);
INSERT INTO `question_sub` VALUES (1776044820768, 168, 'According to the passage, how do navigation apps like Google Maps use AI?', 1, '[\"By learning users\' personal preferences\", \"By analyzing traffic patterns\", \"By connecting with other users\' devices\", \"By recording voice commands\"]', 'B', 'The passage specifically states that navigation apps like Google Maps use AI to \'analyze traffic patterns and suggest the fastest routes.\' This is the only correct option as it directly reflects information provided in the text.', 1, 2.00);
INSERT INTO `question_sub` VALUES (1776044820769, 168, 'What can be inferred about AI in education from the passage?', 1, '[\"AI is completely replacing teachers in schools\", \"AI helps create customized learning experiences for students\", \"AI is mainly used for grading homework\", \"AI technology is too expensive for most schools\"]', 'B', 'The passage mentions that \'AI tools help students with personalized learning experiences, adapting to individual needs and learning styles.\' This suggests that AI in education focuses on customization rather than replacement of teachers or just grading homework.', 2, 2.00);
INSERT INTO `question_sub` VALUES (1776044820770, 168, 'According to the passage, AI technology is used in entertainment to create entirely new forms of media.', 3, NULL, 'false', 'The passage states that streaming services use AI algorithms to recommend movies and shows based on viewing history, but it does not mention that AI is used to create entirely new forms of media. It only discusses how AI enhances existing entertainment through personalized recommendations.', 3, 2.00);
INSERT INTO `question_sub` VALUES (1776044820771, 168, 'List three areas mentioned in the passage where AI is used in daily life.', 4, NULL, 'morning routines (virtual assistants), commuting (navigation apps), education (personalized learning), entertainment (streaming services)', 'The passage explicitly mentions four areas where AI is used: 1) Morning routines with virtual assistants like Siri or Alexa, 2) Commuting with navigation apps like Google Maps, 3) Education with personalized learning tools, and 4) Entertainment with streaming service recommendations. Students should list at least three of these areas to receive full credit.', 4, 2.00);
INSERT INTO `question_sub` VALUES (1776044820772, 182, 'What has been the approximate rise in global temperatures since the pre-industrial era?', 1, '[\"0.5°C\", \"1.1°C\", \"2.0°C\", \"3.5°C\"]', 'B', 'The passage states that global temperatures have risen by approximately 1.1°C since the pre-industrial era. This is directly mentioned in the first paragraph.', 0, 2.00);
INSERT INTO `question_sub` VALUES (1776044820773, 182, 'Which of the following human activities contribute to climate change?', 2, '[\"Burning fossil fuels\", \"Deforestation\", \"Industrial processes\", \"Agriculture\"]', 'A,B,C,D', 'The passage mentions burning fossil fuels, deforestation, and industrial processes as activities that increase greenhouse gases in the atmosphere. While agriculture is a significant contributor to climate change, it\'s not mentioned in this specific passage.', 1, 2.00);
INSERT INTO `question_sub` VALUES (1776044820774, 182, 'The Paris Agreement aims to limit global warming to well below 2°C.', 3, NULL, 'true', 'The passage explicitly states: \'International agreements like the Paris aim to limit global warming to well below 2°C.\' Note that the passage has a minor grammatical error (\'the Paris\' instead of \'the Paris Agreement\'), but the information is correct.', 2, 2.00);
INSERT INTO `question_sub` VALUES (1776044820775, 182, 'According to the passage, without immediate action, we could face more extreme _____ events.', 4, NULL, 'weather', 'The passage states: \'without immediate action, we could face more extreme weather events, rising sea levels threatening coastal cities, and significant disruptions to ecosystems worldwide.\' The blank should be filled with \'weather\'.', 3, 2.00);
INSERT INTO `question_sub` VALUES (1776044820776, 182, 'What are some of the consequences of climate change mentioned in the passage?', 5, NULL, 'The passage mentions several consequences of climate change: affecting weather patterns, sea levels, biodiversity, and human health; more extreme weather events; rising sea levels threatening coastal cities; and significant disruptions to ecosystems worldwide.', 'The answer should include all the consequences mentioned in the passage. The passage specifically lists these effects in the second paragraph.', 4, 2.00);
INSERT INTO `question_sub` VALUES (1776044820777, 208, 'According to the passage, how does AI help high school students?', 1, '[\"By replacing teachers\", \"By identifying strengths and weaknesses\", \"By reducing homework load\", \"By eliminating exams\"]', 'B', 'The passage states that AI-powered educational tools help high school students identify their strengths and weaknesses, providing customized learning paths.', 0, 2.00);
INSERT INTO `question_sub` VALUES (1776044820778, 208, 'According to the passage, AI is used in which of the following areas?', 2, '[\"Smart home devices\", \"Educational platforms\", \"Career planning\", \"Entertainment only\"]', 'A,B,C', 'The passage mentions AI in smart home devices, educational platforms for high school students, and career planning for college students.', 1, 2.00);
INSERT INTO `question_sub` VALUES (1776044820779, 208, 'The passage suggests that as AI advances, individuals need to develop ___ skills.', 4, NULL, 'digital literacy', 'The passage states that as AI continues to advance, it\'s crucial for individuals to develop digital literacy skills.', 2, 2.00);
INSERT INTO `question_sub` VALUES (1776044820780, 208, 'According to the passage, AI has only brought benefits to family life without any challenges.', 3, NULL, 'false', 'The passage states that the integration of AI in family life has brought both convenience and challenges, as parents navigate between embracing technological advancements and ensuring healthy screen time.', 3, 2.00);
INSERT INTO `question_sub` VALUES (1776044820781, 208, 'Based on the passage, what are some ways college students can benefit from AI applications?', 5, NULL, 'College students can benefit from AI applications in research assistance, time management, and career planning as mentioned in the passage.', 'The passage specifically mentions that for college students, AI applications assist in research, time management, and career planning, making university life more efficient and productive.', 4, 2.00);
INSERT INTO `question_sub` VALUES (1776044820782, 209, 'The university ___ week is an exciting time for freshmen.', 1, '[\"orientation\", \"graduation\", \"summer\", \"winter\"]', 'A', 'orientation week（迎新周）是新生入学时的活动，符合上下文。', 0, 2.00);
INSERT INTO `question_sub` VALUES (1776044820783, 209, 'Military training helps students develop ___ and teamwork.', 1, '[\"discipline\", \"entertainment\", \"comfort\", \"freedom\"]', 'A', '根据上下文，军训帮助学生培养纪律性（discipline）和团队合作精神。', 1, 2.00);
INSERT INTO `question_sub` VALUES (1776044820784, 209, 'The training usually starts early ___ the morning with basic exercises.', 1, '[\"in\", \"at\", \"on\", \"for\"]', 'A', 'in the morning是固定搭配，表示在早晨。', 2, 2.00);
INSERT INTO `question_sub` VALUES (1776044820785, 209, 'Many students find it ___ at first, but they gradually build up their physical strength.', 1, '[\"challenging\", \"easy\", \"boring\", \"interesting\"]', 'A', '根据上下文，学生起初觉得军训很有挑战性（challenging）。', 3, 2.00);
INSERT INTO `question_sub` VALUES (1776044820786, 209, 'By the end of the week, most students feel a strong sense of ___ and pride.', 1, '[\"accomplishment\", \"failure\", \"regret\", \"fatigue\"]', 'A', '根据上下文，完成军训后，学生会有强烈的成就感（accomplishment）和自豪感。', 4, 2.00);
INSERT INTO `question_sub` VALUES (1776044820787, 210, 'In today\'s fast-paced world, many people experience high levels of stress ___ their daily lives.', 1, '[\"in\", \"on\", \"at\", \"by\"]', 'A', 'in their daily lives是固定搭配，表示在日常生活中。', 0, 2.00);
INSERT INTO `question_sub` VALUES (1776044820788, 210, 'Regular exercise can help ___ tension and improve mood.', 1, '[\"reduce\", \"increase\", \"cause\", \"create\"]', 'A', '根据上下文，运动可以帮助减轻(tension)紧张情绪，所以选reduce（减少）。', 1, 2.00);
INSERT INTO `question_sub` VALUES (1776044820789, 210, 'Physical activities like walking, swimming, or yoga release endorphins, which are natural stress ___.', 1, '[\"relievers\", \"causers\", \"enhancers\", \"triggers\"]', 'A', '内啡肽是天然的压力缓解剂，所以选relievers（缓解剂）。', 2, 2.00);
INSERT INTO `question_sub` VALUES (1776044820790, 210, 'Eating nutritious foods and avoiding excessive caffeine and sugar can ___ your body better cope with stress.', 1, '[\"help\", \"prevent\", \"stop\", \"avoid\"]', 'A', '根据上下文，健康饮食可以帮助身体更好地应对压力，所以选help（帮助）。', 3, 2.00);
INSERT INTO `question_sub` VALUES (1776044820791, 210, 'Most adults need 7-9 hours of quality sleep each night to ___ properly.', 1, '[\"function\", \"work\", \"exercise\", \"relax\"]', 'A', '根据上下文，充足的睡眠有助于身体正常运作，所以选function（运作）。', 4, 2.00);
INSERT INTO `rag_document` VALUES (2, 1, 1, 'c++知识.txt', 'txt', 4105, '/profile/rag/documents/2026/05/04/c++知识_20260504011713A001.txt', '# C++ 核心知识体系\r\n\r\n## 1. 基础语法\r\n\r\n### 1.1 Hello World 程序\r\n```cpp\r\n#include <iostream>\r\nusing namespace std;\r\n\r\nint main() {\r\n    cout << \"Hello, World!\" << endl;\r\n    return 0;\r\n}\r\n```\r\n\r\n### 1.2 基本数据类型\r\n| 类型 | 关键字 | 典型大小 |\r\n|------|--------|----------|\r\n| 整型 | int | 4字节 |\r\n| 浮点型 | float/double | 4/8字节 |\r\n| 字符 | char | 1字节 |\r\n| 布尔 | bool | 1字节 |\r\n\r\n## 2. 面向对象编程\r\n\r\n### 2.1 类与对象\r\n```cpp\r\nclass Student {\r\nprivate:\r\n    string name;\r\n    int age;\r\n    \r\npublic:\r\n    Student(string n, int a) : name(n), a', 4, 5, '', '2026-05-04 01:17:13', '2026-05-04 01:17:14');
INSERT INTO `rag_document` VALUES (7, 2, 1, 'Java 核心知识题库.pdf', 'pdf', 156702, '/profile/rag/documents/2026/05/08/Java 核心知识题库_20260508161258A001.pdf', 'Java 核心知识题库（测试用）\r\n一、单选题\r\n1. Java 语言的诞生产生于哪一年？\r\nA. 1991\r\nB. 1995\r\nC. 1998\r\nD. 2000\r\n✅ 答案：B\r\n2. 以下哪个是 Java 的面向对象特性？\r\nA. 继承\r\nB. 封装\r\nC. 多态\r\nD. 所有以上\r\n✅ 答案：D\r\n3. 下面哪个关键字用于让类不能被继承？\r\nA. static\r\nB. final\r\nC. abstract\r\nD. private\r\n✅ 答案：B\r\n二、判断题\r\n1. Java 支持多继承（类之间）。\r\n✅ 错误\r\n2. JVM 是跨平台的核心。\r\n✅ 正确\r\n3. public static void main(String[] args) 是 Java 程序的入口方法。\r\n✅ 正确\r\n三、简答题\r\n1. 简述 Java 的垃圾回收机制。\r\nJava 自动内存管理，通过 GC 回收不再使用的对象内存，避免内存泄漏。\r\n2. 什么是 JVM、JRE 和 JDK？\r\nJVM：Java 虚拟机\r\nJRE：运行环境（JVM + 核心类库）\r\nJDK：开发工具包（JRE + 编译器 + 调', 5, 5, '', '2026-05-08 16:12:58', '2026-05-08 16:13:02');
INSERT INTO `rag_document` VALUES (8, 2, 1, 'java知识库2.txt', 'txt', 3069, '/profile/rag/documents/2026/05/08/java知识库2_20260508161447A002.txt', '你提供的这份《Java 核心知识题库》内容非常全面，涵盖了 Java 基础、面向对象、JVM、集合、并发、内存模型、异常处理、设计模式、面试高频题、场景设计等多个维度。如果你希望在此基础上“添加新的知识”，可以根据现有结构，按以下方式扩展内容：\r\n\r\n---\r\n\r\n## 一、新增题型示例\r\n\r\n### 1. 单选题（新增）\r\n\r\n**在 Java 中，以下哪个类是不可变类（Immutable Class）？**\r\n\r\nA. `StringBuilder`  \r\nB. `String`  \r\nC. `ArrayList`  \r\nD. `HashMap`\r\n\r\n**答案**：B\r\n\r\n---\r\n\r\n### 2. 多选题（新增）\r\n\r\n**以下哪些是 Java 8 引入的新特性？**\r\n\r\nA. Lambda 表达式  \r\nB. Stream API  \r\nC. `Optional` 类  \r\nD. `synchronized` 关键字\r\n\r\n**答案**：A, B, C\r\n\r\n---\r\n\r\n### 3. 填空题（新增）\r\n\r\n```java\r\npublic class Example {\r', 3, 5, '', '2026-05-08 16:14:47', '2026-05-08 16:14:49');
INSERT INTO `rag_document` VALUES (20, 2, 1, '文本内容_1778572565035.txt', 'txt', 13592, NULL, '<p>以下已按相同格式（无 <code>#</code> 号，但保留 Markdown 渲染效果）生成 <strong>Java 反射知识库</strong>：</p><hr><p><strong>Java 反射核心知识库</strong></p><hr><p><strong>一、反射简介</strong></p><ol><li><p><strong>概念</strong>：Java 反射机制允许程序在运行时获取任意类的内部信息（如成员变量、方法、构造器等），并能动态创建对象、调用方法、修改属性。</p></li><li><p><strong>作用</strong>：</p><ul><li><p>动态加载类、创建对象</p></li><li><p>访问私有成员（突破封装）</p></li><li><p>实现框架（如 Spring、MyBatis）的核心底层</p></li><li><p>运行时类型判断与处理</p></li></ul></li><li><p><strong>核心包</strong>：<code>java.lang.reflect</code></p></li></ol>', 52, 5, '', '2026-05-12 15:56:05', '2026-05-12 15:56:24');
INSERT INTO `rag_document` VALUES (21, 2, 1, '文本内容_1778574328287.txt', 'txt', 4914, NULL, '<p></p><hr><p><strong>反射的核心作用</strong></p><hr><p><strong>1. 运行时获取类的完整信息</strong></p><p>可以在程序运行时动态获取任意类的构造器、方法、字段、注解、父类、接口等信息，而不需要在编译时知道类的具体名称。</p><pre><code class=\"language-java\">// 运行时获取类的所有方法\nClass&lt;?&gt; clazz = Class.forName(\"com.example.User\");\nMethod[] methods = clazz.getDeclaredMethods();\n</code></pre><hr><p><strong>2. 动态创建对象</strong></p><p>可以在运行时根据类名动态创建实例，而不是在代码中写死 <code>new</code> 关键字。</p><pre><code class=\"language-java\">// 动态创建对象\nObject obj = Class.forName(\"com.example.User\").newIns', 5, 5, '', '2026-05-12 16:25:28', '2026-05-12 16:25:30');
INSERT INTO `rag_document` VALUES (22, 2, 1, '文本内容_1778575245638.txt', 'txt', 19295, NULL, '<p>以下是 <strong>Java 堆和栈</strong> 的核心知识库，按同样格式整理：</p><hr><p><strong>Java 内存管理 —— 堆（Heap）与栈（Stack）</strong></p><hr><p><strong>一、基本概念</strong></p><p>Java 虚拟机（JVM）将内存主要划分为以下几个区域，其中<strong>堆</strong>和<strong>栈</strong>是最核心的两个：</p><table style=\"min-width: 100px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>内存区域</p></th><th colspan=\"1\" rowspan=\"1\"><p>全称</p></th><th ', 26, 5, '', '2026-05-12 16:40:45', '2026-05-12 16:40:56');
INSERT INTO `rag_document_chunk` VALUES (5, 2, 0, '# C++ 核心知识体系\r\n\r\n## 1. 基础语法\r\n\r\n### 1.1 Hello World 程序\r\n```cpp\r\n#include <iostream>\r\nusing namespace std;\r\n\r\nint main() {\r\n    cout << \"Hello, World!\" << endl;\r\n    return 0;\r\n}\r\n```\r\n\r\n### 1.2 基本数据类型\r\n| 类型 | 关键字 | 典型大小 |\r\n|------|--------|----------|\r\n| 整型 | int | 4字节 |\r\n| 浮点型 | float/double | 4/8字节 |\r\n| 字符 | char | 1字节 |\r\n| 布尔 | bool | 1字节 |\r\n\r\n## 2. 面向对象编程\r\n\r\n### 2.1 类与对象\r\n```cpp\r\nclass Student {\r\nprivate:\r\n    string name;\r\n    int age;\r\n    \r\npublic:\r\n    Student(string n, int a) : name(n), age(a) {}\r\n    \r\n    void display() {\r\n        cout << name << \", \" << age << endl;\r\n    }\r\n};\r\n```\r\n\r\n### 2.2 三大特性\r\n- **封装**：隐藏内部实现，提供公共接口\r\n- **继承**：代码复用，建立类间层次关系\r\n- **多态**：同一接口，不同实现\r\n\r\n```cpp\r\n// 多态示例\r\nclass Animal {\r\npublic:\r\n    virtual void speak() { cout << \"动物叫声\" << endl; }\r\n};\r\n\r\nclass Dog : ', 800, 'doc_2_chunk_0', '2026-05-04 01:17:13');
INSERT INTO `rag_document_chunk` VALUES (6, 2, 1, 'public Animal {\r\npublic:\r\n    void speak() override { cout << \"汪汪\" << endl; }\r\n};\r\n```\r\n\r\n## 3. 内存管理\r\n\r\n### 3.1 动态内存\r\n```cpp\r\nint* ptr = new int(10);  // 分配内存\r\ndelete ptr;              // 释放内存\r\n\r\nint* arr = new int[10];  // 分配数组\r\ndelete[] arr;            // 释放数组\r\n```\r\n\r\n### 3.2 智能指针（C++11）\r\n```cpp\r\n#include <memory>\r\n\r\nunique_ptr<int> uptr(new int(5));\r\nshared_ptr<int> sptr = make_shared<int>(10);\r\nweak_ptr<int> wptr = sptr;\r\n```\r\n\r\n## 4. STL标准模板库\r\n\r\n### 4.1 容器\r\n```cpp\r\nvector<int> vec = {1, 2, 3};\r\nlist<int> lst = {1, 2, 3};\r\nmap<string, int> mp = {{\"a\", 1}, {\"b\", 2}};\r\nunordered_set<int> set = {1, 2, 3};\r\n```\r\n\r\n### 4.2 算法\r\n```cpp\r\n#include <algorithm>\r\n\r\nsort(vec.begin(), vec.end());\r\nreverse(vec.begin(), vec.end());\r\nauto it = find(vec.begin(), vec.end(), 3);\r\n```\r\n\r\n## 5. 现代C++特性（C++1', 800, 'doc_2_chunk_1', '2026-05-04 01:17:13');
INSERT INTO `rag_document_chunk` VALUES (7, 2, 2, '1/14/17/20）\r\n\r\n### 5.1 Lambda表达式\r\n```cpp\r\nauto add = [](int a, int b) { return a + b; };\r\ncout << add(3, 5) << endl;\r\n\r\n// 捕获变量\r\nint x = 10;\r\nauto func = [x](int y) { return x + y; };\r\n```\r\n\r\n### 5.2 自动类型推导\r\n```cpp\r\nauto i = 42;           // int\r\nauto d = 3.14;         // double\r\nauto v = vector<int>(); // vector<int>\r\n```\r\n\r\n### 5.3 范围for循环\r\n```cpp\r\nvector<int> nums = {1, 2, 3, 4, 5};\r\nfor (auto& num : nums) {\r\n    num *= 2;\r\n}\r\n```\r\n\r\n## 6. 常见陷阱与最佳实践\r\n\r\n### 6.1 避免悬空指针\r\n```cpp\r\n// 错误示例\r\nint* getPtr() {\r\n    int local = 10;\r\n    return &local;  // 返回局部变量地址\r\n}\r\n\r\n// 正确做法\r\nint* getPtr() {\r\n    int* ptr = new int(10);\r\n    return ptr;\r\n}\r\n```\r\n\r\n### 6.2 使用const修饰\r\n```cpp\r\nconst int MAX_SIZE = 100;        // 常量\r\nconst string& getName() const {  // const成员函数\r\n    return name;\r\n}\r\n```\r\n\r\n### 6.3', 800, 'doc_2_chunk_2', '2026-05-04 01:17:13');
INSERT INTO `rag_document_chunk` VALUES (8, 2, 3, ' 资源获取即初始化（RAII）\r\n```cpp\r\nclass FileHandler {\r\n    FILE* file;\r\npublic:\r\n    FileHandler(const char* filename) {\r\n        file = fopen(filename, \"r\");\r\n    }\r\n    ~FileHandler() {\r\n        if(file) fclose(file);\r\n    }\r\n};\r\n```\r\n\r\n## 7. 常见面试题\r\n\r\n### Q: 虚函数表的工作原理？\r\n**A:** 每个包含虚函数的类都有一个虚函数表（vtable），存储虚函数地址。对象有虚指针（vptr）指向该表，实现动态绑定。\r\n\r\n### Q: 深拷贝与浅拷贝的区别？\r\n**A:** 浅拷贝只复制指针地址，深拷贝复制实际数据。默认拷贝构造函数执行浅拷贝。\r\n\r\n### Q: static关键字的作用？\r\n**A:** \r\n- 修饰局部变量：延长生命周期\r\n- 修饰全局变量/函数：限制作用域在当前文件\r\n- 修饰成员变量：所有对象共享\r\n- 修饰成员函数：不依赖对象调用\r\n\r\n## 8. 编译与链接\r\n\r\n```bash\r\n# 编译四步骤\r\ng++ -E main.cpp -o main.i   # 预处理\r\ng++ -S main.i -o main.s     # 编译\r\ng++ -c main.s -o main.o     # 汇编\r\ng++ main.o -o main          # 链接\r\n\r\n# 一步到位\r\ng++ main.cpp -o main\r\n```\r\n\r\n---\r\n\r\n这份知识体系涵盖了C++的核心内容，建议结合实际编程练习加深理解。需要深入了解某个具体主题吗？', 771, 'doc_2_chunk_3', '2026-05-04 01:17:13');
INSERT INTO `rag_document_chunk` VALUES (27, 7, 0, 'Java 核心知识题库（测试用）\r\n一、单选题\r\n1. Java 语言的诞生产生于哪一年？\r\nA. 1991\r\nB. 1995\r\nC. 1998\r\nD. 2000\r\n✅ 答案：B\r\n2. 以下哪个是 Java 的面向对象特性？\r\nA. 继承\r\nB. 封装\r\nC. 多态\r\nD. 所有以上\r\n✅ 答案：D\r\n3. 下面哪个关键字用于让类不能被继承？\r\nA. static\r\nB. final\r\nC. abstract\r\nD. private\r\n✅ 答案：B\r\n二、判断题\r\n1. Java 支持多继承（类之间）。\r\n✅ 错误\r\n2. JVM 是跨平台的核心。\r\n✅ 正确\r\n3. public static void main(String[] args) 是 Java 程序的入口方法。\r\n✅ 正确\r\n三、简答题\r\n1. 简述 Java 的垃圾回收机制。\r\nJava 自动内存管理，通过 GC 回收不再使用的对象内存，避免内存泄漏。\r\n2. 什么是 JVM、JRE 和 JDK？\r\nJVM：Java 虚拟机\r\nJRE：运行环境（JVM + 核心类库）\r\nJDK：开发工具包（JRE + 编译器 + 调试工具）\r\n四、代码填空题\r\njava\r\npublic class Test {\r\npublic static void main(String[] args) {\r\nint a = 10, b = 20;\r\nint max = (a > b) ? ______ : ______;\r\nSystem.out.println(max);\r\n}\r\n}\r\n✅ 填空： a , b\r\n五、面试高频题\r\n请说明 ArrayList 和 LinkedList 的区别\r\nsynchronized 关键字是如何实现线程安全的\r\n什么是 Java 中的内存模型（JMM）\r\nJava 8 中引入的 Optional ', 800, 'doc_7_chunk_0', '2026-05-08 16:12:59');
INSERT INTO `rag_document_chunk` VALUES (28, 7, 1, '类主要用于解决什么问题？\r\nA. 提高代码执行速度\r\nB. 避免空指针异常 (NullPointerException)\r\nC. 替代所有的 null 检查\r\nD. 优化内存分配\r\n✅ 答案：B\r\n关于 Java 接口（Interface）和抽象类（Abstract Class）的区别，下列说法错误的是？\r\nA. 接口中可以有默认方法（default method）\r\nB. 抽象类可以有构造方法，接口不能有\r\nC. 一个类可以实现多个接口，但只能继承一个抽象类\r\nD. 接口中的变量默认是 private static final 的\r\n✅ 答案：D (应为 public static final)\r\n下列哪个集合类是线程安全的？\r\nA. HashMap\r\nB. ArrayList\r\nC. ConcurrentHashMap\r\nD. LinkedList\r\n✅ 答案：C\r\nJava 中 == 和 equals() 的区别是什么？\r\nA. 没有区别\r\nB. == 比较引用地址，equals() 比较内容（若未重写则同 ==）\r\nC. == 比较内容，equals() 比较引用地址\r\nD. == 只能用于基本类型\r\n✅ 答案：B\r\n二、多选题（新增题型）\r\n以下哪些属于 Java 的自动装箱/拆箱操作？\r\nA. Integer i = 10;\r\nB. int n = new Integer(10);\r\nC. Integer j = new Integer(\"10\");\r\nD. int k = (Integer) 10;\r\n✅ 答案：A, B, D\r\nJava 垃圾回收算法包括哪些？\r\nA. 标记 - 清除\r\nB. 标记 - 整理\r\nC. 复制算法\r\nD. 分代收集\r\n✅ 答案：A, B, C, D\r\n三、判断题（进阶）\r\nJava 中的 String 是不可变的，因此 Strin', 800, 'doc_7_chunk_1', '2026-05-08 16:12:59');
INSERT INTO `rag_document_chunk` VALUES (29, 7, 2, 'gBuffer 和 StringBuilder 都是线程安全的。\r\n✅ 错误 (StringBuilder 不是线程安全的)\r\n在 Java 8 之后，接口中可以包含私有方法（private methods）。\r\n✅ 正确\r\nfinal 修饰的类不能被继承，但 final 修饰的方法可以被重写。\r\n✅ 错误 (final 方法不可被重写)\r\n四、简答题（深度解析）\r\n简述 JVM 内存区域划分及各区域的作用？\r\n堆（Heap）：存放对象实例，是 GC 管理的主要区域。\r\n栈（Stack）：每个线程私有，存储局部变量、操作数栈、动态链接等。\r\n方法区（Method Area）：存储类信息、常量、静态变量、即时编译器编译后的代码。\r\n程序计数器（Program Counter Register）：记录当前线程执行的字节码行号。\r\n本地方法栈（Native Method Stack）：服务于 Native 方法。\r\n请解释 volatile 关键字的作用及其原理？\r\n作用：保证变量的可见性和禁止指令重排序，不保证原子性。\r\n原理：\r\n可见性：当一个线程修改了 volatile 变量，新值会立即刷新到主内存，其他线程读取时强制\r\n从主内存加载。\r\n有序性：通过插入内存屏障（Memory Barrier）禁止指令重排。\r\n什么是死锁？产生死锁的必要条件有哪些？\r\n定义：两个或多个线程互相持有对方需要的资源，导致无限等待。\r\n四个必要条件：\r\n互斥条件\r\n请求与保持条件\r\n不剥夺条件\r\n循环等待条件\r\n五、代码填空与纠错（新增）\r\n题目 1：代码纠错\r\njava\r\n编辑\r\npublic class Test {\r\npublic static void main(String[] args) {\r\nint[] arr = {1, 2, 3};\r\nfor (int i = 0; i <= ', 800, 'doc_7_chunk_2', '2026-05-08 16:12:59');
INSERT INTO `rag_document_chunk` VALUES (30, 7, 3, 'arr.length; i++) { // 错误点\r\nSystem.out.println(arr[i]);\r\n}\r\n}\r\n}\r\n✅ 修正：将 i <= arr.length 改为 i < arr.length，否则会发生 ArrayIndexOutOfBoundsException。\r\n题目 2：Stream API 填空\r\njava\r\n编辑\r\nList<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);\r\nList<Integer> result = numbers.stream()\r\n.filter(n -> ________) // 过滤出偶数\r\n.map(n -> n * 2)\r\n.collect(Collectors.toList());\r\n✅ 填空：n % 2 == 0\r\n六、面试高频题（扩展）\r\n深入 HashMap：\r\nJDK 1.7 和 1.8 中 HashMap 的结构有什么区别？（数组+链表 vs 数组+链表+红黑树）\r\nHashMap 为什么线程不安全？扩容时的数据迁移过程是怎样的？\r\n并发工具类：\r\nCountDownLatch 和 CyclicBarrier 的区别是什么？\r\nThreadLocal 的原理及内存泄漏问题如何解决？\r\n设计模式：\r\n单例模式的几种写法（饿汉、懒汉、双重检查锁、静态内部类、枚举）。\r\n工厂模式和策略模式的应用场景。\r\nJVM 调优：\r\n常见的 GC 收集器有哪些（CMS, G1, ZGC）？它们的特点和适用场景是什么？\r\n如何排查 OOM（Out Of Memory）问题？\r\nSpring 相关（可选扩展）：\r\nSpring Bean 的生命周期。\r\nAOP 的实现原理（动态代理）。\r\n七、场景设计题（新增）\r\n高并发场景：\r\n如果有一个秒杀系统，库存只有 100 个，', 800, 'doc_7_chunk_3', '2026-05-08 16:12:59');
INSERT INTO `rag_document_chunk` VALUES (31, 7, 4, '如何防止超卖？（数据库乐观锁、Redis Lua 脚本、\r\n分布式锁等方案对比）\r\n大文件处理：\r\n如何在内存有限的情况下，读取并处理一个 10GB 的日志文件？（流式读取、NIO、分块处\r\n理）', 98, 'doc_7_chunk_4', '2026-05-08 16:12:59');
INSERT INTO `rag_document_chunk` VALUES (32, 8, 0, '你提供的这份《Java 核心知识题库》内容非常全面，涵盖了 Java 基础、面向对象、JVM、集合、并发、内存模型、异常处理、设计模式、面试高频题、场景设计等多个维度。如果你希望在此基础上“添加新的知识”，可以根据现有结构，按以下方式扩展内容：\r\n\r\n---\r\n\r\n## 一、新增题型示例\r\n\r\n### 1. 单选题（新增）\r\n\r\n**在 Java 中，以下哪个类是不可变类（Immutable Class）？**\r\n\r\nA. `StringBuilder`  \r\nB. `String`  \r\nC. `ArrayList`  \r\nD. `HashMap`\r\n\r\n**答案**：B\r\n\r\n---\r\n\r\n### 2. 多选题（新增）\r\n\r\n**以下哪些是 Java 8 引入的新特性？**\r\n\r\nA. Lambda 表达式  \r\nB. Stream API  \r\nC. `Optional` 类  \r\nD. `synchronized` 关键字\r\n\r\n**答案**：A, B, C\r\n\r\n---\r\n\r\n### 3. 填空题（新增）\r\n\r\n```java\r\npublic class Example {\r\n    public static void main(String[] args) {\r\n        List<String> list = Arrays.asList(\"a\", \"b\", \"c\");\r\n        String result = list.stream()\r\n            .filter(s -> s.equals(\"b\"))\r\n            .findFirst()\r\n            ._______; // 填空：获取值，避免空指针\r\n        System.out.println(result);\r\n    }\r\n}\r\n``', 800, 'doc_8_chunk_0', '2026-05-08 16:14:47');
INSERT INTO `rag_document_chunk` VALUES (33, 8, 1, '`\r\n\r\n**填空**：`orElse(null)`\r\n\r\n---\r\n\r\n## 二、新增知识点模块\r\n\r\n### 1. Java 模块化系统（JPMS）\r\n\r\n- **引入版本**：Java 9\r\n- **作用**：提高封装性、可维护性\r\n- **关键字**：`module`, `requires`, `exports`, `provides`, `uses`\r\n\r\n### 2. `record` 类（Java 14 预览，Java 17 正式）\r\n\r\n- 用于简化不可变数据类的定义\r\n- 自动生成构造方法、`equals()`、`hashCode()`、`toString()`\r\n\r\n```java\r\nrecord Point(int x, int y) {}\r\n```\r\n\r\n### 3. `sealed` 类（Java 17）\r\n\r\n- 限制哪些类可以继承或实现某个类/接口\r\n\r\n```java\r\nsealed class Shape permits Circle, Rectangle {}\r\n```\r\n\r\n### 4. 虚拟线程（Virtual Threads，Java 21）\r\n\r\n- 轻量级线程，提升高并发性能\r\n- 使用 `Thread.startVirtualThread()` 或 `Executors.newVirtualThreadPerTaskExecutor()`\r\n\r\n---\r\n\r\n## 三、新增场景设计题\r\n\r\n### 1. 热点缓存问题\r\n\r\n**如何设计一个热点缓存系统，防止缓存击穿、雪崩、穿透？**\r\n\r\n- **击穿**：使用互斥锁或逻辑过期\r\n- **雪崩**：设置随机过期时间\r\n- **穿透**：布隆过滤器 + 缓存空对象\r\n\r\n### 2. 分布式事务\r\n\r\n**在微服务架构中，如何保证多个服务之间的数据一致性？**\r\n\r\n- 两阶段', 800, 'doc_8_chunk_1', '2026-05-08 16:14:47');
INSERT INTO `rag_document_chunk` VALUES (34, 8, 2, '提交（2PC）\r\n- TCC（Try-Confirm-Cancel）\r\n- 最终一致性 + 消息队列（RocketMQ、Kafka）\r\n\r\n---\r\n\r\n## 四、新增代码纠错题\r\n\r\n```java\r\npublic class Counter {\r\n    private int count = 0;\r\n\r\n    public void increment() {\r\n        count++; // 问题：非原子操作，线程不安全\r\n    }\r\n\r\n    public int getCount() {\r\n        return count;\r\n    }\r\n}\r\n```\r\n\r\n**修正**：使用 `AtomicInteger` 或 `synchronized`。\r\n\r\n---\r\n\r\n## 五、新增简答题\r\n\r\n**什么是 JMX（Java Management Extensions）？**\r\n\r\n- 用于监控和管理 Java 应用程序\r\n- 核心组件：MBean、MBeanServer、JMX Agent\r\n\r\n---', 475, 'doc_8_chunk_2', '2026-05-08 16:14:47');
INSERT INTO `rag_document_chunk` VALUES (494, 20, 0, '<p>以下已按相同格式（无 <code>#</code> 号，但保留 Markdown 渲染效果）生成 <strong>Java 反射知识库</strong>：</p><hr><p><strong>Java 反射核心知识库</strong></p><hr><p><strong>一、反射简介</strong></p><ol><li><p><strong>概念</strong>：Java 反射机制允许程序在运行时获取任意类的内部信息（如成员变量、方法、构造器等），并能动态创建对象、调用方法、修改属性。</p></li><li><p><strong>作用</strong>：</p><ul><li><p>动态加载类、创建对象</p></li><li><p>访问私有成员（突破封装）</p></li><li><p>实现框架（如 Spring、MyBatis）的核心底层</p></li><li><p>运行时类型判断与处理</p></li></ul></li><li><p><strong>核心包</strong>：<code>java.lang.reflect</code></p></li></ol><hr><p><strong>二、反射的优缺点</strong></p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>优点</p></th><th colspan=\"1\" rowspan=\"1\"><p>缺点</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>提高程序灵活性和扩展性</p><', 800, 'doc_20_chunk_0', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (495, 20, 1, '/td><td colspan=\"1\" rowspan=\"1\"><p>性能较低（比直接调用慢）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>实现动态代理、框架解耦</p></td><td colspan=\"1\" rowspan=\"1\"><p>破坏封装性（可访问私有成员）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>适合开发通用框架和工具</p></td><td colspan=\"1\" rowspan=\"1\"><p>存在安全限制（SecurityManager）</p></td></tr></tbody></table><hr><p><strong>三、获取 Class 对象的三种方式</strong></p><pre><code class=\"language-java\">// 1. 通过类名.class（编译时已知）\nClass&lt;?&gt; clazz1 = User.class;', 452, 'doc_20_chunk_1', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (496, 20, 2, '// 2. 通过对象的 getClass() 方法\nUser user = new User();\nClass&lt;?&gt; clazz2 = user.getClass();', 90, 'doc_20_chunk_2', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (497, 20, 3, '// 3. 通过 Class.forName()（最灵活，运行时加载）\nClass&lt;?&gt; clazz3 = Class.forName(\"com.example.User\");\n</code></pre><hr><p><strong>四、通过反射创建对象</strong></p><pre><code class=\"language-java\">// 方式1：调用无参构造\nClass&lt;?&gt; clazz = Class.forName(\"com.example.User\");\nObject obj = clazz.newInstance();        // 已过时，推荐下方方式', 305, 'doc_20_chunk_3', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (498, 20, 4, '// 方式2：通过 Constructor 对象\nConstructor&lt;?&gt; constructor = clazz.getConstructor();\nObject obj2 = constructor.newInstance();', 124, 'doc_20_chunk_4', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (499, 20, 5, '// 方式3：调用有参构造\nConstructor&lt;?&gt; constructor2 = clazz.getConstructor(String.class, int.class);\nObject obj3 = constructor2.newInstance(\"张三\", 25);\n</code></pre><hr><p><strong>五、反射操作成员变量（Field）</strong></p><pre><code class=\"language-java\">Class&lt;?&gt; clazz = Class.forName(\"com.example.User\");', 295, 'doc_20_chunk_5', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (500, 20, 6, '// 获取所有公共字段（包括父类）\nField[] fields = clazz.getFields();', 53, 'doc_20_chunk_6', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (501, 20, 7, '// 获取所有声明的字段（包括私有，不包括父类）\nField[] declaredFields = clazz.getDeclaredFields();', 76, 'doc_20_chunk_7', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (502, 20, 8, '// 获取指定公共字段\nField nameField = clazz.getField(\"name\");', 53, 'doc_20_chunk_8', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (503, 20, 9, '// 获取指定私有字段\nField ageField = clazz.getDeclaredField(\"age\");', 59, 'doc_20_chunk_9', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (504, 20, 10, '// 访问私有字段（设置可访问）\nageField.setAccessible(true);', 46, 'doc_20_chunk_10', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (505, 20, 11, '// 设置字段值\nObject obj = clazz.newInstance();\nageField.set(obj, 25);', 65, 'doc_20_chunk_11', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (506, 20, 12, '// 获取字段值\nint age = (int) ageField.get(obj);\n</code></pre><hr><p><strong>六、反射操作方法（Method）</strong></p><pre><code class=\"language-java\">Class&lt;?&gt; clazz = Class.forName(\"com.example.User\");', 191, 'doc_20_chunk_12', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (507, 20, 13, '// 获取所有公共方法（包括父类）\nMethod[] methods = clazz.getMethods();', 56, 'doc_20_chunk_13', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (508, 20, 14, '// 获取所有声明的方法（不包括父类）\nMethod[] declaredMethods = clazz.getDeclaredMethods();', 74, 'doc_20_chunk_14', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (509, 20, 15, '// 获取指定公共方法\nMethod method1 = clazz.getMethod(\"getName\");', 56, 'doc_20_chunk_15', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (510, 20, 16, '// 获取指定私有方法\nMethod method2 = clazz.getDeclaredMethod(\"privateMethod\", String.class);', 84, 'doc_20_chunk_16', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (511, 20, 17, '// 调用方法\nObject obj = clazz.newInstance();\nString result = (String) method1.invoke(obj);', 87, 'doc_20_chunk_17', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (512, 20, 18, '// 调用私有方法\nmethod2.setAccessible(true);\nObject result2 = method2.invoke(obj, \"参数值\");\n</code></pre><hr><p><strong>七、反射操作构造器（Constructor）</strong></p><pre><code class=\"language-java\">Class&lt;?&gt; clazz = Class.forName(\"com.example.User\");', 237, 'doc_20_chunk_18', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (513, 20, 19, '// 获取所有公共构造器\nConstructor&lt;?&gt;[] constructors = clazz.getConstructors();', 75, 'doc_20_chunk_19', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (514, 20, 20, '// 获取所有声明的构造器\nConstructor&lt;?&gt;[] declaredConstructors = clazz.getDeclaredConstructors();', 92, 'doc_20_chunk_20', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (515, 20, 21, '// 获取指定构造器\nConstructor&lt;?&gt; constructor = clazz.getConstructor(String.class, int.class);', 92, 'doc_20_chunk_21', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (516, 20, 22, '// 创建对象\nObject obj = constructor.newInstance(\"李四\", 30);\n</code></pre><hr><p><strong>八、反射获取类信息</strong></p><pre><code class=\"language-java\">Class&lt;?&gt; clazz = Class.forName(\"com.example.User\");', 196, 'doc_20_chunk_22', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (517, 20, 23, '// 获取类名\nString className = clazz.getName();           // 全限定名：com.example.User\nString simpleName = clazz.getSimpleName();    // 简单名：User', 136, 'doc_20_chunk_23', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (518, 20, 24, '// 获取包名\nPackage pkg = clazz.getPackage();\nString packageName = pkg.getName();', 77, 'doc_20_chunk_24', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (519, 20, 25, '// 获取修饰符\nint modifiers = clazz.getModifiers();\nboolean isPublic = Modifier.isPublic(modifiers);\nboolean isAbstract = Modifier.isAbstract(modifiers);', 148, 'doc_20_chunk_25', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (520, 20, 26, '// 获取父类\nClass&lt;?&gt; superclass = clazz.getSuperclass();', 58, 'doc_20_chunk_26', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (521, 20, 27, '// 获取接口\nClass&lt;?&gt;[] interfaces = clazz.getInterfaces();', 60, 'doc_20_chunk_27', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (522, 20, 28, '// 判断类型\nboolean isArray = clazz.isArray();\nboolean isEnum = clazz.isEnum();\nboolean isInterface = clazz.isInterface();\n</code></pre><hr><p><strong>九、反射操作数组</strong></p><pre><code class=\"language-java\">// 创建数组\nClass&lt;?&gt; arrayClass = Class.forName(\"[Ljava.lang.String;\");  // String[]\nObject array = Array.newInstance(String.class, 5);', 338, 'doc_20_chunk_28', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (523, 20, 29, '// 设置数组元素\nArray.set(array, 0, \"元素1\");\nArray.set(array, 1, \"元素2\");', 65, 'doc_20_chunk_29', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (524, 20, 30, '// 获取数组元素\nString element = (String) Array.get(array, 0);', 56, 'doc_20_chunk_30', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (525, 20, 31, '// 获取数组长度\nint length = Array.getLength(array);\n</code></pre><hr><p><strong>十、反射注解处理</strong></p><pre><code class=\"language-java\">// 获取类上的注解\nClass&lt;?&gt; clazz = Class.forName(\"com.example.User\");\nAnnotation[] annotations = clazz.getAnnotations();', 248, 'doc_20_chunk_31', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (526, 20, 32, '// 获取指定注解\nMyAnnotation annotation = clazz.getAnnotation(MyAnnotation.class);', 76, 'doc_20_chunk_32', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (527, 20, 33, '// 获取方法上的注解\nMethod method = clazz.getMethod(\"getName\");\nAnnotation[] methodAnnotations = method.getAnnotations();', 113, 'doc_20_chunk_33', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (528, 20, 34, '// 判断是否有注解\nboolean hasAnnotation = method.isAnnotationPresent(MyAnnotation.class);\n</code></pre><hr><p><strong>十一、反射示例代码（完整）</strong></p><pre><code class=\"language-java\">// 实体类\npublic class User {\n    private String name;\n    private int age;', 242, 'doc_20_chunk_34', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (529, 20, 35, 'public User() {}\n    public User(String name, int age) {\n        this.name = name;\n        this.age = age;\n    }', 112, 'doc_20_chunk_35', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (530, 20, 36, 'private String getSecretInfo() {\n        return \"私有方法返回的秘密信息\";\n    }', 68, 'doc_20_chunk_36', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (531, 20, 37, 'public void sayHello() {\n        System.out.println(\"Hello, I\'m \" + name);\n    }\n}', 82, 'doc_20_chunk_37', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (532, 20, 38, '// 反射操作演示\npublic class ReflectionDemo {\n    public static void main(String[] args) throws Exception {\n        // 1. 获取 Class 对象\n        Class&lt;?&gt; clazz = Class.forName(\"com.example.User\");', 193, 'doc_20_chunk_38', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (533, 20, 39, '// 2. 创建对象\n        Constructor&lt;?&gt; constructor = clazz.getConstructor(String.class, int.class);\n        Object obj = constructor.newInstance(\"王五\", 28);', 156, 'doc_20_chunk_39', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (534, 20, 40, '// 3. 调用公共方法\n        Method sayHello = clazz.getMethod(\"sayHello\");\n        sayHello.invoke(obj);', 97, 'doc_20_chunk_40', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (535, 20, 41, '// 4. 访问私有字段\n        Field nameField = clazz.getDeclaredField(\"name\");\n        nameField.setAccessible(true);\n        nameField.set(obj, \"赵六\");\n        System.out.println(\"修改后的名字：\" + nameField.get(obj));', 203, 'doc_20_chunk_41', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (536, 20, 42, '// 5. 调用私有方法\n        Method privateMethod = clazz.getDeclaredMethod(\"getSecretInfo\");\n        privateMethod.setAccessible(true);\n        String result = (String) privateMethod.invoke(obj);\n        System.out.println(\"私有方法返回：\" + result);\n    }\n}\n</code></pre><hr><p><strong>十二、反射常用工具方法（封装）</strong></p><pre><code class=\"language-java\">public class ReflectionUtil {', 363, 'doc_20_chunk_42', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (537, 20, 43, '// 获取所有字段（包括父类私有字段）\n    public static List&lt;Field&gt; getAllFields(Class&lt;?&gt; clazz) {\n        List&lt;Field&gt; fields = new ArrayList&lt;&gt;();\n        while (clazz != null &amp;&amp; clazz != Object.class) {\n            fields.addAll(Arrays.asList(clazz.getDeclaredFields()));\n            clazz = clazz.getSuperclass();\n        }\n        return fields;\n    }', 368, 'doc_20_chunk_43', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (538, 20, 44, '// 递归查找方法（包括父类）\n    public static Method getMethodRecursive(Class&lt;?&gt; clazz, String methodName, Class&lt;?&gt;... paramTypes) {\n        try {\n            return clazz.getDeclaredMethod(methodName, paramTypes);\n        } catch (NoSuchMethodException e) {\n            if (clazz.getSuperclass() != null) {\n                return getMethodRecursive(clazz.getSuperclass(), methodName, paramTypes);\n            }\n        }\n        return null;\n    }', 448, 'doc_20_chunk_44', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (539, 20, 45, '// 设置字段值（自动处理私有和继承）\n    public static void setFieldValue(Object target, String fieldName, Object value) throws Exception {\n        Field field = getFieldRecursive(target.getClass(), fieldName);\n        if (field != null) {\n            field.setAccessible(true);\n            field.set(target, value);\n        }\n    }', 315, 'doc_20_chunk_45', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (540, 20, 46, 'private static Field getFieldRecursive(Class&lt;?&gt; clazz, String fieldName) {\n        try {\n            return clazz.getDeclaredField(fieldName);\n        } catch (NoSuchFieldException e) {\n            if (clazz.getSuperclass() != null) {\n                return getFieldRecursive(clazz.getSuperclass(), fieldName);\n            }\n        }\n        return null;\n    }\n}\n</code></pre><hr><p><strong>十三、常见异常</strong></p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>异常</p></th><th colspan=\"1\" rowspan=\"1\"><p>原因</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>ClassNotFoundException</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>类名错误或类路径不存在</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p', 800, 'doc_20_chunk_46', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (541, 20, 47, '><code>NoSuchMethodException</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>方法名或参数类型不匹配</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>NoSuchFieldException</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>字段名不存在</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>IllegalAccessException</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>无法访问（未调用 <code>setAccessible(true)</code>）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>InvocationTargetException</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>被调用方法内部抛出了异常</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>InstantiationException</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>无法实例化（如抽象类、接口）</p></td></tr></tbody></table><hr><p><strong>十四、性能优化建议</strong></p><ol><li><p><strong>缓存 Class 对象</strong>：避免重复调用 <code>Class.forName()</code><', 800, 'doc_20_chunk_47', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (542, 20, 48, '/p></li><li><p><strong>缓存 Method / Field / Constructor</strong>：反射对象创建成本较高</p></li><li><p><strong>关闭访问检查</strong>：<code>setAccessible(true)</code> 可提升性能（约 1.5-2 倍）</p></li><li><p><strong>优先使用直接调用</strong>：非必要场景避免使用反射</p></li><li><p><strong>使用 MethodHandle</strong>（Java 7+）作为反射的高性能替代</p></li></ol><pre><code class=\"language-java\">// 缓存示例\npublic class ReflectionCache {\n    private static final Map&lt;String, Method&gt; METHOD_CACHE = new ConcurrentHashMap&lt;&gt;();', 467, 'doc_20_chunk_48', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (543, 20, 49, 'public static Method getCachedMethod(Class&lt;?&gt; clazz, String methodName, Class&lt;?&gt;... paramTypes) {\n        String key = clazz.getName() + \"#\" + methodName + Arrays.toString(paramTypes);\n        return METHOD_CACHE.computeIfAbsent(key, k -&gt; {\n            try {\n                return clazz.getDeclaredMethod(methodName, paramTypes);\n            } catch (NoSuchMethodException e) {\n                return null;\n            }\n        });\n    }\n}\n</code></pre><hr><p><strong>十五、反射的应用场景</strong></p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>场景</p></th><th colspan=\"1\" rowspan=\"1\"><p>说明</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Spring IoC</strong></p></td><td cols', 800, 'doc_20_chunk_49', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (544, 20, 50, 'pan=\"1\" rowspan=\"1\"><p>动态创建 Bean、依赖注入</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Spring AOP</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>动态代理生成代理对象</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>MyBatis</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>将数据库结果集映射到 POJO</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>JUnit</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>动态查找和执行 <code>@Test</code> 方法</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Jackson / Gson</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>JSON 序列化/反序列化</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>注解处理器</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>运行时读取注解并执行逻辑</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>开发工具</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>代码分', 800, 'doc_20_chunk_50', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (545, 20, 51, '析、调试、热部署</p></td></tr></tbody></table><hr><p></p>', 49, 'doc_20_chunk_51', '2026-05-12 15:56:05');
INSERT INTO `rag_document_chunk` VALUES (546, 21, 0, '<p></p><hr><p><strong>反射的核心作用</strong></p><hr><p><strong>1. 运行时获取类的完整信息</strong></p><p>可以在程序运行时动态获取任意类的构造器、方法、字段、注解、父类、接口等信息，而不需要在编译时知道类的具体名称。</p><pre><code class=\"language-java\">// 运行时获取类的所有方法\nClass&lt;?&gt; clazz = Class.forName(\"com.example.User\");\nMethod[] methods = clazz.getDeclaredMethods();\n</code></pre><hr><p><strong>2. 动态创建对象</strong></p><p>可以在运行时根据类名动态创建实例，而不是在代码中写死 <code>new</code> 关键字。</p><pre><code class=\"language-java\">// 动态创建对象\nObject obj = Class.forName(\"com.example.User\").newInstance();\n</code></pre><hr><p><strong>3. 动态调用方法</strong></p><p>可以在运行时决定调用哪个对象的哪个方法，方法名可以作为字符串参数传入。</p><pre><code class=\"language-java\">// 动态调用方法\nMethod method = obj.getClass().getMethod(\"sayHello\");\nmethod.invoke(obj);\n</code></pre><hr><p><strong>4. 访问和修改私有成员</strong></p><p>可以绕过 <code>private</code> ', 800, 'doc_21_chunk_0', '2026-05-12 16:25:28');
INSERT INTO `rag_document_chunk` VALUES (547, 21, 1, '访问限制，读取或修改私有字段、调用私有方法（常用于框架和工具开发）。</p><pre><code class=\"language-java\">// 访问私有字段\nField field = clazz.getDeclaredField(\"password\");\nfield.setAccessible(true);  // 突破封装\nString pwd = (String) field.get(user);\n</code></pre><hr><p><strong>5. 动态处理注解</strong></p><p>可以在运行时读取类、方法、字段上的注解，根据注解执行相应逻辑（这是 Spring、JUnit 等框架的基础）。</p><pre><code class=\"language-java\">// 读取注解\nif (method.isAnnotationPresent(MyAnnotation.class)) {\n    MyAnnotation anno = method.getAnnotation(MyAnnotation.class);\n    String value = anno.value();\n}\n</code></pre><hr><p><strong>6. 操作数组</strong></p><p>可以通过反射动态创建和操作数组，适用于泛型或运行时类型未知的场景。</p><pre><code class=\"language-java\">// 动态创建数组\nObject array = Array.newInstance(String.class, 10);\nArray.set(array, 0, \"元素1\");\n</code></pre><hr><p><strong>7. 实现通用框架和工具</strong></p><p>反射是几乎所有 Java 框架的底层基', 800, 'doc_21_chunk_1', '2026-05-12 16:25:28');
INSERT INTO `rag_document_chunk` VALUES (548, 21, 2, '础：</p><ul><li><p><strong>Spring</strong>：通过反射创建 Bean、依赖注入、AOP 代理</p></li><li><p><strong>MyBatis / Hibernate</strong>：通过反射将数据库结果映射到 Java 对象</p></li><li><p><strong>JUnit</strong>：通过反射查找和执行 <code>@Test</code> 方法</p></li><li><p><strong>Jackson / Gson</strong>：通过反射实现 JSON 与对象互转</p></li></ul><hr><p><strong>8. 打破类型约束，提高代码灵活性</strong></p><p>可以在不修改原有代码的情况下，动态扩展功能、实现热加载、处理泛型擦除等。</p><pre><code class=\"language-java\">// 绕过泛型检查（谨慎使用）\nList&lt;String&gt; list = new ArrayList&lt;&gt;();\nMethod method = list.getClass().getMethod(\"add\", Object.class);\nmethod.invoke(list, 123);  // 可以存入非 String 类型\n</code></pre><hr><p><strong>一句话总结</strong></p><blockquote><p><strong>反射让 Java 程序从「编译时确定」变成「运行时动态」，这是框架、注解、动态代理等高级特性的底层基石。</strong></p></blockquote><hr><p><strong>使用场景速查表</strong></p><table style=\"min-width: 50px;\"><', 800, 'doc_21_chunk_2', '2026-05-12 16:25:28');
INSERT INTO `rag_document_chunk` VALUES (549, 21, 3, 'colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>场景</p></th><th colspan=\"1\" rowspan=\"1\"><p>典型代表</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>框架设计</p></td><td colspan=\"1\" rowspan=\"1\"><p>Spring、MyBatis、Hibernate</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>单元测试</p></td><td colspan=\"1\" rowspan=\"1\"><p>JUnit、TestNG</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>数据转换</p></td><td colspan=\"1\" rowspan=\"1\"><p>Jackson、Gson、Fastjson</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>动态代理</p></td><td colspan=\"1\" rowspan=\"1\"><p>JDK Proxy、CGLIB</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>代码分析</p></td><td colspan=\"1\" rowspan=\"1\"><p>IDEA 插件、代码检查工具</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>注解处理</p></td><td colspan=\"1\" row', 800, 'doc_21_chunk_3', '2026-05-12 16:25:28');
INSERT INTO `rag_document_chunk` VALUES (550, 21, 4, 'span=\"1\"><p>Lombok、@Autowired 等</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>热部署/插件化</p></td><td colspan=\"1\" rowspan=\"1\"><p>OSGi、Java Agent</p></td></tr></tbody></table><hr><p><strong>注意事项提醒</strong></p><ul><li><p>反射有一定的<strong>性能损耗</strong>（比直接调用慢）</p></li><li><p>会<strong>破坏封装性</strong>（可访问私有成员）</p></li><li><p>受 <strong>SecurityManager</strong> 安全限制</p></li><li><p>非必要场景<strong>优先使用直接调用</strong></p></li></ul><hr><p></p>', 426, 'doc_21_chunk_4', '2026-05-12 16:25:28');
INSERT INTO `rag_document_chunk` VALUES (551, 22, 0, '<p>以下是 <strong>Java 堆和栈</strong> 的核心知识库，按同样格式整理：</p><hr><p><strong>Java 内存管理 —— 堆（Heap）与栈（Stack）</strong></p><hr><p><strong>一、基本概念</strong></p><p>Java 虚拟机（JVM）将内存主要划分为以下几个区域，其中<strong>堆</strong>和<strong>栈</strong>是最核心的两个：</p><table style=\"min-width: 100px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>内存区域</p></th><th colspan=\"1\" rowspan=\"1\"><p>全称</p></th><th colspan=\"1\" rowspan=\"1\"><p>线程共享</p></th><th colspan=\"1\" rowspan=\"1\"><p>存储内容</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>堆</p></td><td colspan=\"1\" rowspan=\"1\"><p>Heap</p></td><td colspan=\"1\" rowspan=\"1\"><p>是</p></td><td colspan=\"1\" rowspan=\"1\"><p>对象实例、数组</p></td></tr><tr><td colspan=\"1\" rowspan=\"', 800, 'doc_22_chunk_0', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (552, 22, 1, '1\"><p>栈</p></td><td colspan=\"1\" rowspan=\"1\"><p>Java Virtual Machine Stack</p></td><td colspan=\"1\" rowspan=\"1\"><p>否（每个线程私有）</p></td><td colspan=\"1\" rowspan=\"1\"><p>局部变量、方法调用、操作数栈</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>方法区</p></td><td colspan=\"1\" rowspan=\"1\"><p>Method Area</p></td><td colspan=\"1\" rowspan=\"1\"><p>是</p></td><td colspan=\"1\" rowspan=\"1\"><p>类信息、静态变量、常量</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>程序计数器</p></td><td colspan=\"1\" rowspan=\"1\"><p>Program Counter Register</p></td><td colspan=\"1\" rowspan=\"1\"><p>否</p></td><td colspan=\"1\" rowspan=\"1\"><p>当前线程执行的字节码行号</p></td></tr></tbody></table><blockquote><p>本知识库重点讲解 <strong>堆</strong> 和 <strong>栈</strong> 的区别与联系</p></blockquote><hr><p><strong>二、堆（Heap）详解</strong></p><p><strong>2.1 定义</strong></p><ul><li><p>堆是 JVM 管理的<strong>最大内', 800, 'doc_22_chunk_1', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (553, 22, 2, '存区域</strong></p></li><li><p>所有线程<strong>共享</strong>同一个堆</p></li><li><p>用于存储<strong>对象实例</strong>和<strong>数组</strong></p></li><li><p>通过 <code>new</code> 关键字创建的对象都存放在堆中</p></li></ul><p><strong>2.2 特点</strong></p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>特性</p></th><th colspan=\"1\" rowspan=\"1\"><p>说明</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>生命周期</p></td><td colspan=\"1\" rowspan=\"1\"><p>对象不再被引用时，由 GC（垃圾回收器）回收</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>访问方式</p></td><td colspan=\"1\" rowspan=\"1\"><p>通过栈中的引用来访问堆中的对象</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>内存大小</p></td><td colspan=\"1\" rowspan=\"1\"><p>相对较大，可通过 <code>-Xms</code>（初始）和 <code>-Xmx</code>（最大）调整</p></td></tr><tr><t', 800, 'doc_22_chunk_2', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (554, 22, 3, 'd colspan=\"1\" rowspan=\"1\"><p>线程安全</p></td><td colspan=\"1\" rowspan=\"1\"><p>需要考虑线程安全问题（多线程共享）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>存储内容</p></td><td colspan=\"1\" rowspan=\"1\"><p>对象实例、数组、成员变量</p></td></tr></tbody></table><p><strong>2.3 堆的内存结构（JVM 分代模型）</strong></p><pre><code class=\"language-text\">┌─────────────────────────────────────────┐\n│              堆（Heap）                   │\n│  ┌─────────────────────────────────────┐ │\n│  │         年轻代（Young Generation）    │ │\n│  │  ┌─────┐ ┌─────┐ ┌──────────────┐  │ │\n│  │  │Eden │ │S0   │ │   S1 (Survivor)│  │ │\n│  │  └─────┘ └─────┘ └──────────────┘  │ │\n│  └─────────────────────────────────────┘ │\n│  ┌─────────────────────────────────────┐ │\n│  │         老年代（Old Generation）      │ │\n│  └─────────────────────────────────────┘ │\n└────────────', 800, 'doc_22_chunk_3', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (555, 22, 4, '─────────────────────────────┘\n</code></pre><ul><li><p><strong>Eden 区</strong>：新创建的对象首先存放在这里</p></li><li><p><strong>Survivor 区（S0 / S1）</strong>：Minor GC 后存活的对象复制到这里</p></li><li><p><strong>老年代</strong>：长期存活的对象晋升到这里</p></li><li><p><strong>元空间（JDK 8+）</strong>：原永久代，存储类元数据，不在堆中</p></li></ul><p><strong>2.4 堆内存配置参数</strong></p><pre><code class=\"language-bash\"># 初始堆大小\n-Xms512m', 373, 'doc_22_chunk_4', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (556, 22, 5, '# 最大堆大小\n-Xmx2048m', 17, 'doc_22_chunk_5', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (557, 22, 6, '# 新生代大小\n-Xmn256m', 16, 'doc_22_chunk_6', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (558, 22, 7, '# 查看堆使用情况\njmap -heap &lt;pid&gt;\n</code></pre><hr><p><strong>三、栈（Stack）详解</strong></p><p><strong>3.1 定义</strong></p><ul><li><p>栈是<strong>线程私有</strong>的内存区域</p></li><li><p>每个线程都有自己的栈，互不干扰</p></li><li><p>每个方法调用都会创建一个<strong>栈帧（Stack Frame）</strong></p></li></ul><p><strong>3.2 栈帧的结构</strong></p><pre><code class=\"language-text\">┌─────────────────────────────┐\n│      栈帧（Stack Frame）      │\n├─────────────────────────────┤\n│  局部变量表（Local Variables） │ ← 存储方法参数和局部变量\n├─────────────────────────────┤\n│  操作数栈（Operand Stack）    │ ← 存储计算过程中的中间结果\n├─────────────────────────────┤\n│  动态链接（Dynamic Linking）  │ ← 指向运行时常量池的符号引用\n├─────────────────────────────┤\n│  方法返回地址（Return Address）│ ← 方法执行后返回的位置\n└─────────────────────────────┘\n</code></pre><p><strong>3.3 特点</strong></p><table style=\"min-width: 50px;\"><colgrou', 800, 'doc_22_chunk_7', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (559, 22, 8, 'p><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>特性</p></th><th colspan=\"1\" rowspan=\"1\"><p>说明</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>生命周期</p></td><td colspan=\"1\" rowspan=\"1\"><p>线程创建时产生，线程结束时销毁</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>访问方式</p></td><td colspan=\"1\" rowspan=\"1\"><p>自动分配和释放，无需 GC</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>内存大小</p></td><td colspan=\"1\" rowspan=\"1\"><p>相对较小（默认 1MB），可通过 <code>-Xss</code> 调整</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>线程安全</p></td><td colspan=\"1\" rowspan=\"1\"><p>线程私有，天然线程安全</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>存储内容</p></td><td colspan=\"1\" rowspan=\"1\"><p>局部变量、方法参数、操作数栈、返回地址</p></td></tr></tbody></table><p><strong>3.4 栈的两种操作</strong></p><ul><li><p><stron', 800, 'doc_22_chunk_8', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (560, 22, 9, 'g>压栈（push）</strong>：调用方法时，创建栈帧并压入栈顶</p></li><li><p><strong>出栈（pop）</strong>：方法执行完毕，栈帧从栈顶弹出</p></li></ul><p><strong>3.5 栈内存配置参数</strong></p><pre><code class=\"language-bash\"># 每个线程栈大小\n-Xss1m', 188, 'doc_22_chunk_9', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (561, 22, 10, '# 默认值（取决于操作系统和 JVM）\n# Linux 64位：1MB\n# Windows 64位：1MB\n</code></pre><hr><p><strong>四、堆与栈的核心区别</strong></p><table style=\"min-width: 75px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>对比维度</p></th><th colspan=\"1\" rowspan=\"1\"><p>堆（Heap）</p></th><th colspan=\"1\" rowspan=\"1\"><p>栈（Stack）</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>存储内容</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>对象实例、数组、成员变量</p></td><td colspan=\"1\" rowspan=\"1\"><p>局部变量、方法调用、操作数栈</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>线程共享</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>是（所有线程共享）</p></td><td colspan=\"1\" rowspan=\"1\"><p>否（每个线程私有）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>生命周期</stro', 800, 'doc_22_chunk_10', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (562, 22, 11, 'ng></p></td><td colspan=\"1\" rowspan=\"1\"><p>对象不再被引用时由 GC 回收</p></td><td colspan=\"1\" rowspan=\"1\"><p>方法执行结束自动释放</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>内存大小</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>大（通常几 GB）</p></td><td colspan=\"1\" rowspan=\"1\"><p>小（通常 1MB）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>访问速度</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>较慢（需要 GC 和指针操作）</p></td><td colspan=\"1\" rowspan=\"1\"><p>较快（直接压栈出栈）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>内存管理</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p>自动（GC 管理）</p></td><td colspan=\"1\" rowspan=\"1\"><p>自动（帧入帧出）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>异常类型</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><code>OutOfMemoryError: Java heap space</code></p></td><td colspan=\"1\" r', 800, 'doc_22_chunk_11', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (563, 22, 12, 'owspan=\"1\"><p><code>StackOverflowError</code></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>调整参数</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><code>-Xms</code>, <code>-Xmx</code></p></td><td colspan=\"1\" rowspan=\"1\"><p><code>-Xss</code></p></td></tr></tbody></table><hr><p><strong>五、内存中的引用关系</strong></p><pre><code class=\"language-text\">        栈（线程私有）                    堆（线程共享）\n    ┌─────────────────┐            ┌─────────────────────┐\n    │    main() 栈帧   │            │                     │\n    │ ┌─────────────┐ │            │    ┌─────────────┐  │\n    │ │ 局部变量 user │─┼────────────┼───→│ User 对象   │  │\n    │ │   (引用)     │ │            │    │ name=\"张三\" │  │\n    │ └─────────────┘ │            │    │ age=25      │  │\n    └─────────────────┘            │    └─────────────┘  │\n   ', 800, 'doc_22_chunk_12', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (564, 22, 13, '                                │                     │\n    ┌─────────────────┐            │    ┌─────────────┐  │\n    │   method() 栈帧  │            │    │  int[] 数组 │  │\n    │ ┌─────────────┐ │            │    │ [1,2,3,4,5] │  │\n    │ │ 局部变量 arr │─┼────────────┼───→ │             │  │\n    │ │   (引用)     │ │            │    └─────────────┘  │\n    │ └─────────────┘ │            │                     │\n    └─────────────────┘            └─────────────────────┘\n</code></pre><ul><li><p><strong>栈中的变量存的是引用地址</strong>，真正的对象在堆中</p></li><li><p>基本类型（int, boolean, char 等）的值直接存在栈中</p></li></ul><hr><p><strong>六、不同数据类型的内存分配</strong></p><pre><code class=\"language-java\">public class MemoryDemo {\n    int instanceVar = 10;      // 成员变量 → 堆\n    static int staticVar = 20; // 静态变量 → 方法区（元空间）', 781, 'doc_22_chunk_13', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (565, 22, 14, 'public void method() {\n        int localVar = 30;           // 局部变量 → 栈\n        String str = \"hello\";        // str 引用 → 栈，字符串常量 → 堆/方法区\n        User user = new User();      // user 引用 → 栈，User 对象 → 堆\n        int[] arr = new int[5];      // arr 引用 → 栈，数组对象 → 堆\n    }\n}\n</code></pre><table style=\"min-width: 75px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>变量类型</p></th><th colspan=\"1\" rowspan=\"1\"><p>存储位置</p></th><th colspan=\"1\" rowspan=\"1\"><p>说明</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>局部变量（基本类型）</p></td><td colspan=\"1\" rowspan=\"1\"><p>栈</p></td><td colspan=\"1\" rowspan=\"1\"><p>值直接存储在栈中</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>局部变量（引用类型）</p></td><td colspan=\"1\" rowspan=\"1\"', 800, 'doc_22_chunk_14', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (566, 22, 15, '><p>栈</p></td><td colspan=\"1\" rowspan=\"1\"><p>引用在栈中，对象在堆中</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>成员变量（实例变量）</p></td><td colspan=\"1\" rowspan=\"1\"><p>堆</p></td><td colspan=\"1\" rowspan=\"1\"><p>属于对象，存储在堆中</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>静态变量（类变量）</p></td><td colspan=\"1\" rowspan=\"1\"><p>方法区</p></td><td colspan=\"1\" rowspan=\"1\"><p>属于类，存储在方法区/元空间</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>常量（字面量）</p></td><td colspan=\"1\" rowspan=\"1\"><p>堆/方法区</p></td><td colspan=\"1\" rowspan=\"1\"><p>字符串常量池在堆中（JDK 7+）</p></td></tr></tbody></table><hr><p><strong>七、常见异常及原因</strong></p><p><strong>7.1 栈溢出（StackOverflowError）</strong></p><pre><code class=\"language-java\">// 无限递归调用 → 栈帧不断压栈，超出栈深度\npublic void recursive() {\n    recursive();  // 最终抛出 StackOverflowError\n}\n</code></pre><p><strong>原因</stro', 800, 'doc_22_chunk_15', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (567, 22, 16, 'ng>：</p><ul><li><p>递归调用过深没有终止条件</p></li><li><p>方法调用层次过多</p></li><li><p>线程栈帧过大</p></li></ul><p><strong>解决方案</strong>：</p><ul><li><p>增加栈内存：<code>-Xss2m</code></p></li><li><p>优化递归算法（改为迭代）</p></li><li><p>检查是否存在死循环调用</p></li></ul><p><strong>7.2 堆溢出（OutOfMemoryError: Java heap space）</strong></p><pre><code class=\"language-java\">// 不断创建对象，强引用无法被 GC 回收\nList&lt;Object&gt; list = new ArrayList&lt;&gt;();\nwhile (true) {\n    list.add(new byte[1024 * 1024]);  // 每次1MB，最终 OOM\n}\n</code></pre><p><strong>原因</strong>：</p><ul><li><p>内存泄漏（对象被持续引用无法回收）</p></li><li><p>创建的对象过大或过多</p></li><li><p>堆内存设置过小</p></li></ul><p><strong>解决方案</strong>：</p><ul><li><p>增加堆内存：<code>-Xmx2g -Xms2g</code></p></li><li><p>分析堆转储文件（<code>jmap -dump</code>）</p></li><li><p>修复内存泄漏（使用 MAT、JProfiler 等工具）</p></li></ul><hr><p><strong>八、性能优化建', 800, 'doc_22_chunk_16', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (568, 22, 17, '议</strong></p><p><strong>8.1 堆优化</strong></p><pre><code class=\"language-bash\"># 1. 合理设置堆大小（避免频繁 GC）\n-Xms2048m -Xmx2048m', 119, 'doc_22_chunk_17', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (569, 22, 18, '# 2. 设置新生代大小（调整对象晋升阈值）\n-Xmn512m', 31, 'doc_22_chunk_18', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (570, 22, 19, '# 3. 选择适合的 GC 算法\n-XX:+UseG1GC          # JDK 9+ 默认\n-XX:+UseConcMarkSweepGC  # CMS（已弃用）\n</code></pre><p><strong>8.2 栈优化</strong></p><pre><code class=\"language-bash\"># 1. 递归场景增加栈大小\n-Xss2m', 185, 'doc_22_chunk_19', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (571, 22, 20, '# 2. 减少局部变量数量（减小栈帧体积）\n# 3. 避免深层嵌套调用\n</code></pre><p><strong>8.3 编码建议</strong></p><pre><code class=\"language-java\">// 1. 及时释放无用对象引用\nlargeObject = null;  // 帮助 GC 回收', 163, 'doc_22_chunk_20', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (572, 22, 21, '// 2. 使用局部变量代替成员变量（栈比堆快）\npublic void method() {\n    int local = 10;   // 栈访问，速度快\n    this.member = 10; // 堆访问，速度慢\n}', 115, 'doc_22_chunk_21', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (573, 22, 22, '// 3. 避免在循环中创建对象\n// ❌ 坏做法\nfor (int i = 0; i &lt; 10000; i++) {\n    String s = new String(\"test\");  // 产生大量对象\n}', 110, 'doc_22_chunk_22', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (574, 22, 23, '// ✅ 好做法\nString s = new String(\"test\");\nfor (int i = 0; i &lt; 10000; i++) {\n    // 复用同一个对象\n}\n</code></pre><hr><p><strong>九、JDK 8 与 JDK 7 的变化</strong></p><table style=\"min-width: 75px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>变化点</p></th><th colspan=\"1\" rowspan=\"1\"><p>JDK 7 及以前</p></th><th colspan=\"1\" rowspan=\"1\"><p>JDK 8+</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>永久代</p></td><td colspan=\"1\" rowspan=\"1\"><p>存在（PermGen）</p></td><td colspan=\"1\" rowspan=\"1\"><p>移除</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>替代方案</p></td><td colspan=\"1\" rowspan=\"1\"><p>-</p></td><td colspan=\"1\" rowspan=\"1\"><p>元空间（Metaspace）</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>字符串常量池</p></td><td co', 800, 'doc_22_chunk_23', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (575, 22, 24, 'lspan=\"1\" rowspan=\"1\"><p>永久代中</p></td><td colspan=\"1\" rowspan=\"1\"><p>堆中</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>静态变量</p></td><td colspan=\"1\" rowspan=\"1\"><p>永久代中</p></td><td colspan=\"1\" rowspan=\"1\"><p>堆中</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>元空间位置</p></td><td colspan=\"1\" rowspan=\"1\"><p>-</p></td><td colspan=\"1\" rowspan=\"1\"><p>本地内存（Native Memory）</p></td></tr></tbody></table><pre><code class=\"language-bash\"># JDK 8+ 元空间参数\n-XX:MetaspaceSize=128m     # 初始元空间大小\n-XX:MaxMetaspaceSize=256m  # 最大元空间大小\n</code></pre><hr><p><strong>十、面试常考题</strong></p><p><strong>1. Java 中的基本类型和引用类型分别存在哪里？</strong></p><blockquote><p>基本类型的<strong>局部变量</strong>存在栈中，<strong>成员变量</strong>存在堆中。引用类型的<strong>引用</strong>在栈中，<strong>对象本身</strong>在堆中。</p></blockquote><p><strong>2. 为什么需要堆和栈的划分？</strong></p><bloc', 800, 'doc_22_chunk_24', '2026-05-12 16:40:45');
INSERT INTO `rag_document_chunk` VALUES (576, 22, 25, 'kquote><p>栈负责方法执行的顺序和退出（LIFO），堆负责对象的生命周期管理（GC）。职责分离，各司其职。</p></blockquote><p><strong>3. 类中的静态变量存在哪里？</strong></p><blockquote><p>JDK 7 及以前在永久代（PermGen），JDK 8+ 在堆中。</p></blockquote><p><strong>4. 栈上分配是什么？</strong></p><blockquote><p>JVM 的逃逸分析优化。如果对象不会逃逸出方法，可能会在栈上分配，避免 GC 压力。JDK 6u23+ 默认开启。</p></blockquote><p><strong>5. 如何定位堆内存泄漏？</strong></p><blockquote><p>使用 <code>jmap</code> 导出堆转储文件，用 MAT、JProfiler、VisualVM 等工具分析 GC Roots 和对象引用链。</p></blockquote><hr><p></p>', 459, 'doc_22_chunk_25', '2026-05-12 16:40:45');
INSERT INTO `rag_knowledge_base` VALUES (1, 1, 'C++知识库', '', '', 0, 1, '2026-05-04 01:16:20', '2026-05-04 01:17:13');
INSERT INTO `rag_knowledge_base` VALUES (2, 1, 'Java知识库', '', '', 0, 5, '2026-05-04 01:17:54', '2026-05-12 16:40:45');
INSERT INTO `rag_qa_record` VALUES (1, 1, 1, '你的知识库里有什么内容', '我的C++知识库包含以下主要内容：\n\n## 1. 基础语法\n- Hello World程序示例\n- 基本数据类型（int、float/double、char、bool）及其大小\n\n## 2. 面向对象编程\n- 类与对象的定义和使用\n- 三大特性：封装、继承、多态\n- 多态的具体实现示例\n\n## 3. 内存管理\n- 动态内存分配与释放\n- 智能指针（unique_ptr、shared_ptr、weak_ptr）\n\n## 4. STL标准模板库\n- 容器（vector、list、map、unordered_set等）\n- 算法（sort、reverse、find等）\n\n## 5. 现代C++特性\n- 资源获取即初始化（RAII）模式\n- FileHandler类的RAII实现示例\n\n## 6. 常见面试题\n- 虚函数表工作原理\n- 深拷贝与浅拷贝区别\n- static关键字的各种作用\n\n## 7. 编译与链接\n- 编译四步骤（预处理、编译、汇编、链接）\n- 命令行编译示例\n\n这些内容涵盖了C++的核心知识体系，从基础语法到高级特性都有涉及。', NULL, 3241, NULL, '2026-05-04 01:17:29');
INSERT INTO `rag_qa_record` VALUES (2, 1, 2, '你的知识库里有什么内容', '根据提供的背景知识，我的「Java知识库」包含以下内容：\n\n## 一、题型分类\n\n### 1. 单选题\n- Java语言诞生年份\n- 面向对象特性\n- 关键字使用(final等)\n\n### 2. 判断题\n- Java多继承支持\n- JVM跨平台特性\n- 程序入口方法\n\n### 3. 简答题\n- Java垃圾回收机制\n- JVM、JRE、JDK概念\n\n### 4. 代码填空题\n- 三元运算符使用\n\n### 5. 面试高频题\n- ArrayList与LinkedList区别\n- synchronized线程安全实现\n- Java内存模型(JMM)\n- Java 8的Optional类\n\n## 二、知识点模块\n\n### 1. Java基础\n- 面向对象特性(继承、封装、多态)\n- 关键字使用(static、final、abstract等)\n\n### 2. JVM相关\n- 垃圾回收机制\n- Java内存模型(JMM)\n- 跨平台特性\n\n### 3. Java新特性\n- Java 8新特性(Lambda、Stream API、Optional)\n- Java模块化系统(JPMS, Java 9)\n- record类(Java 14预览/17正式)\n- sealed类(Java 17)\n- 虚拟线程(Java 21)\n\n### 4. 场景设计题\n- 热点缓存系统设计(防止缓存击穿、雪崩、穿透)\n- 分布式事务处理\n\n### 5. 集合框架\n- ArrayList与LinkedList区别\n\n### 6. 并发编程\n- synchronized关键字\n- 线程安全实现\n\n这些内容涵盖了Java核心知识点，从基础语法到高级特性，以及实际应用场景。', NULL, 5628, NULL, '2026-05-04 01:18:36');
INSERT INTO `rag_qa_record` VALUES (3, 1, 2, '1', '您好！我正在「Java知识库」知识库中回答您的问题。\n\n关于您发送的\"1\"，这似乎是一个简短的消息。如果您有任何关于Java编程的问题，例如语法、概念、框架、最佳实践等，我很乐意为您提供帮助。请告诉我您具体想了解什么，我将基于我的通用知识为您提供解答。\n\n请注意，由于当前知识库中没有检索到相关文档内容，我的回答将基于通用知识，而非知识库中的文档内容。\n\n---\n⚠️ 当前知识库是「Java知识库」，这个问题不在范围内。你的「C++知识库」可能包含相关内容，要切换过去吗？', NULL, 1600, NULL, '2026-05-04 01:18:47');
INSERT INTO `rag_qa_record` VALUES (4, 1, 2, '我想学习封装', '您好！我正在「Java知识库」知识库中回答您的问题。关于封装的学习，当前知识库中没有检索到相关文档内容，以下我将基于通用知识为您介绍封装的概念和实现。\n\n### 封装的概念\n\n封装是面向对象编程(OOP)的三大基本特性之一（另外两个是继承和多态）。封装指的是将数据（属性）和操作数据的方法（行为）捆绑到一个单元（类）中，并隐藏对象的内部状态，只通过公共方法与外部进行交互。\n\n### 封装的主要目的\n\n1. **数据保护**：防止外部代码直接访问对象的内部数据，避免数据被意外修改\n2. **接口简化**：提供简单清晰的公共接口，隐藏复杂的实现细节\n3. **代码维护性**：内部实现可以修改而不影响使用该类的其他代码\n4. **安全性**：可以通过方法验证数据的有效性，确保对象状态的一致性\n\n### Java中封装的实现方式\n\n1. **使用访问修饰符**：\n   - `private`：私有，只能在类内部访问\n   - `default`：默认，只能在同一个包内访问\n   - `protected`：受保护，可以在同一个包和子类中访问\n   - `public`：公共，可以在任何地方访问\n\n2. **提供getter和setter方法**：\n   - `getter`方法：获取私有属性的值\n   - `setter`方法：设置私有属性的值，并可以添加验证逻辑\n\n### 封装的示例代码\n\n```java\npublic class Person {\n    // 私有属性，外部无法直接访问\n    private String name;\n    private int age;\n    \n    // 构造方法\n    public Person(String name, int age) {\n        this.name = name;\n        this.setAge(age); // 使用setter方法进行验证\n    }\n    \n    // getter方法\n    public String getName() {\n        return name;\n    }\n    \n    // setter方法，可以添加验证逻辑\n    public void setAge(int age) {\n        if (age > 0 && age < 150) {\n            this.age = age;\n        } else {\n            throw new IllegalArgumentException(\"年龄必须在1-150之间\");\n        }\n    }\n    \n    public int getAge() {\n        return age;\n    }\n    \n    // 公共方法，封装了内部实现\n    public void introduce() {\n        System.out.println(\"我叫\" + name + \"，今年\" + age + \"岁\");\n    }\n}\n```\n\n### 使用封装的示例\n\n```java\npublic class Main {\n    public static void main(String[] args) {\n        Person person = new Person(\"张三\", 25);\n        person.introduce(); // 输出：我叫张三，今年25岁\n        \n        // 尝试直接修改私有属性（编译错误）\n        // person.name = \"李四\"; // 无法直接访问私有属性\n        \n        // 通过setter方法修改属性\n        person.setAge(26); // 合法\n        // person.setAge(-5); // 抛出IllegalArgumentException\n        \n        System.out.println(\"姓名: \" + person.getName()); // 通过getter获取\n        System.out.println(\"年龄: \" + person.getAge());\n    }\n}\n```\n\n### 封装的最佳实践\n\n1. **将所有字段设为私有**，除非有特殊原因\n2. **提供公共的getter和setter方法**来访问私有字段\n3. **在setter方法中添加验证逻辑**，确保数据有效性\n4. **对于不应该修改的属性，只提供getter方法**（创建只读属性）\n5. **对于布尔类型的属性，可以使用isXxx()代替getXxx()**\n\n封装是Java编程中的基础概念，掌握封装对于编写健壮、可维护的代码非常重要。希望这些信息对您有所帮助！\n\n---\n⚠️ 当前知识库是「Java知识库」，这个问题不在范围内。你的「C++知识库」可能包含相关内容，要切换过去吗？', NULL, 11836, NULL, '2026-05-04 01:21:23');
INSERT INTO `rag_qa_record` VALUES (5, 1, 2, 'java虚拟机的知识', '根据Java知识库中的内容，我可以为您提供关于Java虚拟机(JVM)的相关知识：\n\n## JVM基础概念\n- **JVM**：Java虚拟机，是跨平台的核心\n- **JRE**：Java运行环境，包含JVM和核心类库\n- **JDK**：Java开发工具包，包含JRE、编译器和调试工具\n\n## JVM内存区域划分\n1. **堆(Heap)**：存放对象实例，是垃圾回收(GC)管理的主要区域\n2. **栈(Stack)**：每个线程私有，存储局部变量、操作数栈、动态链接等\n3. **方法区(Method Area)**：存储类信息、常量、静态变量、即时编译器编译后的代码\n4. **程序计数器(Program Counter Register)**：记录当前线程执行的字节码行号\n5. **本地方法栈(Native Method Stack)**：服务于Native方法\n\n## 垃圾回收机制\nJava采用自动内存管理，通过垃圾回收器(GC)回收不再使用的对象内存，避免内存泄漏。\n\n## JVM相关面试题\n- **volatile关键字**：保证变量的可见性和禁止指令重排序，但不保证原子性\n- **死锁**：两个或多个线程互相持有对方需要的资源，导致无限等待\n- **死锁产生的必要条件**：互斥条件、请求与保持条件、不剥夺条件、循环等待条件\n\n## JVM调优相关\n- **常见GC收集器**：CMS、G1、ZGC等，各有不同的特点和适用场景\n- **OOM问题排查**：通过分析堆转储文件(heap dump)来定位内存泄漏问题\n\n这些是知识库中关于JVM的主要内容。如果您需要更深入的信息，建议查阅专业的JVM文档或相关书籍。', NULL, 4983, NULL, '2026-05-04 01:23:55');
INSERT INTO `rag_qa_record` VALUES (6, 1, 2, '死锁是什么', '你好！我正在「Java知识库」知识库中回答你的问题。\n\n关于死锁，基于我的通用知识（非知识库文档内容），我可以为你解释：\n\n死锁（Deadlock）是指在多线程或多进程环境中，两个或多个线程（或进程）因互相等待对方持有的资源而造成的一种阻塞状态，导致所有相关线程都无法继续执行的情况。\n\n### 死锁的必要条件\n根据Coffman条件，死锁必须同时满足以下四个条件：\n1. **互斥条件**：资源一次只能被一个线程占用\n2. **持有并等待**：线程持有至少一个资源，同时等待获取其他线程持有的资源\n3. **非抢占条件**：资源不能被强制抢占，只能由持有者自愿释放\n4. **循环等待**：存在一个线程资源的循环等待链，如线程A等待线程B的资源，线程B又等待线程A的资源\n\n### 死锁的示例\n在Java中，一个典型的死锁场景可能是：\n```java\npublic class DeadlockExample {\n    private static final Object lock1 = new Object();\n    private static final Object lock2 = new Object();\n    \n    public static void main(String[] args) {\n        Thread thread1 = new Thread(() -> {\n            synchronized (lock1) {\n                System.out.println(\"Thread1: Holding lock1...\");\n                try { Thread.sleep(100); } catch (InterruptedException e) {}\n                System.out.println(\"Thread1: Waiting for lock2...\");\n                synchronized (lock2) {\n                    System.out.println(\"Thread1: Acquired lock2\");\n                }\n            }\n        });\n        \n        Thread thread2 = new Thread(() -> {\n            synchronized (lock2) {\n                System.out.println(\"Thread2: Holding lock2...\");\n                try { Thread.sleep(100); } catch (InterruptedException e) {}\n                System.out.println(\"Thread2: Waiting for lock1...\");\n                synchronized (lock1) {\n                    System.out.println(\"Thread2: Acquired lock1\");\n                }\n            }\n        });\n        \n        thread1.start();\n        thread2.start();\n    }\n}\n```\n\n### 死锁的预防与解决方法\n1. **破坏死锁条件**：\n   - 按固定顺序获取锁\n   - 使用锁超时机制\n   - 避免嵌套锁\n\n2. **死锁检测与恢复**：\n   - 使用工具检测死锁（如JConsole、VisualVM）\n   - 实现死锁检测算法\n   - 重新启动程序或释放资源\n\n3. **使用高级并发工具**：\n   - 使用`java.util.concurrent`包中的工具类\n   - 使用`Lock`接口替代`synchronized`\n   - 使用`ReentrantLock`的`tryLock()`方法\n\n4. **设计层面避免**：\n   - 减少锁的持有时间\n   - 使用不可变对象\n   - 采用无锁数据结构\n\n希望这些信息对你有所帮助！如果你需要更具体的Java死锁解决方案或案例分析，请随时提问。\n\n---\n⚠️ 当前知识库是「Java知识库」，这个问题不在范围内。你的「C++知识库」可能包含相关内容，要切换过去吗？', NULL, 22158, NULL, '2026-05-04 01:27:02');
INSERT INTO `rag_qa_record` VALUES (7, 1, 2, '那你的知识库还会什么内容', '根据提供的背景知识，我的Java知识库包含以下主要内容：\n\n## 已掌握的知识模块\n\n### 一、Java基础特性\n- Java模块化系统（JPMS，Java 9引入）\n- `record`类（Java 14预览，Java 17正式）\n- `sealed`类（Java 17）\n- 虚拟线程（Virtual Threads，Java 21）\n\n### 二、题型设计\n- 单选题（如：不可变类识别）\n- 多选题（如：Java 8新特性）\n- 填空题（如：`orElse(null)`的使用、Stream API操作）\n\n### 三、场景设计题\n- 热点缓存系统设计（防止缓存击穿、雪崩、穿透）\n- 分布式事务处理（微服务架构中的数据一致性）\n\n### 四、技术深入点\n- HashMap实现原理（JDK 1.7 vs 1.8）\n- 并发工具类（CountDownLatch、CyclicBarrier、ThreadLocal）\n- 设计模式（单例模式、工厂模式、策略模式）\n- JVM调优（GC收集器、OOM排查）\n- Spring相关（Bean生命周期、AOP原理）\n\n### 五、错误调试\n- 常见编程错误修正（如数组越界、Stream API使用）\n\n## 当前知识库覆盖范围\n我的知识库主要集中在Java语言特性、并发编程、JVM优化、设计模式以及实际应用场景设计方面，涵盖了从基础到高级的Java开发知识。\n\n如果您有特定的Java技术领域需要了解，我可以查看知识库中是否有相关内容，或者明确告知您当前知识库中未覆盖该主题。', NULL, 5165, NULL, '2026-05-04 01:27:17');
INSERT INTO `rag_qa_record` VALUES (8, 1, 1, '我想了解c++的内存管理', '您好！我正在「C++知识库」知识库中回答您的问题。关于C++的内存管理，当前回答基于我的通用知识，非知识库文档内容。\n\nC++内存管理是C++编程中的重要概念，主要包括以下几个方面：\n\n## 1. 内存分配区域\n- **栈内存**：自动分配和释放，存储局部变量、函数参数等\n- **堆内存**：动态分配，需要手动管理，使用`new`和`delete`操作\n- **静态/全局内存**：存储全局变量和静态变量\n- **常量内存**：存储字符串字面量等常量数据\n\n## 2. 手动内存管理\n- **堆分配**：使用`new`关键字分配内存\n  ```cpp\n  int* ptr = new int;          // 分配单个int\n  int* arr = new int[10];     // 分配数组\n  ```\n- **内存释放**：使用`delete`关键字释放内存\n  ```cpp\n  delete ptr;                 // 释放单个对象\n  delete[] arr;               // 释放数组\n  ```\n\n## 3. 现代C++内存管理技术\n- **智能指针**（C++11及以后）：\n  - `std::unique_ptr`：独占所有权\n  - `std::shared_ptr`：共享所有权\n  - `std::weak_ptr`：弱引用，避免循环引用\n\n- **RAII（资源获取即初始化）**：资源管理对象生命周期\n\n## 4. 内存问题\n- **内存泄漏**：分配的内存未释放\n- **悬挂指针**：指向已释放内存的指针\n- **双重释放**：同一内存被释放多次\n- **内存越界**：访问超出分配范围的内存\n\n## 5. 最佳实践\n- 尽量使用智能指针而非原始指针\n- 遵循RAII原则\n- 避免裸露的`new`和`delete`\n- 使用容器类（如`std::vector`）替代原始数组\n\n如果您需要更详细的信息或有特定问题，请告诉我！\n\n---\n⚠️ 当前知识库是「C++知识库」，这个问题不在范围内。你的「Java知识库」可能包含相关内容，要切换过去吗？', NULL, 5512, NULL, '2026-05-04 18:36:39');
