INSERT INTO `sys_oper_log` VALUES (750, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"正确答案：A。现在完成时表示从过去持续到现在的动作。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":115,\"options\":\"[\\\"has learned\\\",\\\"learns\\\",\\\"learned\\\",\\\"is learning\\\"]\",\"params\":{},\"questionText\":\"She ______ English for five years.\",\"questionType\":1,\"score\":2.0,\"sortOrder\":0,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 33);
INSERT INTO `sys_oper_log` VALUES (751, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"正确答案：C。虚拟语气中，be 动词用 were。\",\"answer\":\"C\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":116,\"options\":\"[\\\"am\\\",\\\"was\\\",\\\"were\\\",\\\"will be\\\"]\",\"params\":{},\"questionText\":\"If I ______ you, I would take the job.\",\"questionType\":1,\"score\":2.0,\"sortOrder\":1,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 20);
INSERT INTO `sys_oper_log` VALUES (752, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"正确答案：A,C,E。情态动词包括 can, must, should 等。\",\"answer\":\"\\u0000,\\u0000,\\u0000\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":117,\"options\":\"[\\\"can\\\",\\\"go\\\",\\\"must\\\",\\\"run\\\",\\\"should\\\"]\",\"params\":{},\"questionText\":\"Which of the following are modal verbs?\",\"questionType\":2,\"score\":3.0,\"sortOrder\":2,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 10);
INSERT INTO `sys_oper_log` VALUES (753, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"正确答案：B（错误）。\\\"He don’t like apples.\\\" 是错误句，正确应为 \\\"He doesn’t like apples.\\\"，故原句错误。\",\"answer\":\"false\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":118,\"options\":\"\",\"params\":{},\"questionText\":\"\\\"He don’t like apples.\\\" is grammatically correct.\",\"questionType\":3,\"score\":1.0,\"sortOrder\":3,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 9);
INSERT INTO `sys_oper_log` VALUES (754, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"标准答案：table。根据上下文和提示，应填 table。\",\"answer\":\"table\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":119,\"options\":\"\",\"params\":{},\"questionText\":\"The book is on the ______. (提示：家具)\",\"questionType\":4,\"score\":2.0,\"sortOrder\":4,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 9);
INSERT INTO `sys_oper_log` VALUES (755, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"正确答案：B。过去完成时表示“过去的过去”。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":120,\"options\":\"[\\\"has left\\\",\\\"had left\\\",\\\"left\\\",\\\"leaves\\\"]\",\"params\":{},\"questionText\":\"By the time we arrived, the train ______.\",\"questionType\":1,\"score\":2.0,\"sortOrder\":5,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 11);
INSERT INTO `sys_oper_log` VALUES (756, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"正确答案：B（错误）。\\\"Information\\\" 是不可数名词。\",\"answer\":\"false\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":121,\"options\":\"\",\"params\":{},\"questionText\":\"The word \\\"information\\\" is countable.\",\"questionType\":3,\"score\":1.0,\"sortOrder\":6,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 10);
INSERT INTO `sys_oper_log` VALUES (757, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"标准答案：in。固定搭配：be interested in...\",\"answer\":\"in\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":122,\"options\":\"\",\"params\":{},\"questionText\":\"She is interested ______ learning French.\",\"questionType\":4,\"score\":2.0,\"sortOrder\":7,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 9);
INSERT INTO `sys_oper_log` VALUES (758, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"正确答案：B。Not only 开头，主句倒装，且时态为一般过去时。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":123,\"options\":\"[\\\"he was\\\",\\\"was he\\\",\\\"did he\\\",\\\"he did\\\"]\",\"params\":{},\"questionText\":\"Not only ______ late, but also forgot the documents.\",\"questionType\":1,\"score\":3.0,\"sortOrder\":8,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:11', 10);
INSERT INTO `sys_oper_log` VALUES (759, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"参考答案：Affect is usually a verb meaning to influence; effect is usually a noun meaning result.。注意词性和用法区别。\",\"answer\":\"Affect is usually a verb meaning to influence; effect is usually a noun meaning result.\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-11 15:37:11\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":124,\"options\":\"\",\"params\":{},\"questionText\":\"Explain the difference between \\\"affect\\\" and \\\"effect\\\".\",\"questionType\":5,\"score\":5.0,\"sortOrder\":9,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-11 15:37:12', 11);
INSERT INTO `sys_oper_log` VALUES (760, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"文章主旨：阅读对认知和社交的益处。\",\"answer\":\"\\u0000\",\"bankId\":1,\"content\":\"<p>In today’s digital age, reading books remains one of the most effective ways to improve cognitive function. Studies show that regular readers have better memory, concentration, and empathy. Unlike passive screen time, reading actively engages the brain, creating new neural pathways. Moreover, reading fiction allows people to experience different perspectives, which enhances social understanding.</p>\",\"difficulty\":2,\"hasSubQuestions\":0,\"options\":\"\",\"params\":{},\"questionText\":\"The Benefits of Reading\",\"questionType\":1,\"score\":5.0,\"sortOrder\":10,\"status\":\"0\"}', '{\"msg\":\"题目答案不能为空\",\"code\":500}', 0, NULL, '2026-04-11 15:37:12', 3);
INSERT INTO `sys_oper_log` VALUES (761, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"完形填空主题：环保人人有责。\",\"answer\":\"\\u0000\",\"bankId\":1,\"content\":\"Many people believe that protecting the environment is not just the government’s responsibility, but ___1___ of every individual. Simple actions like recycling, using less plastic, and saving water can make a big ___2___. If everyone contributes, we can reduce pollution and ___3___ natural resources for future generations. It’s never too late to start making ___4___ changes in our daily lives. After all, the Earth is our only ___5___.\",\"difficulty\":2,\"hasSubQuestions\":0,\"options\":\"\",\"params\":{},\"questionText\":\"Environmental Protection\",\"questionType\":1,\"score\":5.0,\"sortOrder\":11,\"status\":\"0\"}', '{\"msg\":\"题目答案不能为空\",\"code\":500}', 0, NULL, '2026-04-11 15:37:12', 4);
