INSERT INTO `sys_oper_log` VALUES (1187, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\",\"answer\":\"\",\"bankId\":1,\"content\":\"Many people enjoy drinking coffee ___1___ the morning. It helps them wake up and feel more ___2___. However, too much coffee can cause problems like anxiety or trouble sleeping. Experts recommend drinking no more than ___3___ cups per day.\",\"difficulty\":2,\"hasSubQuestions\":1,\"id\":150,\"params\":{},\"questionSubList\":[{\"analysis\":\"\",\"answer\":\"A\",\"id\":1776001233251,\"mainId\":150,\"options\":\"[\\\"选项A\\\", \\\"选项B\\\"]\",\"params\":{},\"questionText\":\"11\",\"questionType\":1,\"score\":2,\"sortOrder\":0}],\"questionText\":\"阅读下面的短文，从每题所给的选项中选择最佳答案填空。\",\"questionType\":6,\"score\":5.0,\"sortOrder\":15,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 09:12:50', 18);
INSERT INTO `sys_oper_log` VALUES (1188, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查过去完成进行时。\'by the time\'引导的时间状语从句表示在过去某一时间点之前已经完成的动作，主句用过去完成时。由于电影一直在放映，所以用过去完成进行时\'had been running\'表示在过去某一时间点之前一直在进行的动作。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-14 09:12:50\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":151,\"options\":\"[\\\"had been running\\\",\\\"has been running\\\",\\\"ran\\\",\\\"was running\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"By the time we got to the cinema, the movie ________ for twenty minutes.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":16,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 09:12:50', 21);
INSERT INTO `sys_oper_log` VALUES (1189, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查现在完成时。句子表达的是过去发生的动作对现在造成的结果或影响（找不到钥匙），且强调动作已经完成，所以用现在完成时\'have lost\'。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-14 09:12:50\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":152,\"options\":\"[\\\"lost\\\",\\\"have lost\\\",\\\"was losing\\\",\\\"had lost\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"I ________ my keys. I can\'t find them anywhere.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":17,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 09:12:50', 12);
INSERT INTO `sys_oper_log` VALUES (1190, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查过去完成时。\'when I arrived\'表示过去的时间点，而\'already left\'表示在\'我到达\'之前已经发生的动作，所以需要用过去完成时\'had left\'来表示过去的过去。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-14 09:12:50\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":153,\"options\":\"[\\\"had, left\\\",\\\"was, leaving\\\",\\\"has, left\\\",\\\"would, leave\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"When I arrived at the party, everyone ________ already ________.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":18,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 09:12:50', 12);
INSERT INTO `sys_oper_log` VALUES (1191, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查将来完成进行时。\'by the end of this year\'表示将来的时间点，而\'for five years\'表示持续的时间，所以用将来完成进行时\'will have been working\'表示到将来的某一时间点为止已经持续了一段时间的动作。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"createTime\":\"2026-04-14 09:12:50\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":154,\"options\":\"[\\\"will be working\\\",\\\"will have been working\\\",\\\"have worked\\\",\\\"had worked\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"By the end of this year, we ________ this project for five years.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":19,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 09:12:50', 12);
