INSERT INTO `sys_oper_log` VALUES (1269, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\",\"answer\":\"\",\"bankId\":1,\"content\":\"Many people enjoy drinking coffee ___1___ the morning. It helps them wake up and feel more ___2___. However, too much coffee can cause problems like anxiety or trouble sleeping. Experts recommend drinking no more than ___3___ cups per day.\",\"difficulty\":2,\"hasSubQuestions\":1,\"id\":150,\"params\":{},\"questionSubList\":[{\"analysis\":\"\",\"answer\":\"A\",\"id\":1776001233251,\"mainId\":150,\"options\":\"[\\\"选项A\\\", \\\"选项B\\\"]\",\"params\":{},\"questionText\":\"11\",\"questionType\":1,\"score\":2,\"sortOrder\":0}],\"questionText\":\"阅读下面的短文，从每题所给的选项中选择最佳答案填空。\",\"questionType\":6,\"score\":5.0,\"sortOrder\":15,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 15);
INSERT INTO `sys_oper_log` VALUES (1270, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查过去完成进行时。\'by the time\'引导的时间状语从句表示在过去某一时间点之前已经完成的动作，主句用过去完成时。由于电影一直在放映，所以用过去完成进行时\'had been running\'表示在过去某一时间点之前一直在进行的动作。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":151,\"options\":\"[\\\"had been running\\\",\\\"has been running\\\",\\\"ran\\\",\\\"was running\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"By the time we got to the cinema, the movie ________ for twenty minutes.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":16,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 11);
INSERT INTO `sys_oper_log` VALUES (1271, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查现在完成时。句子表达的是过去发生的动作对现在造成的结果或影响（找不到钥匙），且强调动作已经完成，所以用现在完成时\'have lost\'。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":152,\"options\":\"[\\\"lost\\\",\\\"have lost\\\",\\\"was losing\\\",\\\"had lost\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"I ________ my keys. I can\'t find them anywhere.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":17,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 10);
INSERT INTO `sys_oper_log` VALUES (1272, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查过去完成时。\'when I arrived\'表示过去的时间点，而\'already left\'表示在\'我到达\'之前已经发生的动作，所以需要用过去完成时\'had left\'来表示过去的过去。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":153,\"options\":\"[\\\"had, left\\\",\\\"was, leaving\\\",\\\"has, left\\\",\\\"would, leave\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"When I arrived at the party, everyone ________ already ________.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":18,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 10);
INSERT INTO `sys_oper_log` VALUES (1273, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查将来完成进行时。\'by the end of this year\'表示将来的时间点，而\'for five years\'表示持续的时间，所以用将来完成进行时\'will have been working\'表示到将来的某一时间点为止已经持续了一段时间的动作。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":154,\"options\":\"[\\\"will be working\\\",\\\"will have been working\\\",\\\"have worked\\\",\\\"had worked\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"By the end of this year, we ________ this project for five years.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":19,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 10);
INSERT INTO `sys_oper_log` VALUES (1274, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查虚拟语气中与现在事实相反的假设。在if条件状语从句中，表示与现在事实相反的假设时，用过去式（rained），而主句用\'would + 动词原形\'。\",\"answer\":\"D\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":155,\"options\":\"[\\\"rains\\\",\\\"rained\\\",\\\"will rain\\\",\\\"would rain222\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"If it ________ tomorrow, we would cancel the picnic.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":20,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 8);
INSERT INTO `sys_oper_log` VALUES (1275, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"int是Java的基本数据类型，而String、ArrayList和HashMap都是引用类型。Java的基本数据类型包括byte、short、int、long、float、double、char和boolean。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":156,\"options\":\"[\\\"String\\\",\\\"int\\\",\\\"ArrayList\\\",\\\"HashMap\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"以下哪个是Java的基本数据类型？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":21,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 9);
INSERT INTO `sys_oper_log` VALUES (1276, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Java中，使用new关键字来创建对象。例如：ClassName obj = new ClassName();。create、make和construct都不是Java的关键字。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":157,\"options\":\"[\\\"new\\\",\\\"create\\\",\\\"make\\\",\\\"construct\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在Java中，哪个关键字用于创建对象？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":22,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 9);
INSERT INTO `sys_oper_log` VALUES (1277, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Java接口只能包含抽象方法、常量、默认方法、静态方法和私有方法。接口不能包含实例变量、构造方法或静态代码块。从Java 8开始，接口可以有默认方法和静态方法，但必须有default或static关键字修饰。\",\"answer\":\"C\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":158,\"options\":\"[\\\"实例变量\\\",\\\"构造方法\\\",\\\"抽象方法\\\",\\\"静态代码块\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Java中的接口可以包含以下哪种成员？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":23,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 9);
INSERT INTO `sys_oper_log` VALUES (1278, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"The correct past tense form of \'go\' is \'went\'. \'Goed\' is not a standard English word form. \'Gone\' is the past participle form, and \'going\' is the present participle or gerund form.\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":159,\"options\":\"[\\\"goed\\\",\\\"went\\\",\\\"gone\\\",\\\"going\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Which of the following is the correct past tense form of the verb \'go\'?\",\"questionType\":1,\"score\":5.0,\"sortOrder\":24,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 10);
INSERT INTO `sys_oper_log` VALUES (1279, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"For most one-syllable adjectives, we add \'-er\' to form the comparative. So \'big\' becomes \'bigger\'. \'Biggest\' is the superlative form, \'more big\' is incorrect structure, and \'biger\' is misspelled (should be \'bigger\').\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":160,\"options\":\"[\\\"biggest\\\",\\\"bigger\\\",\\\"more big\\\",\\\"biger\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"What is the comparative form of the adjective \'big\'?\",\"questionType\":1,\"score\":5.0,\"sortOrder\":25,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 8);
INSERT INTO `sys_oper_log` VALUES (1280, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"The present perfect tense (has/have + past participle) is used for actions that started in the past and continue to the present or have present results. \'She has gone to school\' is correct. The other options are either simple past (\'went\'), present continuous (\'is going\'), or simple present (\'goes\').\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":161,\"options\":\"[\\\"She goes to school yesterday.\\\",\\\"She has gone to school.\\\",\\\"She is going to school.\\\",\\\"She goes to school every day.\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Which sentence correctly uses the present perfect tense?\",\"questionType\":1,\"score\":5.0,\"sortOrder\":26,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 10);
INSERT INTO `sys_oper_log` VALUES (1281, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'安详\'中的\'详\'是\'安静、平和\'的意思，没有错别字。\'祥和\'中的\'祥\'是\'吉祥\'的意思，不是\'详\'；\'祥瑞\'和\'吉祥\'中的\'祥\'都是\'吉祥\'的意思，但\'祥瑞\'中的\'祥\'没有错，而\'吉祥\'中的\'吉\'也没有错。因此，\'安详\'是没有错别字的选项。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":162,\"options\":\"[\\\"安详\\\",\\\"详和\\\",\\\"祥瑞\\\",\\\"吉祥\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"下列词语中，没有错别字的一项是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":27,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 8);
INSERT INTO `sys_oper_log` VALUES (1282, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'名列前茅\'的正确写法是\'名列前茅\'，意思是名次排在前面。\'茅\'指茅草，古代用茅草做旗帜，比喻名次在前。\'矛\'是古代的一种兵器，与成语意思无关。因此，第二个\'名列前茅\'是正确的。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":163,\"options\":\"[\\\"名列前矛\\\",\\\"名列前茅\\\",\\\"名列前矛\\\",\\\"名列前茅\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"下列成语中，没有错别字的一项是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":28,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 8);
INSERT INTO `sys_oper_log` VALUES (1283, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'马虎大意\'中的\'意\'是\'意思、含义\'的意思，表示做事不细心、不认真。\'大义\'通常指\'大道理、正义\'的意思，与句子语境不符。因此，第三个句子中的\'马虎大意\'是正确的写法。\",\"answer\":\"C\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":164,\"options\":\"[\\\"他做事一丝不苟，从不马虎大意\\\",\\\"他做事一丝不苟，从不马虎大义\\\",\\\"他做事一丝不苟，从不马虎大意\\\",\\\"他做事一丝不苟，从不马虎大义\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"下列句子中，没有错别字的一项是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":29,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 10);
INSERT INTO `sys_oper_log` VALUES (1284, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'你好\'是中文中最常用的问候语，用于初次见面或日常打招呼，表示对对方的礼貌和尊重。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":165,\"options\":\"[\\\"表示惊讶\\\",\\\"表示问候\\\",\\\"表示告别\\\",\\\"表示感谢\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在中文语境中，\'你好\'最常用的含义是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":30,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 10);
INSERT INTO `sys_oper_log` VALUES (1285, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"初次见面时，\'你好\'是最恰当的开场白，表示友好和尊重，而其他选项分别表示告别、感谢和道歉，不适合初次见面的场景。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":166,\"options\":\"[\\\"再见\\\",\\\"你好\\\",\\\"谢谢\\\",\\\"对不起\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"当你第一次见到某人时，最合适的开场白是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":31,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 8);
INSERT INTO `sys_oper_log` VALUES (1286, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在电话通话开始时，使用\'你好\'作为问候语是最礼貌和标准的方式，表示通话开始并准备交流。\'喂\'虽然也常用于电话，但不如\'你好\'正式和礼貌。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":167,\"options\":\"[\\\"喂\\\",\\\"你好\\\",\\\"再见\\\",\\\"谢谢\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在电话通话开始时，通常说的第一句话是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":32,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 7);
INSERT INTO `sys_oper_log` VALUES (1287, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\",\"answer\":\"\",\"bankId\":1,\"content\":\"Artificial Intelligence in Daily Life\\n\\nArtificial Intelligence (AI) has become an integral part of our daily lives, often without us even realizing it. From the moment we wake up to when we go to bed, AI technology is working behind the scenes to make our lives easier and more efficient.\\n\\nIn the morning, many people rely on AI-powered virtual assistants like Siri or Alexa to check the weather, set reminders, or play music. These assistants use natural language processing to understand and respond to our commands. When we commute, navigation apps like Google Maps use AI to analyze traffic patterns and suggest the fastest routes. \\n\\nAt school, AI tools help students with personalized learning experiences, adapting to individual needs and learning styles. Even entertainment has been transformed by AI, with streaming services using algorithms to recommend movies and shows based on our viewing history.\\n\\nAs AI continues to evolve, it will likely become even more prevalent in our daily routines, offering new ways to improve our quality of life.\",\"createTime\":\"2026-04-14 19:43:57\",\"difficulty\":2,\"hasSubQuestions\":1,\"id\":168,\"params\":{},\"questionSubList\":[{\"analysis\":\"The main idea of the passage is that AI has become an integral and often unnoticed part of our daily lives. The passage describes how AI is used in various aspects of daily routines, from morning routines to entertainment, without explicitly stating that it\'s replacing humans or that it\'s only in virtual assistants.\",\"answer\":\"B\",\"mainId\":168,\"options\":\"[\\\"AI technology is replacing human workers in various industries\\\",\\\"AI has become an invisible but essential part of daily life\\\",\\\"Virtual assistants are the most common form of AI technology\\\",\\\"AI will eventually replace all traditional forms of entertainment\\\"]\",\"params\":{},\"questionText\":\"What is the main idea of the passage?\",\"questionType\":1,\"score\":2,\"sortOrder\":0},{\"analysis\":\"The passage specifi', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-14 19:43:57', 15);
