INSERT INTO `sys_oper_log` VALUES (1346, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\",\"answer\":\"\",\"bankId\":1,\"content\":\"Many people enjoy drinking coffee ___1___ the morning. It helps them wake up and feel more ___2___. However, too much coffee can cause problems like anxiety or trouble sleeping. Experts recommend drinking no more than ___3___ cups per day.\",\"difficulty\":2,\"hasSubQuestions\":1,\"id\":150,\"params\":{},\"questionSubList\":[{\"analysis\":\"\",\"answer\":\"A\",\"id\":1776001233251,\"mainId\":150,\"options\":\"[\\\"选项A\\\", \\\"选项B\\\"]\",\"params\":{},\"questionText\":\"11\",\"questionType\":1,\"score\":2,\"sortOrder\":0}],\"questionText\":\"阅读下面的短文，从每题所给的选项中选择最佳答案填空。\",\"questionType\":6,\"score\":5.0,\"sortOrder\":15,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 18);
INSERT INTO `sys_oper_log` VALUES (1347, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查过去完成进行时。\'by the time\'引导的时间状语从句表示在过去某一时间点之前已经完成的动作，主句用过去完成时。由于电影一直在放映，所以用过去完成进行时\'had been running\'表示在过去某一时间点之前一直在进行的动作。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":151,\"options\":\"[\\\"had been running\\\",\\\"has been running\\\",\\\"ran\\\",\\\"was running\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"By the time we got to the cinema, the movie ________ for twenty minutes.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":16,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 13);
INSERT INTO `sys_oper_log` VALUES (1348, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查现在完成时。句子表达的是过去发生的动作对现在造成的结果或影响（找不到钥匙），且强调动作已经完成，所以用现在完成时\'have lost\'。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":152,\"options\":\"[\\\"lost\\\",\\\"have lost\\\",\\\"was losing\\\",\\\"had lost\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"I ________ my keys. I can\'t find them anywhere.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":17,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 10);
INSERT INTO `sys_oper_log` VALUES (1349, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查过去完成时。\'when I arrived\'表示过去的时间点，而\'already left\'表示在\'我到达\'之前已经发生的动作，所以需要用过去完成时\'had left\'来表示过去的过去。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":153,\"options\":\"[\\\"had, left\\\",\\\"was, leaving\\\",\\\"has, left\\\",\\\"would, leave\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"When I arrived at the party, everyone ________ already ________.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":18,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 13);
INSERT INTO `sys_oper_log` VALUES (1350, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查将来完成进行时。\'by the end of this year\'表示将来的时间点，而\'for five years\'表示持续的时间，所以用将来完成进行时\'will have been working\'表示到将来的某一时间点为止已经持续了一段时间的动作。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":154,\"options\":\"[\\\"will be working\\\",\\\"will have been working\\\",\\\"have worked\\\",\\\"had worked\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"By the end of this year, we ________ this project for five years.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":19,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 11);
INSERT INTO `sys_oper_log` VALUES (1351, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"本题考查虚拟语气中与现在事实相反的假设。在if条件状语从句中，表示与现在事实相反的假设时，用过去式（rained），而主句用\'would + 动词原形\'。\",\"answer\":\"D\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":155,\"options\":\"[\\\"rains\\\",\\\"rained\\\",\\\"will rain\\\",\\\"would rain222\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"If it ________ tomorrow, we would cancel the picnic.\",\"questionType\":1,\"score\":5.0,\"sortOrder\":20,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 12);
INSERT INTO `sys_oper_log` VALUES (1352, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"int是Java的基本数据类型，而String、ArrayList和HashMap都是引用类型。Java的基本数据类型包括byte、short、int、long、float、double、char和boolean。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":156,\"options\":\"[\\\"String\\\",\\\"int\\\",\\\"ArrayList\\\",\\\"HashMap\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"以下哪个是Java的基本数据类型？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":21,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 13);
INSERT INTO `sys_oper_log` VALUES (1353, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Java中，使用new关键字来创建对象。例如：ClassName obj = new ClassName();。create、make和construct都不是Java的关键字。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":157,\"options\":\"[\\\"new\\\",\\\"create\\\",\\\"make\\\",\\\"construct\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在Java中，哪个关键字用于创建对象？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":22,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 14);
INSERT INTO `sys_oper_log` VALUES (1354, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Java接口只能包含抽象方法、常量、默认方法、静态方法和私有方法。接口不能包含实例变量、构造方法或静态代码块。从Java 8开始，接口可以有默认方法和静态方法，但必须有default或static关键字修饰。\",\"answer\":\"C\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":158,\"options\":\"[\\\"实例变量\\\",\\\"构造方法\\\",\\\"抽象方法\\\",\\\"静态代码块\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Java中的接口可以包含以下哪种成员？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":23,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 10);
INSERT INTO `sys_oper_log` VALUES (1355, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"The correct past tense form of \'go\' is \'went\'. \'Goed\' is not a standard English word form. \'Gone\' is the past participle form, and \'going\' is the present participle or gerund form.\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":159,\"options\":\"[\\\"goed\\\",\\\"went\\\",\\\"gone\\\",\\\"going\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Which of the following is the correct past tense form of the verb \'go\'?\",\"questionType\":1,\"score\":5.0,\"sortOrder\":24,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 9);
INSERT INTO `sys_oper_log` VALUES (1356, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"For most one-syllable adjectives, we add \'-er\' to form the comparative. So \'big\' becomes \'bigger\'. \'Biggest\' is the superlative form, \'more big\' is incorrect structure, and \'biger\' is misspelled (should be \'bigger\').\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":160,\"options\":\"[\\\"biggest\\\",\\\"bigger\\\",\\\"more big\\\",\\\"biger\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"What is the comparative form of the adjective \'big\'?\",\"questionType\":1,\"score\":5.0,\"sortOrder\":25,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 10);
INSERT INTO `sys_oper_log` VALUES (1357, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"The present perfect tense (has/have + past participle) is used for actions that started in the past and continue to the present or have present results. \'She has gone to school\' is correct. The other options are either simple past (\'went\'), present continuous (\'is going\'), or simple present (\'goes\').\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":161,\"options\":\"[\\\"She goes to school yesterday.\\\",\\\"She has gone to school.\\\",\\\"She is going to school.\\\",\\\"She goes to school every day.\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Which sentence correctly uses the present perfect tense?\",\"questionType\":1,\"score\":5.0,\"sortOrder\":26,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 9);
INSERT INTO `sys_oper_log` VALUES (1358, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'安详\'中的\'详\'是\'安静、平和\'的意思，没有错别字。\'祥和\'中的\'祥\'是\'吉祥\'的意思，不是\'详\'；\'祥瑞\'和\'吉祥\'中的\'祥\'都是\'吉祥\'的意思，但\'祥瑞\'中的\'祥\'没有错，而\'吉祥\'中的\'吉\'也没有错。因此，\'安详\'是没有错别字的选项。\",\"answer\":\"A\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":162,\"options\":\"[\\\"安详\\\",\\\"详和\\\",\\\"祥瑞\\\",\\\"吉祥\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"下列词语中，没有错别字的一项是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":27,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 20);
INSERT INTO `sys_oper_log` VALUES (1359, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'名列前茅\'的正确写法是\'名列前茅\'，意思是名次排在前面。\'茅\'指茅草，古代用茅草做旗帜，比喻名次在前。\'矛\'是古代的一种兵器，与成语意思无关。因此，第二个\'名列前茅\'是正确的。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":163,\"options\":\"[\\\"名列前矛\\\",\\\"名列前茅\\\",\\\"名列前矛\\\",\\\"名列前茅\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"下列成语中，没有错别字的一项是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":28,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 8);
INSERT INTO `sys_oper_log` VALUES (1360, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'马虎大意\'中的\'意\'是\'意思、含义\'的意思，表示做事不细心、不认真。\'大义\'通常指\'大道理、正义\'的意思，与句子语境不符。因此，第三个句子中的\'马虎大意\'是正确的写法。\",\"answer\":\"C\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":164,\"options\":\"[\\\"他做事一丝不苟，从不马虎大意\\\",\\\"他做事一丝不苟，从不马虎大义\\\",\\\"他做事一丝不苟，从不马虎大意\\\",\\\"他做事一丝不苟，从不马虎大义\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"下列句子中，没有错别字的一项是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":29,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 8);
INSERT INTO `sys_oper_log` VALUES (1361, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\'你好\'是中文中最常用的问候语，用于初次见面或日常打招呼，表示对对方的礼貌和尊重。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":165,\"options\":\"[\\\"表示惊讶\\\",\\\"表示问候\\\",\\\"表示告别\\\",\\\"表示感谢\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在中文语境中，\'你好\'最常用的含义是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":30,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 7);
INSERT INTO `sys_oper_log` VALUES (1362, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"初次见面时，\'你好\'是最恰当的开场白，表示友好和尊重，而其他选项分别表示告别、感谢和道歉，不适合初次见面的场景。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":166,\"options\":\"[\\\"再见\\\",\\\"你好\\\",\\\"谢谢\\\",\\\"对不起\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"当你第一次见到某人时，最合适的开场白是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":31,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 9);
INSERT INTO `sys_oper_log` VALUES (1363, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在电话通话开始时，使用\'你好\'作为问候语是最礼貌和标准的方式，表示通话开始并准备交流。\'喂\'虽然也常用于电话，但不如\'你好\'正式和礼貌。\",\"answer\":\"B\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":167,\"options\":\"[\\\"喂\\\",\\\"你好\\\",\\\"再见\\\",\\\"谢谢\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在电话通话开始时，通常说的第一句话是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":32,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 8);
INSERT INTO `sys_oper_log` VALUES (1364, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"\",\"answer\":\"\",\"bankId\":1,\"content\":\"Artificial Intelligence in Daily Life\\n\\nArtificial Intelligence (AI) has become an integral part of our daily lives, often without us even realizing it. From the moment we wake up to when we go to bed, AI technology is working behind the scenes to make our lives easier and more efficient.\\n\\nIn the morning, many people rely on AI-powered virtual assistants like Siri or Alexa to check the weather, set reminders, or play music. These assistants use natural language processing to understand and respond to our commands. When we commute, navigation apps like Google Maps use AI to analyze traffic patterns and suggest the fastest routes. \\n\\nAt school, AI tools help students with personalized learning experiences, adapting to individual needs and learning styles. Even entertainment has been transformed by AI, with streaming services using algorithms to recommend movies and shows based on our viewing history.\\n\\nAs AI continues to evolve, it will likely become even more prevalent in our daily routines, offering new ways to improve our quality of life.\",\"difficulty\":2,\"hasSubQuestions\":1,\"id\":168,\"params\":{},\"questionSubList\":[{\"analysis\":\"The main idea of the passage is that AI has become an integral and often unnoticed part of our daily lives. The passage describes how AI is used in various aspects of daily routines, from morning routines to entertainment, without explicitly stating that it\'s replacing humans or that it\'s only in virtual assistants.\",\"answer\":\"B\",\"id\":1776044820767,\"mainId\":168,\"options\":\"[\\\"AI technology is replacing human workers in various industries\\\", \\\"AI has become an invisible but essential part of daily life\\\", \\\"Virtual assistants are the most common form of AI technology\\\", \\\"AI will eventually replace all traditional forms of entertainment\\\"]\",\"params\":{},\"questionText\":\"What is the main idea of the passage?\",\"questionType\":1,\"score\":2,\"sortOrder\":0},{\"analysis\":\"The passage specifically states ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 17);
INSERT INTO `sys_oper_log` VALUES (1365, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"这是一道议论文写作题，要求学生以\\\"青春心向党，奋斗正当时\\\"为题，论述当代青年如何将个人理想与国家发展相结合。参考答案从坚定理想信念、锤炼过硬本领、勇于创新创造、传承红色基因四个方面展开论述，结构清晰，论点明确，论据充分。文章开头点明主题，中间分四个层次论述，结尾总结升华，符合议论文的基本要求。学生写作时应注意论点明确，论据充分，结构合理，语言流畅，同时结合自身实际和社会热点，使文章更具说服力和感染力。\",\"answer\":\"参考答案：青春心向党，奋斗正当时\\n\\n青春，是人生中最美好的年华，也是国家发展最宝贵的资源。当代青年作为国家未来的建设者和接班人，肩负着实现中华民族伟大复兴的历史使命。将个人理想与国家发展相结合，是当代青年应有的责任与担当。\\n\\n首先，坚定理想信念，筑牢思想根基。当代青年要深入学习党的创新理论，树立正确的世界观、人生观、价值观，把个人理想融入国家和民族的事业中。只有坚定理想信念，才能在纷繁复杂的社会环境中保持清醒头脑，找准人生方向，为实现个人价值和国家发展贡献智慧和力量。\\n\\n其次，锤炼过硬本领，提升综合素质。青年时期是学习的黄金时期，当代青年要珍惜时光，刻苦学习，掌握科学文化知识和专业技能，不断提高自身综合素质。同时，要积极参与社会实践，在实践中增长才干，在奋斗中锤炼品格，为将来服务国家、服务社会打下坚实基础。\\n\\n再次，勇于创新创造，积极投身实践。创新是民族进步的灵魂，是国家兴旺发达的不竭动力。当代青年要勇于打破常规，敢于挑战权威，积极投身科技创新、文化创新、制度创新等各个领域，为国家发展注入新的活力。同时，要立足本职岗位，从点滴做起，在平凡的岗位上创造不平凡的业绩，用实际行动诠释奋斗的意义。\\n\\n最后，传承红色基因，弘扬时代精神。当代青年要学习革命先辈的崇高精神，传承红色基因，弘扬以爱国主义为核心的民族精神和以改革创新为核心的时代精神。要将个人理想与国家发展紧密结合起来，在实现中华民族伟大复兴的征程中贡献青春力量，书写无悔于青春、无愧于时代的华彩篇章。\\n\\n总之，青春心向党，奋斗正当时。当代青年要将个人理想与国家发展紧密结合，坚定理想信念，锤炼过硬本领，勇于创新创造，传承红色基因，在实现中华民族伟大复兴的中国梦中放飞青春梦想，书写人生华章。\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":169,\"params\":{},\"questionSubList\":[],\"questionText\":\"请以\\\"青春心向党，奋斗正当时\\\"为题，写一篇800字的议论文，论述当代青年如何将个人理想与国家发展相结合。\",\"questionType\":5,\"score\":5.0,\"sortOrder\":34,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 8);
INSERT INTO `sys_oper_log` VALUES (1366, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"这是一道议论文写作题，要求学生以\\\"青春心向党，奋斗正当时\\\"为题，论述当代青年如何将个人理想与国家发展相结合。参考答案从树立远大理想、勇于担当作为、锤炼品德修养、坚定文化自信四个方面展开论述，结构完整，论点明确，论据充分。文章开头点明主题，中间分四个层次论述，结尾总结升华，符合议论文的基本要求。学生写作时应注意论点明确，论据充分，结构合理，语言流畅，同时结合自身实际和社会热点，使文章更具说服力和感染力。\",\"answer\":\"参考答案：青春心向党，奋斗正当时\\n\\n青春是人生中最美好的时光，也是国家发展最宝贵的资源。当代青年作为国家未来的建设者和接班人，肩负着实现中华民族伟大复兴的历史使命。如何将个人理想与国家发展相结合，是当代青年必须认真思考和践行的重要课题。\\n\\n首先，树立远大理想，明确人生方向。当代青年要树立正确的理想信念，把个人理想与国家前途、民族命运紧密联系起来。只有将个人理想融入国家和民族的事业中，才能在实现个人价值的同时，为国家发展贡献力量。青年时期是树立理想信念的关键时期，要深入学习党的创新理论，增强\\\"四个意识\\\"，坚定\\\"四个自信\\\"，做到\\\"两个维护\\\"，为人生奋斗奠定坚实的思想基础。\\n\\n其次，勇于担当作为，积极投身实践。当代青年要勇于担当时代责任，积极投身国家建设和社会发展。在学习上要刻苦钻研，掌握科学文化知识和专业技能；在工作上要爱岗敬业，精益求精；在社会实践中要勇于探索，敢于创新。只有通过实际行动，才能将个人理想转化为服务国家、服务社会的具体行动，实现个人价值与社会价值的统一。\\n\\n再次，锤炼品德修养，弘扬时代新风。当代青年要自觉践行社会主义核心价值观，锤炼高尚品格，弘扬时代新风。要明大德、守公德、严私德，培养爱国情怀、社会责任感、创新精神和实践能力。同时，要积极参与志愿服务，关心弱势群体，用实际行动传递正能量，展现当代青年的良好形象。\\n\\n最后，坚定文化自信，传承中华优秀文化。当代青年要坚定文化自信，传承和弘扬中华优秀传统文化，吸收借鉴人类文明优秀成果。要树立正确的历史观、民族观、国家观、文化观，增强做中国人的志气、骨气、底气，为实现中华民族伟大复兴提供强大的精神力量。\\n\\n总之，青春心向党，奋斗正当时。当代青年要将个人理想与国家发展紧密结合，树立远大理想，勇于担当作为，锤炼品德修养，坚定文化自信，在实现中华民族伟大复兴的征程中贡献青春力量，书写无愧于时代、无愧于人民的青春华章。\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":170,\"params\":{},\"questionSubList\":[],\"questionText\":\"请以\\\"青春心向党，奋斗正当时\\\"为题，写一篇800字的议论文，论述当代青年如何将个人理想与国家发展相结合。\",\"questionType\":5,\"score\":5.0,\"sortOrder\":35,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 10);
INSERT INTO `sys_oper_log` VALUES (1367, '一级题目', 2, 'com.openstudy.questionMain.controller.QuestionMainController.edit()', 'PUT', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"这是一道议论文写作题，要求学生以\\\"青春心向党，奋斗正当时\\\"为题，论述当代青年如何将个人理想与国家发展相结合。参考答案从坚定理想信念、锤炼过硬本领、勇于创新创造、传承红色基因四个方面展开论述，结构清晰，论点明确，论据充分。文章开头点明主题，中间分四个层次论述，结尾总结升华，符合议论文的基本要求。学生写作时应注意论点明确，论据充分，结构合理，语言流畅，同时结合自身实际和社会热点，使文章更具说服力和感染力。\",\"answer\":\"参考答案：青春心向党，奋斗正当时\\n\\n青春是人生最美好的时光，也是国家发展最宝贵的资源。当代青年作为国家未来的建设者和接班人，肩负着实现中华民族伟大复兴的历史使命。如何将个人理想与国家发展相结合，是当代青年必须认真思考和践行的重要课题。\\n\\n首先，坚定理想信念，筑牢精神支柱。当代青年要深入学习党的创新理论，树立正确的世界观、人生观、价值观，坚定对马克思主义的信仰，对中国特色社会主义的信念，对中华民族伟大复兴中国梦的信心。只有坚定理想信念，才能在纷繁复杂的社会环境中保持清醒头脑，找准人生方向，为实现个人价值和国家发展贡献智慧和力量。\\n\\n其次，锤炼过硬本领，提升综合素质。青年时期是学习的黄金时期，当代青年要珍惜时光，刻苦学习，掌握科学文化知识和专业技能，不断提高自身综合素质。同时，要积极参与社会实践，在实践中增长才干，在奋斗中锤炼品格，为将来服务国家、服务社会打下坚实基础。只有具备过硬的本领，才能在实现个人理想的同时为国家发展贡献力量。\\n\\n再次，勇于创新创造，积极投身实践。创新是民族进步的灵魂，是国家兴旺发达的不竭动力。当代青年要勇于打破常规，敢于挑战权威，积极投身科技创新、文化创新、制度创新等各个领域，为国家发展注入新的活力。同时，要立足本职岗位，从点滴做起，在平凡的岗位上创造不平凡的业绩，用实际行动诠释奋斗的意义。\\n\\n最后，传承红色基因，弘扬时代精神。当代青年要学习革命先辈的崇高精神，传承红色基因，弘扬以爱国主义为核心的民族精神和以改革创新为核心的时代精神。要将个人理想与国家发展紧密结合起来，在实现中华民族伟大复兴的征程中贡献青春力量，书写无悔于青春、无愧于时代的华彩篇章。\\n\\n总之，青春心向党，奋斗正当时。当代青年要将个人理想与国家发展紧密结合，坚定理想信念，锤炼过硬本领，勇于创新创造，传承红色基因，在实现中华民族伟大复兴的中国梦中放飞青春梦想，书写人生华章。\",\"bankId\":1,\"content\":\"\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":171,\"params\":{},\"questionSubList\":[],\"questionText\":\"请以\\\"青春心向党，奋斗正当时\\\"为题，写一篇800字的议论文，论述当代青年如何将个人理想与国家发展相结合。\",\"questionType\":5,\"score\":5.0,\"sortOrder\":36,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:23:49', 11);
INSERT INTO `sys_oper_log` VALUES (1368, '题库主', 1, 'com.openstudy.questionBank.controller.QuestionBankController.createWithReturn()', 'POST', 1, 'admin', '研发部门', '/questionBank/questionBank/createWithReturn', '127.0.0.1', '内网IP', '{\"bankName\":\"Python\",\"coverImage\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"description\":\"11\",\"id\":14,\"isPublic\":0,\"params\":{},\"status\":\"0\",\"subject\":\"Python\",\"totalQuestions\":10,\"userId\":1} ', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"bankName\":\"Python\",\"createTime\":\"2026-04-16 09:28:30\",\"description\":\"11\",\"id\":14,\"isPublic\":0,\"params\":{},\"status\":\"0\",\"subject\":\"Python\",\"totalQuestions\":10,\"userId\":1}}', 0, NULL, '2026-04-16 09:28:30', 66);
INSERT INTO `sys_oper_log` VALUES (1369, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，\'def\'是用于定义函数的关键字，而\'function\'、\'define\'和\'func\'都不是Python的关键字。\",\"answer\":\"B\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":172,\"options\":\"[\\\"function\\\",\\\"def\\\",\\\"define\\\",\\\"func\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"以下哪个是Python中的关键字？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":0,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 12);
INSERT INTO `sys_oper_log` VALUES (1370, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，tuple（元组）是不可变数据类型，一旦创建就不能修改。而list（列表）、dictionary（字典）和set（集合）都是可变的。\",\"answer\":\"C\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":173,\"options\":\"[\\\"list\\\",\\\"dictionary\\\",\\\"tuple\\\",\\\"set\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下哪个数据类型是不可变的？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":1,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 13);
INSERT INTO `sys_oper_log` VALUES (1371, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，\'//\'运算符用于整除运算，返回商的整数部分；\'%\'是取模运算；\'/\'是普通除法；\'**\'是幂运算。\",\"answer\":\"B\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":174,\"options\":\"[\\\"%\\\",\\\"//\\\",\\\"/\\\",\\\"**\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下哪个运算符用于计算整除？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":2,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 12);
INSERT INTO `sys_oper_log` VALUES (1372, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，\'len()\'函数用于获取列表（或其他序列）的长度。\'size()\'和\'length()\'不是Python内置函数，\'count()\'用于统计元素出现次数。\",\"answer\":\"C\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":175,\"options\":\"[\\\"size()\\\",\\\"length()\\\",\\\"len()\\\",\\\"count()\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下哪个函数用于获取列表的长度？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":3,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 11);
INSERT INTO `sys_oper_log` VALUES (1373, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，没有传统的do-while循环，但其他选项中，for循环和while循环都是先判断条件再执行循环体，可能一次都不执行。Python中没有for-else循环的概念。\",\"answer\":\"C\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":176,\"options\":\"[\\\"for循环\\\",\\\"while循环\\\",\\\"do-while循环\\\",\\\"for-else循环\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下哪个循环结构会执行至少一次循环体？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":4,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 17);
INSERT INTO `sys_oper_log` VALUES (1374, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，\'append()\'方法用于向列表末尾添加单个元素；\'add()\'是集合的方法；\'insert()\'用于在指定位置插入元素；\'extend()\'用于将一个列表的所有元素添加到另一个列表中。\",\"answer\":\"A\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":177,\"options\":\"[\\\"append()\\\",\\\"add()\\\",\\\"insert()\\\",\\\"extend()\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下哪个方法用于向列表末尾添加元素？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":5,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 13);
INSERT INTO `sys_oper_log` VALUES (1375, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，\'is\'运算符用于比较两个对象是否引用同一个内存地址；\'==\'和\'!=\'用于比较值是否相等；\'is not\'用于检查两个对象是否引用不同的内存地址。\",\"answer\":\"C\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":178,\"options\":\"[\\\"==\\\",\\\"!=\\\",\\\"is\\\",\\\"is not\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下哪个运算符用于比较两个对象是否引用同一个内存地址？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":6,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 13);
INSERT INTO `sys_oper_log` VALUES (1376, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，\'int()\'函数用于将字符串（或其他类型）转换为整数；\'str_to_int()\'、\'convert()\'和\'parse()\'都不是Python内置函数。\",\"answer\":\"B\",\"bankId\":14,\"content\":\"\",\"createTime\":\"2026-04-16 09:28:30\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":179,\"options\":\"[\\\"str_to_int()\\\",\\\"int()\\\",\\\"convert()\\\",\\\"parse()\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下哪个函数用于将字符串转换为整数？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":7,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-16 09:28:30', 11);
