INSERT INTO `sys_oper_log` VALUES (1477, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Python中，封装主要通过命名约定来实现，使用单下划线前缀(_)表示受保护的成员，使用双下划线(__)表示私有的成员。Python没有像Java那样的private或public关键字。\",\"answer\":\"B\",\"bankId\":15,\"content\":\"\",\"createTime\":\"2026-04-19 18:09:06\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":183,\"options\":\"[\\\"使用private关键字\\\",\\\"使用下划线前缀\\\",\\\"使用public关键字\\\",\\\"使用final关键字\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在Python中，以下哪种方式可以实现封装？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":0,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-19 18:09:07', 45);
INSERT INTO `sys_oper_log` VALUES (1478, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Python不像Java等语言那样有严格的访问控制修饰符，而是通过命名约定(如下划线前缀)和属性访问器(getter/setter)来实现封装。Python的封装更多是一种约定而非强制执行。\",\"answer\":\"C\",\"bankId\":15,\"content\":\"\",\"createTime\":\"2026-04-19 18:09:07\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":184,\"options\":\"[\\\"Python强制实现封装\\\",\\\"Python通过访问控制修饰符实现封装\\\",\\\"Python主要通过命名约定和属性访问器实现封装\\\",\\\"Python不支持封装\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Python中，以下关于封装的说法正确的是？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":1,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-19 18:09:07', 12);
