INSERT INTO `sys_oper_log` VALUES (1608, '用户笔记主，每篇笔记必须归属于一个用户自定义的分类', 1, 'com.openstudy.notes.controller.NoteController.add()', 'POST', 1, 'admin', '研发部门', '/notes/note', '127.0.0.1', '内网IP', '{\"categoryId\":27,\"createTime\":\"2026-04-26 21:10:57\",\"filename\":\"vue测试.md\",\"id\":37,\"isPublic\":1,\"markdownContent\":\"以下是您需要的Vue笔记HTML代码。它是一个交互式笔记卡片展示页面，用于记录和复习Vue.js的核心概念。\\n```html\\n<!DOCTYPE html>\\n<html lang=\\\"zh-CN\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0, user-scalable=yes\\\">\\n    <title>? Vue.js 核心笔记 | 交互式学习卡片</title>\\n    <!-- 引入 Vue 3 CDN -->\\n    <script src=\\\"https://unpkg.com/vue@3/dist/vue.global.js\\\"></script>\\n    <!-- 优雅字体与基础样式 -->\\n    <link href=\\\"https://fonts.googleapis.com/css2?family=Inter:opsz,wght@14..32,400;14..32,500;14..32,600;14..32,700&display=swap\\\" rel=\\\"stylesheet\\\">\\n    <style>\\n        * {\\n            margin: 0;\\n            padding: 0;\\n            box-sizing: border-box;\\n        }\\n\\n        body {\\n            background: linear-gradient(145deg, #f1f5f9 0%, #e6edf4 100%);\\n            font-family: \'Inter\', system-ui, -apple-system, \'Segoe UI\', Roboto, sans-serif;\\n            padding: 2rem 1.5rem;\\n            color: #0a2b3e;\\n        }\\n\\n        /* 主容器 */\\n        .vue-note-app {\\n            max-width: 1400px;\\n            margin: 0 auto;\\n        }\\n\\n        /* 头部区域 */\\n        .hero {\\n            text-align: center;\\n            margin-bottom: 2.5rem;\\n        }\\n        .hero h1 {\\n            font-size: 2.8rem;\\n            font-weight: 700;\\n            background: linear-gradient(135deg, #2c5f8a, #42b883);\\n            background-clip: text;\\n            -webkit-background-clip: text;\\n            color: transparent;\\n            letter-spacing: -0.5px;\\n            display: inline-flex;\\n            align-items: center;\\n            gap: 12px;\\n        }\\n        .hero h1 span {\\n            font-size: 2.8rem;\\n        }\\n        .hero p {\\n            margin-top: 0.75rem;\\n            color: #2c5568;\\n            font-weight: 500;\\n            background: rgba(66, 184, 131, 0.12);\\n            display: inline-block;\\n            padding: 0.3r', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-26 21:10:57', 18);
