INSERT INTO `sys_oper_log` VALUES (1621, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Vue3中，父子组件之间的通信主要通过props(父传子)和emit(子传父)来实现。这是Vue官方推荐的标准通信方式，简单直接且符合Vue的设计理念。Vuex更适合全局状态管理，EventBus在Vue3中已不推荐使用，而localStorage主要用于跨页面或组件的数据持久化。\",\"answer\":\"B\",\"bankId\":16,\"content\":\"\",\"createTime\":\"2026-04-28 15:04:40\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":187,\"options\":\"[\\\"使用Vuex\\\",\\\"使用props和emit\\\",\\\"使用EventBus\\\",\\\"使用localStorage\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在Vue3中，以下哪种方式是父子组件之间最常用的通信方式？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":0,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-28 15:04:40', 44);
INSERT INTO `sys_oper_log` VALUES (1622, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"setup函数是Vue3组合式API的入口点，它是在组件创建之前执行的函数，主要用于初始化组件的状态、方法和计算属性等。在setup中定义的变量和方法需要通过return暴露给模板使用。虽然setup也会在组件实例创建过程中被调用，但它的主要目的是提供组合式API的编程体验。\",\"answer\":\"C\",\"bankId\":16,\"content\":\"\",\"createTime\":\"2026-04-28 15:04:40\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":188,\"options\":\"[\\\"创建组件实例\\\",\\\"初始化组件的props\\\",\\\"组合式API的入口\\\",\\\"处理组件的生命周期\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Vue3中，setup函数的作用是什么？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":1,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-28 15:04:40', 17);
INSERT INTO `sys_oper_log` VALUES (1623, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Vue3中，ref和reactive都是创建响应式数据的方法。ref主要用于基本类型数据的响应式包装，使用方式为ref(0)；reactive主要用于对象或数组的响应式包装。选项B中reactive(0)是错误的用法，reactive应该接收对象或数组。选项C没有使用任何响应式API，选项D中的Ref不是Vue3中的有效API。\",\"answer\":\"A\",\"bankId\":16,\"content\":\"\",\"createTime\":\"2026-04-28 15:04:40\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":189,\"options\":\"[\\\"let count = ref(0)\\\",\\\"let count = reactive(0)\\\",\\\"let count = 0\\\",\\\"let count = new Ref(0)\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在Vue3中，以下哪个选项是响应式数据的正确定义方式？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":2,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-28 15:04:40', 25);
INSERT INTO `sys_oper_log` VALUES (1624, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Vue3的Composition API相比Options API有多个优势：1) 代码更简洁，相关逻辑可以组织在一起；2) 性能更好，减少了不必要的响应式追踪；3) 逻辑复用更方便，可以将可复用的逻辑抽取为组合函数(Composables)。这些优势使得Composition API在处理复杂组件时更具优势。\",\"answer\":\"D\",\"bankId\":16,\"content\":\"\",\"createTime\":\"2026-04-28 15:04:40\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":190,\"options\":\"[\\\"代码更简洁\\\",\\\"性能更好\\\",\\\"逻辑复用更方便\\\",\\\"以上都是\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Vue3中的Composition API相比Options API的主要优势是什么？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":3,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-28 15:04:40', 14);
INSERT INTO `sys_oper_log` VALUES (1625, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"在Vue3中，v-if是条件渲染指令，根据表达式的值来决定是否渲染元素。v-show也是条件渲染，但它只是切换CSS的display属性，元素始终存在于DOM中。v-for用于列表渲染，v-model用于表单双向绑定。虽然v-show也能实现条件显示，但v-if是真正的条件渲染，当条件为false时，元素不会被渲染到DOM中。\",\"answer\":\"B\",\"bankId\":16,\"content\":\"\",\"createTime\":\"2026-04-28 15:04:40\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":191,\"options\":\"[\\\"v-show\\\",\\\"v-if\\\",\\\"v-for\\\",\\\"v-model\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在Vue3中，以下哪个指令用于条件渲染？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":4,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-28 15:04:40', 19);
