INSERT INTO `sys_oper_log` VALUES (1753, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Java语言由Sun Microsystems公司于1995年正式发布，因此正确答案是1995年。\",\"answer\":\"B\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:42\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":198,\"options\":\"[\\\"1991\\\",\\\"1995\\\",\\\"1998\\\",\\\"2000\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Java语言的诞生产生于哪一年？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":0,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:42', 26);
INSERT INTO `sys_oper_log` VALUES (1754, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Java具有三大面向对象特性：封装、继承和多态，因此所有选项都是Java的面向对象特性。\",\"answer\":\"D\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:42\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":199,\"options\":\"[\\\"继承\\\",\\\"封装\\\",\\\"多态\\\",\\\"所有以上\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"以下哪个是Java的面向对象特性？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":1,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:42', 13);
INSERT INTO `sys_oper_log` VALUES (1755, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"final关键字用于修饰类、方法和变量，当用final修饰类时，表示该类不能被继承。\",\"answer\":\"B\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:42\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":200,\"options\":\"[\\\"static\\\",\\\"final\\\",\\\"abstract\\\",\\\"private\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"下面哪个关键字用于让类不能被继承？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":2,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:42', 12);
INSERT INTO `sys_oper_log` VALUES (1756, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Java不支持类之间的多继承，一个类只能直接继承一个父类，但可以通过实现多个接口来达到类似多继承的效果。\",\"answer\":\"A\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:42\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":201,\"options\":\"[\\\"选项A\\\",\\\"选项B\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Java支持多继承（类之间）。\",\"questionType\":1,\"score\":5.0,\"sortOrder\":3,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:43', 14);
INSERT INTO `sys_oper_log` VALUES (1757, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"JVM(Java虚拟机)是Java跨平台的核心，Java代码被编译成字节码，可以在任何安装了JVM的平台上运行。\",\"answer\":\"A\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:43\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":202,\"options\":\"[\\\"选项A\\\",\\\"选项B\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"JVM是跨平台的核心。\",\"questionType\":1,\"score\":5.0,\"sortOrder\":4,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:43', 15);
INSERT INTO `sys_oper_log` VALUES (1758, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Java程序的入口方法是main方法，其签名必须是public static void main(String[] args)，JVM通过这个方法启动应用程序。\",\"answer\":\"A\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:43\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":203,\"options\":\"[\\\"选项A\\\",\\\"选项B\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"public static void main(String[] args)是Java程序的入口方法。\",\"questionType\":1,\"score\":5.0,\"sortOrder\":5,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:43', 15);
INSERT INTO `sys_oper_log` VALUES (1759, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"StringBuffer是线程安全的，而StringBuilder不是线程安全的。StringBuilder在性能上通常优于StringBuffer，但不保证线程安全。\",\"answer\":\"A\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:43\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":204,\"options\":\"[\\\"选项A\\\",\\\"选项B\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"StringBuffer和StringBuilder都是线程安全的。\",\"questionType\":1,\"score\":5.0,\"sortOrder\":6,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:43', 14);
INSERT INTO `sys_oper_log` VALUES (1760, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"从Java 9开始，接口可以包含私有方法，这些方法只能在接口内部使用，提高了代码的组织性和复用性。\",\"answer\":\"A\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:43\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":205,\"options\":\"[\\\"选项A\\\",\\\"选项B\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"在Java 8之后，接口中可以包含私有方法（private methods）。\",\"questionType\":1,\"score\":5.0,\"sortOrder\":7,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:43', 13);
INSERT INTO `sys_oper_log` VALUES (1761, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"final修饰的类不能被继承，同时final修饰的方法也不能被重写，这是final关键字的基本特性。\",\"answer\":\"A\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:43\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":206,\"options\":\"[\\\"选项A\\\",\\\"选项B\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"final修饰的类不能被继承，但final修饰的方法可以被重写。\",\"questionType\":1,\"score\":5.0,\"sortOrder\":8,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:43', 10);
INSERT INTO `sys_oper_log` VALUES (1762, '一级题目', 1, 'com.openstudy.questionMain.controller.QuestionMainController.add()', 'POST', 1, 'admin', '研发部门', '/questionMain/questionMain', '127.0.0.1', '内网IP', '{\"analysis\":\"Optional类是Java 8引入的容器类，主要用于避免空指针异常，提供了一种更优雅的方式来处理可能为null的值。\",\"answer\":\"B\",\"bankId\":17,\"content\":\"\",\"createTime\":\"2026-05-04 01:31:43\",\"difficulty\":2,\"hasSubQuestions\":0,\"id\":207,\"options\":\"[\\\"提高代码执行速度\\\",\\\"避免空指针异常(NullPointerException)\\\",\\\"替代所有的null检查\\\",\\\"优化内存分配\\\"]\",\"params\":{},\"questionSubList\":[],\"questionText\":\"Optional类主要用于解决什么问题？\",\"questionType\":1,\"score\":5.0,\"sortOrder\":9,\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-04 01:31:43', 11);
