INSERT INTO `sys_oper_log` VALUES (1768, '用户笔记主，每篇笔记必须归属于一个用户自定义的分类', 2, 'com.openstudy.notes.controller.NoteController.edit()', 'PUT', 1, 'admin', '研发部门', '/notes/note', '127.0.0.1', '内网IP', '{\"categoryId\":29,\"id\":51,\"isPublic\":1,\"markdownContent\":\"# CSS Flexbox 布局完全指南\\n\\n## 容器属性\\n\\n```css\\n.container {\\n    display: flex;\\n    justify-content: center;\\n    align-items: center;\\n    gap: 16px;\\n    flex-wrap: wrap;\\n}\\n```\\n\\n## 子元素属性\\n\\n```css\\n.item {\\n    flex: 1;\\n    min-width: 200px;\\n    order: -1;\\n}\\n```\\n\\n## 常见布局\\n\\n### 水平居中\\n```css\\ndisplay: flex;\\njustify-content: center;\\n```\\n\\n### 垂直居中\\n```css\\ndisplay: flex;\\nalign-items: center;\\nmin-height: 100vh;\\n```\\n\\n### 两端对齐\\n```css\\ndisplay: flex;\\njustify-content: space-between;\\n```\\n\\n> 熟练掌握 Flexbox，可以抛弃大部分 float 和 position 的 hack 写法。\",\"params\":{},\"publicSectionId\":3,\"tags\":\"CSS,Flexbox,布局,前端\",\"title\":\"CSS Flexbox 布局完全指南\",\"updateTime\":\"2026-05-05 17:12:09\",\"userId\":1,\"wordCount\":402} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-05-05 17:12:09', 20);
